(385401,42823,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... durch das flache Wasser, als plötzlich hinter ihm ein Delfin herausschoss!'::text,'schwamm'::text,'schwamm'::text,'ist geschwommen'::text,'Er schwamm durch das flache Wasser, als plötzlich hinter ihm ein Delfin herausschoss!'::text),
(385405,42823,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... мілкою водою, коли раптом позаду нього вистрибнув дельфін!'::text,'плив'::text,'проплив'::text,'проплив'::text,'Він плив мілкою водою, коли раптом позаду нього вистрибнув дельфін!'::text),
