(385406,42823,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkasından aniden bir yunus fırladığında o sığ suda ...!'::text,'yüzüyordu'::text,'yüzdü'::text,'yüzdü'::text,'Arkasından aniden bir yunus fırladığında o sığ suda yüzüyordu!'::text),
(385407,42823,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a sekély vízben ..., amikor hirtelen egy delfin ugrott ki mögötte!'::text,'úszott'::text,'átúszott'::text,'átúszott'::text,'Ő a sekély vízben úszott, amikor hirtelen egy delfin ugrott ki mögötte!'::text),
(385482,42832,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig mutig: Er schwimmt Kraul, ... das Wasser so flach ist, dass man darin stehen kann.'::text,'obwohl'::text,'trotz'::text,'wegen'::text,'Eindeutig mutig: Er schwimmt Kraul, obwohl das Wasser so flach ist, dass man darin stehen kann.'::text),
