(385485,42832,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente valiente: él nada a crol ... el agua es tan poco profunda que se puede estar de pie.'::text,'aunque'::text,'a pesar de'::text,'debido a'::text,'Claramente valiente: él nada a crol aunque el agua es tan poco profunda que se puede estar de pie.'::text),
(385484,42832,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement courageux : il nage le crawl ... l''eau est assez peu profonde pour qu''on y ait pied.'::text,'même si'::text,'malgré'::text,'à cause de'::text,'Clairement courageux : il nage le crawl même si l''eau est assez peu profonde pour qu''on y ait pied.'::text),
(385487,42832,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki cesur: su içinde ayakta durulacak kadar sığ ... o serbest stil yüzüyor.'::text,'olmasına rağmen'::text,'rağmen'::text,'yüzünden'::text,'Belli ki cesur: su içinde ayakta durulacak kadar sığ olmasına rağmen o serbest stil yüzüyor.'::text),
(385488,42832,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen bátor: ő gyorsúszásban úszik, ... a víz olyan sekély, hogy meg lehet állni benne.'::text,'pedig'::text,'ellenére'::text,'miatt'::text,'Egyértelműen bátor: ő gyorsúszásban úszik, pedig a víz olyan sekély, hogy meg lehet állni benne.'::text),
(394842,43872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, ich hab gehört, sie ... schon den ganzen Nachmittag diesen Golfschläger.'::text,'schwingt'::text,'schwingt'::text,'schwingt'::text,'Warte, ich hab gehört, sie schwingt schon den ganzen Nachmittag diesen Golfschläger.'::text),
(394846,43872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, я чула, що вона ... цією ключкою для гольфу все пообіддя.'::text,'махає'::text,'махає'::text,'махає'::text,'Стоп, я чула, що вона махає цією ключкою для гольфу все пообіддя.'::text),
(394845,43872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, oí que ella ... ese palo de golf toda la tarde.'::text,'ha estado balanceando'::text,'está balanceando'::text,'balancea'::text,'Espera, oí que ella ha estado balanceando ese palo de golf toda la tarde.'::text),
(394844,43872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu dire qu''elle ... ce club de golf depuis tout l''après-midi.'::text,'balance'::text,'balance'::text,'balance'::text,'Attends, j''ai entendu dire qu''elle balance ce club de golf depuis tout l''après-midi.'::text),
(394847,43872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki o bütün öğleden sonra o golf sopasını ...'::text,'sallıyormuş'::text,'sallıyormuş'::text,'sallarmış'::text,'Dur, duydum ki o bütün öğleden sonra o golf sopasını sallıyormuş.'::text),
(394848,43872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt hallottam, hogy ő egész délután ... azt a golfütőt.'::text,'lengeti'::text,'lengeti'::text,'lengeti'::text,'Várj, azt hallottam, hogy ő egész délután lengeti azt a golfütőt.'::text),
(395103,43901,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da er den Schalter ..., ist der ganze Raum jetzt hell.'::text,'gedrückt hat'::text,'die ganze Zeit drückt'::text,'drückt'::text,'Da er den Schalter gedrückt hat, ist der ganze Raum jetzt hell.'::text),
(395107,43901,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... вимикач, тож уся кімната тепер світла.'::text,'натиснув'::text,'натискав'::text,'натискає'::text,'Він натиснув вимикач, тож уся кімната тепер світла.'::text),
(395106,43901,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... el interruptor, así que toda la habitación está iluminada ahora.'::text,'ha pulsado'::text,'ha estado pulsando'::text,'pulsa'::text,'Él ha pulsado el interruptor, así que toda la habitación está iluminada ahora.'::text),
(395105,43901,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur l''interrupteur, donc toute la pièce est éclairée maintenant.'::text,'a appuyé'::text,'appuie depuis un moment'::text,'appuie'::text,'Il a appuyé sur l''interrupteur, donc toute la pièce est éclairée maintenant.'::text),
(395108,43901,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O düğmeye ..., o yüzden bütün oda artık aydınlık.'::text,'bastı'::text,'basıp duruyor'::text,'basıyor'::text,'O düğmeye bastı, o yüzden bütün oda artık aydınlık.'::text),
(395109,43901,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a kapcsolót, így most az egész szoba világos.'::text,'megnyomta'::text,'nyomkodta'::text,'nyomja'::text,'Ő megnyomta a kapcsolót, így most az egész szoba világos.'::text),
(395166,43908,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Wohnung ... schon so drei Stunden dunkel, als er den Schalter drückte.'::text,'war'::text,'ist'::text,'ist'::text,'Bro, die Wohnung war schon so drei Stunden dunkel, als er den Schalter drückte.'::text),
(395170,43908,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, квартира ... темна вже десь три години, коли він клацнув вимикачем.'::text,'була'::text,'є'::text,'є'::text,'Бро, квартира була темна вже десь три години, коли він клацнув вимикачем.'::text),
(395169,43908,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el piso ... a oscuras como tres horas ya cuando le dio al interruptor.'::text,'llevaba'::text,'lleva'::text,'está'::text,'Bro, el piso llevaba a oscuras como tres horas ya cuando le dio al interruptor.'::text),
(395168,43908,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''appart ... plongé dans le noir depuis genre trois heures quand il a appuyé sur l''interrupteur.'::text,'était'::text,'est'::text,'est'::text,'Frère, l''appart était plongé dans le noir depuis genre trois heures quand il a appuyé sur l''interrupteur.'::text),
(395171,43908,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, düğmeye bastığında daire üç saattir falan karanlık ...'::text,'kalmıştı'::text,'kaldı'::text,'kalıyor'::text,'Kanka, düğmeye bastığında daire üç saattir falan karanlık kalmıştı.'::text),
(395172,43908,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a lakás már vagy három órája sötét ..., amikor felkapcsolta a villanyt.'::text,'volt'::text,NULL::text,NULL::text,'Tesó, a lakás már vagy három órája sötét volt, amikor felkapcsolta a villanyt.'::text),
(330177,36687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Schneider die weiten Ärmel sieht, beschließt er sofort, dass er sie auch ...'::text,'ändern wird'::text,'ändern wird'::text,'ändert'::text,'Als der Schneider die weiten Ärmel sieht, beschließt er sofort, dass er sie auch ändern wird.'::text),
(330181,36687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Побачивши вільні рукави, кравець одразу вирішує, що він їх теж ...'::text,'перешиє'::text,'перешиватиме'::text,'перешиває'::text,'Побачивши вільні рукави, кравець одразу вирішує, що він їх теж перешиє.'::text),
