(395243,43916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, kimse almazsa kutu bütün hafta orada ..., cidden.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Yok kanka, kimse almazsa kutu bütün hafta orada kalacak, cidden.'::text),
