(332319,36925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du liebst diese Avenue, und ich ..., ehrlich, dein Geschmack ist ikonisch.'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Du liebst diese Avenue, und ich auch, ehrlich, dein Geschmack ist ikonisch.'::text),
(332323,36925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти любиш цей проспект, і я ..., чесно, твій смак — іконічний.'::text,'теж'::text,'теж'::text,'теж ні'::text,'Ти любиш цей проспект, і я теж, чесно, твій смак — іконічний.'::text),
(332322,36925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú amas esta avenida, y ... yo. Sinceramente, tu gusto es icónico.'::text,'también'::text,'también'::text,'tampoco'::text,'Tú amas esta avenida, y también yo. Sinceramente, tu gusto es icónico.'::text),
(332321,36925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu adores cette avenue, et moi ... ; franchement, ton goût est iconique.'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Tu adores cette avenue, et moi aussi ; franchement, ton goût est iconique.'::text),
(332324,36925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bu caddeyi seviyorsun, ben de ...; açıkçası tarzın efsane.'::text,'seviyorum'::text,'seviyorum'::text,'sevmiyorum'::text,'Sen bu caddeyi seviyorsun, ben de seviyorum; açıkçası tarzın efsane.'::text),
(332325,36925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te imádod ezt a sugárutat, és én ..., őszintén, ikonikus az ízlésed.'::text,'is'::text,'is'::text,'sem'::text,'Te imádod ezt a sugárutat, és én is, őszintén, ikonikus az ízlésed.'::text),
(332328,36926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich beeindruckend: Bis zum Ende dieser Avenue wirst du zehn Taxis ...'::text,'herangewinkt haben'::text,'heranwinken'::text,'heranwinken'::text,'Ehrlich beeindruckend: Bis zum Ende dieser Avenue wirst du zehn Taxis herangewinkt haben.'::text),
(332332,36926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, вражає: до кінця цього проспекту ти ... десять таксі.'::text,'зупиниш'::text,'зупинятимеш'::text,'зупиняєш'::text,'Чесно, вражає: до кінця цього проспекту ти зупиниш десять таксі.'::text),
