(339182,37687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Takım şampiyon olmasaydı, onlar takım arkadaşlarını bu kadar yükseğe ...'::text,'kaldırmazlardı'::text,'kaldırmayacaklar'::text,'kaldırmıyorlar'::text,'Takım şampiyon olmasaydı, onlar takım arkadaşlarını bu kadar yükseğe kaldırmazlardı.'::text),
(339183,37687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a csapat nem lenne bajnok, ők ... ilyen magasra a csapattársukat.'::text,'nem emelnék'::text,'nem fogják emelni'::text,'nem emelik'::text,'Ha a csapat nem lenne bajnok, ők nem emelnék ilyen magasra a csapattársukat.'::text),
(402789,44755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der Sieg war angeblich riesig, ...?'::text,'war er nicht?'::text,'nicht wahr?'::text,'war er?'::text,'Mädel, der Sieg war angeblich riesig, war er nicht?'::text),
(402793,44755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, та перемога була величезна, ...?'::text,'чи не так?'::text,'правда?'::text,'була?'::text,'Подруго, кажуть, та перемога була величезна, чи не так?'::text),
(402792,44755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer esa victoria fue enorme, ¿...?'::text,'no'::text,'verdad'::text,'sí'::text,'Amiga, al parecer esa victoria fue enorme, ¿no?'::text),
(402791,44755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment cette victoire était énorme, ... ?'::text,'n''est-ce pas'::text,'non'::text,'c''est ça'::text,'Meuf, apparemment cette victoire était énorme, n''est-ce pas ?'::text),
(402794,44755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, o galibiyet baya büyükmüş, ...?'::text,'değil mi?'::text,'değil mi?'::text,'öyle mi?'::text,'Kızım, o galibiyet baya büyükmüş, değil mi?'::text),
(402795,44755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az a győzelem óriási volt, ...?'::text,'nem igaz?'::text,'nem?'::text,'igaz?'::text,'Csajszi, állítólag az a győzelem óriási volt, nem igaz?'::text),
(402861,44763,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das andere Team weigerte sich, den Sieg ...! Totaler Verrat!'::text,'anzuerkennen'::text,'Anerkennen'::text,'anerkennen'::text,'Das andere Team weigerte sich, den Sieg anzuerkennen! Totaler Verrat!'::text),
(402865,44763,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інша команда відмовилася ... перемогу! Повна зрада!'::text,'визнати'::text,'визнання'::text,'визнати'::text,'Інша команда відмовилася визнати перемогу! Повна зрада!'::text),
(402864,44763,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El otro equipo se negó a ... la victoria! ¡Traición total!'::text,'aceptar'::text,'aceptando'::text,'aceptar'::text,'¡El otro equipo se negó a aceptar la victoria! ¡Traición total!'::text),
(402863,44763,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''autre équipe a refusé ... la victoire ! Trahison totale !'::text,'d''accepter'::text,'acceptant'::text,'accepter'::text,'L''autre équipe a refusé d''accepter la victoire ! Trahison totale !'::text),
(402866,44763,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diğer takım galibiyeti ... reddetti! Tam bir ihanet!'::text,'kabul etmeyi'::text,'kabul ederek'::text,'kabul etmek'::text,'Diğer takım galibiyeti kabul etmeyi reddetti! Tam bir ihanet!'::text),
(402867,44763,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A másik csapat nem volt hajlandó ... a győzelmet! Teljes árulás!'::text,'elismerni'::text,'elismerve'::text,'elismer'::text,'A másik csapat nem volt hajlandó elismerni a győzelmet! Teljes árulás!'::text),
(395778,43976,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stark: Du ... seit fünf Minuten Papier und bist immer noch so ruhig.'::text,'zerreißt'::text,'zerreißt'::text,'zerreißt'::text,'Stark: Du zerreißt seit fünf Minuten Papier und bist immer noch so ruhig.'::text),
(395782,43976,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ефектно: ти вже п''ять хвилин ... папір і досі така спокійна.'::text,'рвеш'::text,'рвеш'::text,'рвеш'::text,'Ефектно: ти вже п''ять хвилин рвеш папір і досі така спокійна.'::text),
(395781,43976,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con estilo: tú ... papel durante cinco minutos y sigues tan tranquila.'::text,'has estado rompiendo'::text,'estás rompiendo'::text,'rompes'::text,'Con estilo: tú has estado rompiendo papel durante cinco minutos y sigues tan tranquila.'::text),
(395780,43976,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stylé : tu ... du papier depuis cinq minutes et tu es toujours aussi calme.'::text,'déchires'::text,'déchires'::text,'déchires'::text,'Stylé : tu déchires du papier depuis cinq minutes et tu es toujours aussi calme.'::text),
(395783,43976,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tarz: sen beş dakikadır kâğıt ... ve hâlâ çok sakinsin.'::text,'yırtıyorsun'::text,'yırtıyorsun'::text,'yırtarsın'::text,'Tarz: sen beş dakikadır kâğıt yırtıyorsun ve hâlâ çok sakinsin.'::text),
(395784,43976,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Menő: te öt perce ... a papírt, és még mindig ilyen nyugodt vagy.'::text,'téped'::text,'téped'::text,'téped'::text,'Menő: te öt perce téped a papírt, és még mindig ilyen nyugodt vagy.'::text),
(395850,43984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, es heißt, dass sie den Vertrag ..., bevor jemand ein Wort sagen konnte.'::text,'zerrissen hatte'::text,'zerrissen hat'::text,'zerreißt'::text,'Omg, es heißt, dass sie den Vertrag zerrissen hatte, bevor jemand ein Wort sagen konnte.'::text),
(395854,43984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, кажуть, вона ... контракт, перш ніж хтось встиг сказати хоч слово.'::text,'розірвала'::text,'розірвала'::text,'рве'::text,'Боже, кажуть, вона розірвала контракт, перш ніж хтось встиг сказати хоч слово.'::text),
(395853,43984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, dicen que ella ... el contrato antes de que nadie pudiera decir nada.'::text,'había roto'::text,'ha roto'::text,'está rompiendo'::text,'Dios, dicen que ella había roto el contrato antes de que nadie pudiera decir nada.'::text),
(395852,43984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, on dit qu''elle ... le contrat avant que quiconque puisse dire un mot.'::text,'avait déchiré'::text,'a déchiré'::text,'déchire'::text,'Omg, on dit qu''elle avait déchiré le contrat avant que quiconque puisse dire un mot.'::text),
(395855,43984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman tanrım, dediklerine göre o, kimse tek kelime edemeden sözleşmeyi ...'::text,'yırtmıştı'::text,'yırtmış'::text,'yırtıyor'::text,'Aman tanrım, dediklerine göre o, kimse tek kelime edemeden sözleşmeyi yırtmıştı.'::text),
(395856,43984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt mondják, ő ... a szerződést, mielőtt bárki egy szót is szólhatott volna.'::text,'széttépte'::text,'széttépte'::text,'tépi'::text,'Úristen, azt mondják, ő széttépte a szerződést, mielőtt bárki egy szót is szólhatott volna.'::text),
(389370,43264,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... gerade einen traurigen Film, als die Trauer zu viel wurde, und ehrlich, so nachvollziehbar.'::text,'sahst'::text,'sahst'::text,'siehst'::text,'Du sahst gerade einen traurigen Film, als die Trauer zu viel wurde, und ehrlich, so nachvollziehbar.'::text),
(389374,43264,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... сумний фільм, коли смуток став нестерпним, і, чесно, це так знайомо.'::text,'дивилася'::text,'подивилася'::text,'дивишся'::text,'Ти дивилася сумний фільм, коли смуток став нестерпним, і, чесно, це так знайомо.'::text),
(389373,43264,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... una película triste cuando la tristeza se volvió demasiado, y, sinceramente, qué identificable.'::text,'estabas viendo'::text,'viste'::text,'estás viendo'::text,'Tú estabas viendo una película triste cuando la tristeza se volvió demasiado, y, sinceramente, qué identificable.'::text),
(389372,43264,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... un film triste quand le chagrin est devenu trop lourd, et franchement, je me reconnais trop.'::text,'regardais'::text,'as regardé'::text,'regardes'::text,'Tu regardais un film triste quand le chagrin est devenu trop lourd, et franchement, je me reconnais trop.'::text),
(389375,43264,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hüzün fazla gelince sen hüzünlü bir film ..., ve açıkçası çok tanıdık.'::text,'izliyordun'::text,'izledin'::text,'izliyorsun'::text,'Hüzün fazla gelince sen hüzünlü bir film izliyordun, ve açıkçası çok tanıdık.'::text),
(389376,43264,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te ... egy szomorú filmet, amikor a bánat túl sok lett, és őszintén, annyira átérzem.'::text,'néztél'::text,'megnéztél'::text,'nézel'::text,'Te néztél egy szomorú filmet, amikor a bánat túl sok lett, és őszintén, annyira átérzem.'::text),
(389460,43274,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ihr zwei teilt ... eines traurigen Films wie echte Freundinnen.'::text,'die Trauer'::text,'eine Trauer'::text,'Trauer'::text,'Ehrlich, ihr zwei teilt die Trauer eines traurigen Films wie echte Freundinnen.'::text),
(389464,43274,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ви дві ділите ... сумного фільму, як справжні подруги.'::text,'смуток'::text,'смуток'::text,'смуток'::text,'Чесно, ви дві ділите смуток сумного фільму, як справжні подруги.'::text),
(389463,43274,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, vosotras dos compartís ... de una película triste como verdaderas amigas.'::text,'la tristeza'::text,'una tristeza'::text,'tristeza'::text,'Sinceramente, vosotras dos compartís la tristeza de una película triste como verdaderas amigas.'::text),
(389462,43274,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, vous deux partagez ... d''un film triste comme de vraies amies.'::text,'le chagrin'::text,'un chagrin'::text,'chagrin'::text,'Franchement, vous deux partagez le chagrin d''un film triste comme de vraies amies.'::text),
(389465,43274,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası siz ikiniz hüzünlü bir filmin ... gerçek dostlar gibi paylaşıyorsunuz.'::text,'hüznünü'::text,'bir hüznünü'::text,'hüznünü'::text,'Açıkçası siz ikiniz hüzünlü bir filmin hüznünü gerçek dostlar gibi paylaşıyorsunuz.'::text),
(389466,43274,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ti ketten úgy osztoztok ... egy szomorú film miatt, mint igazi barátnők.'::text,'a bánaton'::text,'egy bánaton'::text,'bánaton'::text,'Őszintén, ti ketten úgy osztoztok a bánaton egy szomorú film miatt, mint igazi barátnők.'::text),
(372162,41352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, sie hat sich geweigert, ..., bis sie die Tüte zurückhatte.'::text,'sich hinzusetzen'::text,'Hinsetzen'::text,'hinsetzen'::text,'Hör zu, ich hab gehört, sie hat sich geweigert, sich hinzusetzen, bis sie die Tüte zurückhatte.'::text),
(372166,41352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вона відмовилася ..., поки не отримала ту пачку назад.'::text,'сісти'::text,'сідання'::text,'сісти'::text,'Слухай, я чула, що вона відмовилася сісти, поки не отримала ту пачку назад.'::text),
(372165,41352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, oí que ella se negó a ... hasta que recuperó ese paquete.'::text,'sentarse'::text,'sentándose'::text,'sentarse'::text,'Escucha, oí que ella se negó a sentarse hasta que recuperó ese paquete.'::text),
(372164,41352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''elle a refusé ... jusqu''à ce qu''elle récupère ce paquet.'::text,'de s''asseoir'::text,'s''asseyant'::text,'s''asseoir'::text,'Écoute, j''ai entendu dire qu''elle a refusé de s''asseoir jusqu''à ce qu''elle récupère ce paquet.'::text),
(372167,41352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki o, o paketi geri alana kadar ... reddetmiş.'::text,'oturmayı'::text,'oturmak'::text,'otur'::text,'Dinle, duydum ki o, o paketi geri alana kadar oturmayı reddetmiş.'::text),
(372168,41352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy ő nem volt hajlandó ..., amíg vissza nem kapta azt a zacskót.'::text,'leülni'::text,'leülve'::text,'leül'::text,'Figyelj, azt hallottam, hogy ő nem volt hajlandó leülni, amíg vissza nem kapta azt a zacskót.'::text),
(372189,41355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... dich zwei ganze Minuten nach der Tüte, bevor er aufgab. Respekt.'::text,'strecktest'::text,'streckst'::text,'strecktest'::text,'Ehrlich, du strecktest dich zwei ganze Minuten nach der Tüte, bevor er aufgab. Respekt.'::text),
(372193,41355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... по ту пачку цілі дві хвилини, поки він не здався. Респект.'::text,'тягнулася'::text,'тягнешся'::text,'тягнулася'::text,'Чесно, ти тягнулася по ту пачку цілі дві хвилини, поки він не здався. Респект.'::text),
(372192,41355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... ese paquete durante dos minutos enteros antes de que él se rindiera. Respeto.'::text,'habías estado intentando alcanzar'::text,'has estado intentando alcanzar'::text,'estabas intentando alcanzar'::text,'Sinceramente, tú habías estado intentando alcanzar ese paquete durante dos minutos enteros antes de que él se rindiera. Respeto.'::text),
(372191,41355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... vers ce paquet pendant deux bonnes minutes avant qu''il abandonne. Respect.'::text,'avais tendu la main'::text,'tends la main'::text,'tendais la main'::text,'Franchement, tu avais tendu la main vers ce paquet pendant deux bonnes minutes avant qu''il abandonne. Respect.'::text),
(372194,41355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen, o pes edene kadar iki koca dakika o pakete ...; saygı.'::text,'uzanmıştın'::text,'uzanıyorsun'::text,'uzanıyordun'::text,'Açıkçası sen, o pes edene kadar iki koca dakika o pakete uzanmıştın; saygı.'::text),
(372195,41355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te két teljes percig ... azért a zacskóért, mielőtt feladta. Respekt.'::text,'nyújtózkodtál'::text,'nyújtózkodsz'::text,'nyújtózkodtál'::text,'Őszintén, te két teljes percig nyújtózkodtál azért a zacskóért, mielőtt feladta. Respekt.'::text),
(348420,38714,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... jedem Griff aus, bis sie ihn am Sofa in die Enge trieb.'::text,'wich'::text,'wurde ausgewichen'::text,'ausweichend'::text,'Er wich jedem Griff aus, bis sie ihn am Sofa in die Enge trieb.'::text),
(348424,38714,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... від кожної спроби схопити, поки вона не загнала його в кут біля дивана.'::text,'ухилявся'::text,'був ухилений'::text,'ухиляючись'::text,'Він ухилявся від кожної спроби схопити, поки вона не загнала його в кут біля дивана.'::text),
(348423,38714,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... cada intento de agarrarlo hasta que ella lo acorraló junto al sofá.'::text,'esquivó'::text,'fue esquivado'::text,'esquivando'::text,'Él esquivó cada intento de agarrarlo hasta que ella lo acorraló junto al sofá.'::text),
(348422,38714,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... chaque tentative jusqu''à ce qu''elle le coince près du canapé.'::text,'a esquivé'::text,'a été esquivé'::text,'esquivant'::text,'Il a esquivé chaque tentative jusqu''à ce qu''elle le coince près du canapé.'::text),
(348425,38714,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kız onu kanepenin yanında köşeye sıkıştırana kadar her kapma hamlesinden ...'::text,'kaçtı'::text,'kaçıldı'::text,'kaçarak'::text,'O, kız onu kanepenin yanında köşeye sıkıştırana kadar her kapma hamlesinden kaçtı.'::text),
(348426,38714,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden kapás elől ..., amíg a lány sarokba nem szorította a kanapénál.'::text,'kitért'::text,'ki lett térve'::text,'kitérve'::text,'Ő minden kapás elől kitért, amíg a lány sarokba nem szorította a kanapénál.'::text),
(348447,38717,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis sie ihn in die Ecke drängt, wird er ihr so zwanzigmal ..., echt.'::text,'ausgewichen sein'::text,'ausweichen'::text,'ausweichen'::text,'Bro, bis sie ihn in die Ecke drängt, wird er ihr so zwanzigmal ausgewichen sein, echt.'::text),
(348451,38717,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки вона зажене його в кут, він ... від неї разів двадцять, реально.'::text,'ухилиться'::text,'ухилятиметься'::text,'ухиляється'::text,'Бро, поки вона зажене його в кут, він ухилиться від неї разів двадцять, реально.'::text),
(348450,38717,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando ella lo acorrale, él la ... como veinte veces, en serio.'::text,'habrá esquivado'::text,'esquivará'::text,'esquiva'::text,'Bro, para cuando ella lo acorrale, él la habrá esquivado como veinte veces, en serio.'::text),
(348449,38717,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, le temps qu''elle le coince, il ... genre vingt fois, sérieux.'::text,'l''aura esquivée'::text,'l''esquivera'::text,'l''esquive'::text,'Frère, le temps qu''elle le coince, il l''aura esquivée genre vingt fois, sérieux.'::text),
(348452,38717,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kız onu köşeye sıkıştırana kadar o ondan yirmi kere falan ..., cidden.'::text,'kaçmış olacak'::text,'kaçacak'::text,'kaçıyor'::text,'Kanka, kız onu köşeye sıkıştırana kadar o ondan yirmi kere falan kaçmış olacak, cidden.'::text),
(348453,38717,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire sarokba szorítja, ő vagy hússzor ... előle, komolyan.'::text,'már kitért'::text,'ki fog térni'::text,'kitér'::text,'Tesó, mire sarokba szorítja, ő vagy hússzor már kitért előle, komolyan.'::text),
(391602,43512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn ein Video so krass ..., starren alle aufs Handy, echt.'::text,'ist'::text,'war'::text,'sein wird'::text,'Bro, wenn ein Video so krass ist, starren alle aufs Handy, echt.'::text),
(391606,43512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо відео ... таке божевільне, всі витріщаються в телефон, реально.'::text,''::text,'було'::text,'буде'::text,'Бро, якщо відео таке божевільне, всі витріщаються в телефон, реально.'::text),
(391605,43512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si un vídeo ... así de loco, todo el mundo se queda mirando el móvil, en serio.'::text,'es'::text,'era'::text,'será'::text,'Bro, si un vídeo es así de loco, todo el mundo se queda mirando el móvil, en serio.'::text),
(391604,43512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, si une vidéo ... aussi dingue, tout le monde fixe le téléphone, sérieux.'::text,'est'::text,'était'::text,'sera'::text,'Frère, si une vidéo est aussi dingue, tout le monde fixe le téléphone, sérieux.'::text),
(391607,43512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir video o kadar çılgın ..., herkes telefona bakakalır, cidden.'::text,'olursa'::text,'olsaydı'::text,'olacaksa'::text,'Kanka, bir video o kadar çılgın olursa, herkes telefona bakakalır, cidden.'::text),
(391608,43512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy videó ennyire őrült ..., mindenki a telefont bámulja, komolyan.'::text,''::text,'volt'::text,'lesz'::text,'Tesó, ha egy videó ennyire őrült, mindenki a telefont bámulja, komolyan.'::text),
(391665,43519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... auf das Handy, seit die Sonne untergegangen ist.'::text,'starren'::text,'starren'::text,'starren'::text,'Bestie, ich hab gehört, sie starren auf das Handy, seit die Sonne untergegangen ist.'::text),
(391669,43519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бестіс, я чула, що вони ... в той телефон, відколи сіло сонце.'::text,'витріщаються'::text,'витріщаються'::text,'витріщаються'::text,'Бестіс, я чула, що вони витріщаються в той телефон, відколи сіло сонце.'::text),
(391668,43519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, oí que ellos ... ese móvil desde que se puso el sol.'::text,'han estado mirando fijamente'::text,'están mirando fijamente'::text,'miran fijamente'::text,'Bestie, oí que ellos han estado mirando fijamente ese móvil desde que se puso el sol.'::text),
(391667,43519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, j''ai entendu dire qu''ils ... ce téléphone depuis le coucher du soleil.'::text,'fixent'::text,'fixent'::text,'fixent'::text,'Bestie, j''ai entendu dire qu''ils fixent ce téléphone depuis le coucher du soleil.'::text),
(391670,43519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki onlar güneş battığından beri o telefona ...'::text,'bakıyormuş'::text,'bakıyormuş'::text,'bakarmış'::text,'Kanka, duydum ki onlar güneş battığından beri o telefona bakıyormuş.'::text),
(391671,43519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, azt hallottam, hogy ők napnyugta óta ... azt a telefont.'::text,'bámulják'::text,'bámulják'::text,'bámulják'::text,'Bestie, azt hallottam, hogy ők napnyugta óta bámulják azt a telefont.'::text),
(396282,44032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig total entspannt: Sie ... voller Panik seinen Arm, als der Clown auftauchte.'::text,'packte'::text,'packte gerade'::text,'packt'::text,'Eindeutig total entspannt: Sie packte voller Panik seinen Arm, als der Clown auftauchte.'::text),
(396286,44032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно дуже розслаблена: вона ... його за руку від жаху, коли з''явився клоун.'::text,'схопила'::text,'хапала'::text,'хапає'::text,'Явно дуже розслаблена: вона схопила його за руку від жаху, коли з''явився клоун.'::text),
(396285,44032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente muy relajada: ella le ... el brazo aterrorizada cuando apareció el payaso.'::text,'agarró'::text,'estaba agarrando'::text,'agarra'::text,'Claramente muy relajada: ella le agarró el brazo aterrorizada cuando apareció el payaso.'::text),
(396284,44032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement très détendue : elle ... son bras, terrorisée, quand le clown est apparu.'::text,'a agrippé'::text,'agrippait'::text,'agrippe'::text,'Clairement très détendue : elle a agrippé son bras, terrorisée, quand le clown est apparu.'::text),
(396287,44032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki çok rahat: palyaço belirince o dehşet içinde adamın kolunu ...'::text,'yakaladı'::text,'yakalıyordu'::text,'yakalıyor'::text,'Belli ki çok rahat: palyaço belirince o dehşet içinde adamın kolunu yakaladı.'::text),
(396288,44032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen nagyon laza: ő rémülten ... a karját, amikor megjelent a bohóc.'::text,'megragadta'::text,'ragadta'::text,'megragadja'::text,'Egyértelműen nagyon laza: ő rémülten megragadta a karját, amikor megjelent a bohóc.'::text),
(396345,44039,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gingen ... ihrer Angst weiter.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Sie gingen trotz ihrer Angst weiter.'::text),
(396349,44039,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони йшли далі ... свій жах.'::text,'попри'::text,'хоча'::text,'через'::text,'Вони йшли далі попри свій жах.'::text),
(396348,44039,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos siguieron caminando ... su terror.'::text,'a pesar de'::text,'aunque'::text,'debido a'::text,'Ellos siguieron caminando a pesar de su terror.'::text),
(396347,44039,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ont continué à marcher ... leur terreur.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'Ils ont continué à marcher malgré leur terreur.'::text),
(396350,44039,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar dehşetlerine ... yürümeye devam ettiler.'::text,'rağmen'::text,'gerçi'::text,'yüzünden'::text,'Onlar dehşetlerine rağmen yürümeye devam ettiler.'::text),
(396351,44039,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők a rémületük ... tovább mentek.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Ők a rémületük ellenére tovább mentek.'::text),
(337629,37515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor dem T-Rex-Vorfall ... das Subjekt jeden Abend in völliger Ruhe fernzusehen.'::text,'pflegte'::text,'pflegte'::text,'war gewohnt'::text,'Vor dem T-Rex-Vorfall pflegte das Subjekt jeden Abend in völliger Ruhe fernzusehen.'::text),
(337633,37515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До інциденту з тиранозавром суб''єкт щовечора ... телевізор у цілковитому спокої.'::text,'дивився'::text,'дивився'::text,'звик дивитися'::text,'До інциденту з тиранозавром суб''єкт щовечора дивився телевізор у цілковитому спокої.'::text),
(337632,37515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del incidente del T-rex, el sujeto ... ver la televisión con total calma cada noche.'::text,'solía'::text,'solía'::text,'estaba acostumbrado a'::text,'Antes del incidente del T-rex, el sujeto solía ver la televisión con total calma cada noche.'::text),
(337631,37515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''incident du T-rex, le sujet ... regarder la télévision dans un calme total chaque soir.'::text,'avait l''habitude de'::text,'avait l''habitude de'::text,'était habitué à'::text,'Avant l''incident du T-rex, le sujet avait l''habitude de regarder la télévision dans un calme total chaque soir.'::text),
(337634,37515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T-rex olayından önce denek her akşam tam bir sükûnet içinde televizyon ...'::text,'izlerdi'::text,'izlerdi'::text,'izlemeye alışkındı'::text,'T-rex olayından önce denek her akşam tam bir sükûnet içinde televizyon izlerdi.'::text),
(337635,37515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A T-rex-incidens előtt az alany minden este teljes nyugalomban ... tévét.'::text,'nézett'::text,'szokott nézni'::text,'hozzá volt szokva nézni'::text,'A T-rex-incidens előtt az alany minden este teljes nyugalomban nézett tévét.'::text),
(337656,37518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Ruhe ... seit dem T-Rex-Angriff weg, deshalb versteckt sie sich unter der Decke.'::text,'ist'::text,'ist'::text,'war'::text,'Ihre Ruhe ist seit dem T-Rex-Angriff weg, deshalb versteckt sie sich unter der Decke.'::text),
(337660,37518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її спокій ... з часу нападу тиранозавра, тож вона ховається під ковдрою.'::text,'зник'::text,'зник'::text,'зник'::text,'Її спокій зник з часу нападу тиранозавра, тож вона ховається під ковдрою.'::text),
(337659,37518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su calma ... desde el ataque del T-rex, así que se esconde bajo la manta.'::text,'ha desaparecido'::text,'ha desaparecido'::text,'desapareció'::text,'Su calma ha desaparecido desde el ataque del T-rex, así que se esconde bajo la manta.'::text),
(337658,37518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son calme ... envolé depuis l''attaque du T-rex, alors elle se cache sous la couverture.'::text,'s''est'::text,'s''est'::text,'était'::text,'Son calme s''est envolé depuis l''attaque du T-rex, alors elle se cache sous la couverture.'::text),
(337661,37518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T-rex saldırısından beri sakinliği ..., o yüzden battaniyenin altına saklanıyor.'::text,'yok'::text,'yok'::text,'yoktu'::text,'T-rex saldırısından beri sakinliği yok, o yüzden battaniyenin altına saklanıyor.'::text),
(337662,37518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nyugalma a T-rex-támadás óta ..., ezért a takaró alá bújik.'::text,'odavan'::text,'odavan'::text,'odavolt'::text,'A nyugalma a T-rex-támadás óta odavan, ezért a takaró alá bújik.'::text),
(340428,37826,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade wird das gefrorene Land mit einer zerrissenen ockerfarbenen Flagge ...'::text,'beansprucht'::text,'beansprucht'::text,'beansprucht'::text,'Gerade wird das gefrorene Land mit einer zerrissenen ockerfarbenen Flagge beansprucht.'::text),
(340432,37826,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз замерзла земля ... пошарпаним вохристим прапором.'::text,'привласнюється'::text,'привласнює'::text,'привласнила'::text,'Просто зараз замерзла земля привласнюється пошарпаним вохристим прапором.'::text),
(340431,37826,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo la tierra helada ... con una bandera ocre rasgada.'::text,'está siendo reclamada'::text,'está reclamando'::text,'ha reclamado'::text,'Ahora mismo la tierra helada está siendo reclamada con una bandera ocre rasgada.'::text),
(340430,37826,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la terre gelée ... avec un drapeau ocre déchiré.'::text,'est revendiquée'::text,'revendique'::text,'a revendiqué'::text,'En ce moment, la terre gelée est revendiquée avec un drapeau ocre déchiré.'::text),
(340433,37826,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda donmuş toprak yırtık hardal rengi bir bayrakla ...'::text,'sahipleniliyor'::text,'sahipleniyor'::text,'sahiplendi'::text,'Şu anda donmuş toprak yırtık hardal rengi bir bayrakla sahipleniliyor.'::text),
(340434,37826,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a fagyott földet egy szakadt okkersárga zászlóval.'::text,'veszik birtokba'::text,'birtokba veszi'::text,'birtokba vette'::text,'Épp most veszik birtokba a fagyott földet egy szakadt okkersárga zászlóval.'::text),
(378588,42066,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen Mittag ... er wieder am Zaun der Ranch entlang.'::text,'reitet'::text,'reitet'::text,'reitet'::text,'Morgen Mittag reitet er wieder am Zaun der Ranch entlang.'::text),
(378592,42066,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра опівдні він знову ... вздовж паркану ранчо.'::text,'їхатиме'::text,'поїде'::text,'їде'::text,'Завтра опівдні він знову їхатиме вздовж паркану ранчо.'::text),
(378591,42066,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana al mediodía él ... de nuevo junto a la valla del rancho.'::text,'estará cabalgando'::text,'cabalgará'::text,'cabalga'::text,'Mañana al mediodía él estará cabalgando de nuevo junto a la valla del rancho.'::text),
(378590,42066,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à midi, il ... de nouveau le long de la clôture du ranch.'::text,'sera en train de chevaucher'::text,'chevauchera'::text,'chevauche'::text,'Demain à midi, il sera en train de chevaucher de nouveau le long de la clôture du ranch.'::text),
(378593,42066,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın öğlen o yine çiftliğin çiti boyunca ...'::text,'at sürüyor olacak'::text,'at sürecek'::text,'at sürüyor'::text,'Yarın öğlen o yine çiftliğin çiti boyunca at sürüyor olacak.'::text),
(378594,42066,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap délben ő újra a tanya kerítése mentén ...'::text,'fog lovagolni'::text,'lovagol majd'::text,'lovagol'::text,'Holnap délben ő újra a tanya kerítése mentén fog lovagolni.'::text),
(367932,40882,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sie wünschte, dass sie die Linie mit einer Drohne ..., weil die Hügel echt steil sind.'::text,'markiert hätten'::text,'markieren würden'::text,'markiert haben'::text,'Bro, sie wünschte, dass sie die Linie mit einer Drohne markiert hätten, weil die Hügel echt steil sind.'::text),
(367936,40882,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона хотіла б, щоб вони ... лінію дроном, бо ті пагорби досить круті.'::text,'позначили'::text,'позначили'::text,'позначили'::text,'Бро, вона хотіла б, щоб вони позначили лінію дроном, бо ті пагорби досить круті.'::text),
(367935,40882,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella desearía que ellos ... la línea con un dron, porque esas colinas son bastante empinadas.'::text,'hubieran marcado'::text,'marcaran'::text,'hayan marcado'::text,'Bro, ella desearía que ellos hubieran marcado la línea con un dron, porque esas colinas son bastante empinadas.'::text),
(367934,40882,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, elle aurait aimé qu''ils ... la ligne avec un drone, parce que ces collines sont assez raides.'::text,'aient marqué'::text,'marquent'::text,'aient marqué'::text,'Frère, elle aurait aimé qu''ils aient marqué la ligne avec un drone, parce que ces collines sont assez raides.'::text),
(367937,40882,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o keşke çizgiyi drone ile ... diyor, çünkü o tepeler baya dik.'::text,'işaretleselerdi'::text,'işaretleseler'::text,'işaretlemiş olsalar'::text,'Kanka, o keşke çizgiyi drone ile işaretleselerdi diyor, çünkü o tepeler baya dik.'::text),
(367938,40882,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő azt szeretné, bárcsak drónnal ... ki a vonalat, mert elég meredekek azok a dombok.'::text,'jelölték volna'::text,'jelölnék'::text,'jelölték'::text,'Tesó, ő azt szeretné, bárcsak drónnal jelölték volna ki a vonalat, mert elég meredekek azok a dombok.'::text),
(368850,40984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, die gewaltige Welle ... gleich über den Möwen.'::text,'bricht'::text,'bricht'::text,'bricht'::text,'Ich glaube, die gewaltige Welle bricht gleich über den Möwen.'::text),
(368854,40984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я думаю, що могутня хвиля за секунду ... над чайками.'::text,'обрушиться'::text,'обрушуватиметься'::text,'обрушується'::text,'Я думаю, що могутня хвиля за секунду обрушиться над чайками.'::text),
(368853,40984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo creo que la poderosa ola ... sobre las gaviotas en un segundo.'::text,'romperá'::text,'estará rompiendo'::text,'está rompiendo'::text,'Yo creo que la poderosa ola romperá sobre las gaviotas en un segundo.'::text),
(368852,40984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que la puissante vague ... sur les mouettes dans une seconde.'::text,'s''écrasera'::text,'sera en train de s''écraser'::text,'s''écrase'::text,'Je pense que la puissante vague s''écrasera sur les mouettes dans une seconde.'::text),
(368855,40984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence o güçlü dalga bir saniye içinde martıların üstüne ...'::text,'çökecek'::text,'çöküyor olacak'::text,'çöküyor'::text,'Bence o güçlü dalga bir saniye içinde martıların üstüne çökecek.'::text),
(368856,40984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem a hatalmas hullám egy másodperc múlva ... a sirályokra.'::text,'le fog zúdulni'::text,'zúdul majd'::text,'zúdul le'::text,'Szerintem a hatalmas hullám egy másodperc múlva le fog zúdulni a sirályokra.'::text),
(396471,44053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Rachen, ... Bewegung beim Schlucken beobachtbar ist, befördert das Wasser nach unten.'::text,'dessen'::text,'der'::text,'das'::text,'Der Rachen, dessen Bewegung beim Schlucken beobachtbar ist, befördert das Wasser nach unten.'::text),
(396475,44053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Горло, ... рух помітний, коли він ковтає, спрямовує воду вниз.'::text,'чий'::text,'яке'::text,'що'::text,'Горло, чий рух помітний, коли він ковтає, спрямовує воду вниз.'::text),
(396474,44053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La garganta, ... movimiento es observable cuando él traga, lleva el agua hacia abajo.'::text,'cuyo'::text,'que'::text,'la cual'::text,'La garganta, cuyo movimiento es observable cuando él traga, lleva el agua hacia abajo.'::text),
(396473,44053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La gorge, ... le mouvement est observable quand il avale, fait descendre l''eau.'::text,'dont'::text,'qui'::text,'que'::text,'La gorge, dont le mouvement est observable quand il avale, fait descendre l''eau.'::text),
(396476,44053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yutkunduğunda ... hareketi gözlemlenebilen boğaz, suyu aşağıya taşır.'::text,''::text,NULL::text,NULL::text,'O yutkunduğunda hareketi gözlemlenebilen boğaz, suyu aşağıya taşır.'::text),
(396477,44053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A torok, ... mozgása megfigyelhető, amikor ő nyel, lefelé viszi a vizet.'::text,'amelynek'::text,'amely'::text,'ami'::text,'A torok, amelynek mozgása megfigyelhető, amikor ő nyel, lefelé viszi a vizet.'::text),
(397218,44136,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ihr Vater schwört, dass er ihren nächsten Schritt auf Video ..., egal was passiert.'::text,'aufnehmen wird'::text,'aufnehmen wird'::text,'aufnimmt'::text,'Mädel, ihr Vater schwört, dass er ihren nächsten Schritt auf Video aufnehmen wird, egal was passiert.'::text),
(397222,44136,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, її тато клянеться, що він ... її наступний крок на відео, хай що станеться.'::text,'зніме'::text,'зніматиме'::text,'знімає'::text,'Подруго, її тато клянеться, що він зніме її наступний крок на відео, хай що станеться.'::text),
(397221,44136,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, su padre jura que él ... su próximo paso en vídeo, pase lo que pase.'::text,'grabará'::text,'estará grabando'::text,'está grabando'::text,'Amiga, su padre jura que él grabará su próximo paso en vídeo, pase lo que pase.'::text),
(397220,44136,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, son père jure qu''il ... son tout prochain pas en vidéo, quoi qu''il arrive.'::text,'filmera'::text,'sera en train de filmer'::text,'filme'::text,'Meuf, son père jure qu''il filmera son tout prochain pas en vidéo, quoi qu''il arrive.'::text),
(397223,44136,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, babası ne olursa olsun onun bir sonraki adımını videoya ... diye yemin ediyor.'::text,'çekecek'::text,'çekiyor olacak'::text,'çekiyor'::text,'Kızım, babası ne olursa olsun onun bir sonraki adımını videoya çekecek diye yemin ediyor.'::text),
(397224,44136,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, az apja esküszik, hogy ő a következő lépését videóra ..., bármi történjék.'::text,'veszi'::text,'venni fogja'::text,'veszi éppen'::text,'Csajszi, az apja esküszik, hogy ő a következő lépését videóra veszi, bármi történjék.'::text),
(397254,44140,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vor der Budgeterhöhung ... die Kita jahrelang 20 Kleinkinder in einem einzigen Raum.'::text,'betreute'::text,'betreute'::text,'betreut'::text,'Vor der Budgeterhöhung betreute die Kita jahrelang 20 Kleinkinder in einem einzigen Raum.'::text),
(397258,44140,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До збільшення бюджету ясла роками ... 20 малюків в одній кімнаті.'::text,'доглядали'::text,'доглядали'::text,'доглянули'::text,'До збільшення бюджету ясла роками доглядали 20 малюків в одній кімнаті.'::text),
(397257,44140,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes del aumento del presupuesto, la guardería ... de 20 niños pequeños en una sola sala durante años.'::text,'había estado cuidando'::text,'estaba cuidando'::text,'ha cuidado'::text,'Antes del aumento del presupuesto, la guardería había estado cuidando de 20 niños pequeños en una sola sala durante años.'::text),
(397256,44140,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant l''augmentation du budget, la crèche ... de 20 tout-petits dans une seule salle pendant des années.'::text,'s''occupait'::text,'s''occupait'::text,'s''est occupée'::text,'Avant l''augmentation du budget, la crèche s''occupait de 20 tout-petits dans une seule salle pendant des années.'::text),
(397259,44140,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe artışından önce kreş yıllarca tek bir odada 20 küçük çocuğa ...'::text,'bakıyordu'::text,'bakıyordu'::text,'baktı'::text,'Bütçe artışından önce kreş yıllarca tek bir odada 20 küçük çocuğa bakıyordu.'::text),
(397260,44140,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A költségvetés-emelés előtt a bölcsőde évekig 20 kisgyerekre ... egyetlen teremben.'::text,'vigyázott'::text,'vigyázott'::text,'vigyázott'::text,'A költségvetés-emelés előtt a bölcsőde évekig 20 kisgyerekre vigyázott egyetlen teremben.'::text),
(394977,43887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau ... eine perfekte Zahnpasta-Spirale auf jede Bürste.'::text,'setzte'::text,'wurde gesetzt'::text,'setzend'::text,'Die Frau setzte eine perfekte Zahnpasta-Spirale auf jede Bürste.'::text),
(394981,43887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка ... ідеальну спіраль пасти на кожній щітці.'::text,'зробила'::text,'була зроблена'::text,'роблячи'::text,'Жінка зробила ідеальну спіраль пасти на кожній щітці.'::text),
(394980,43887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... una espiral perfecta de pasta en cada cepillo.'::text,'hizo'::text,'fue hecha'::text,'haciendo'::text,'La mujer hizo una espiral perfecta de pasta en cada cepillo.'::text),
(394979,43887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... une spirale parfaite de dentifrice sur chaque brosse.'::text,'a fait'::text,'a été faite'::text,'faisant'::text,'La femme a fait une spirale parfaite de dentifrice sur chaque brosse.'::text),
(394982,43887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın her fırçaya kusursuz bir macun kıvrımı ...'::text,'yaptı'::text,'yapıldı'::text,'yaparak'::text,'Kadın her fırçaya kusursuz bir macun kıvrımı yaptı.'::text),
(394983,43887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő ... egy tökéletes fogkrémspirált minden kefére.'::text,'készített'::text,'készült'::text,'készítve'::text,'A nő készített egy tökéletes fogkrémspirált minden kefére.'::text),
(374088,41566,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während die Gruppe zwischen den riesigen Säulen ..., hielt der Guide einen roten Regenschirm hoch.'::text,'hindurchging'::text,'ging'::text,'gegangen ist'::text,'Während die Gruppe zwischen den riesigen Säulen hindurchging, hielt der Guide einen roten Regenschirm hoch.'::text),
(374092,41566,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки група ... між величезними колонами, гід тримав угорі червону парасольку.'::text,'йшла'::text,'пройшла'::text,'пройшла'::text,'Поки група йшла між величезними колонами, гід тримав угорі червону парасольку.'::text),
(374091,41566,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el grupo ... entre los enormes pilares, el guía levantó un paraguas rojo.'::text,'caminaba'::text,'caminó'::text,'ha caminado'::text,'Mientras el grupo caminaba entre los enormes pilares, el guía levantó un paraguas rojo.'::text),
(374090,41566,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le groupe ... entre les immenses piliers, le guide levait un parapluie rouge.'::text,'marchait'::text,'a marché'::text,'a marché'::text,'Pendant que le groupe marchait entre les immenses piliers, le guide levait un parapluie rouge.'::text),
(374093,41566,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Grup devasa sütunların arasında ... rehber kırmızı bir şemsiye kaldırdı.'::text,'yürürken'::text,'yürüdüğünde'::text,'yürümüşken'::text,'Grup devasa sütunların arasında yürürken rehber kırmızı bir şemsiye kaldırdı.'::text),
(374094,41566,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a csoport a hatalmas oszlopok között ..., az idegenvezető feltartott egy piros esernyőt.'::text,'sétált'::text,'sétált'::text,'sétált'::text,'Miközben a csoport a hatalmas oszlopok között sétált, az idegenvezető feltartott egy piros esernyőt.'::text),
(374160,41574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit zwei Stunden Fotos von diesen Säulen, und der Akku ist komplett leer!'::text,'machen'::text,'machen'::text,'machen'::text,'Sie machen seit zwei Stunden Fotos von diesen Säulen, und der Akku ist komplett leer!'::text),
(374164,41574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... фото цих колон уже дві години, і батарея повністю сіла!'::text,'роблять'::text,'роблять'::text,'роблять'::text,'Вони роблять фото цих колон уже дві години, і батарея повністю сіла!'::text),
(374163,41574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... fotos de estos pilares durante dos horas, y la batería está completamente muerta!'::text,'han estado haciendo'::text,'están haciendo'::text,'hacen'::text,'¡Ellos han estado haciendo fotos de estos pilares durante dos horas, y la batería está completamente muerta!'::text),
(374162,41574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... des photos de ces piliers depuis deux heures, et la batterie est complètement morte !'::text,'prennent'::text,'prennent'::text,'prennent'::text,'Ils prennent des photos de ces piliers depuis deux heures, et la batterie est complètement morte !'::text),
(374165,41574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar iki saattir bu sütunların fotoğraflarını ... ve pil tamamen bitti!'::text,'çekiyorlar'::text,'çekiyorlar'::text,'çekerler'::text,'Onlar iki saattir bu sütunların fotoğraflarını çekiyorlar ve pil tamamen bitti!'::text),
(374166,41574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők két órája ... a fotókat ezekről az oszlopokról, és teljesen lemerült az akku!'::text,'csinálják'::text,'csinálják'::text,'csinálják'::text,'Ők két órája csinálják a fotókat ezekről az oszlopokról, és teljesen lemerült az akku!'::text),
(360912,40102,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Verkehr stundenlang ..., fühlen sich die Fahrer hoffnungslos.'::text,'stillsteht'::text,'stillstehen wird'::text,'stillstand'::text,'Wenn der Verkehr stundenlang stillsteht, fühlen sich die Fahrer hoffnungslos.'::text),
(360916,40102,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо транспорт ... годинами, водії почуваються безнадійно.'::text,'стоїть'::text,'стоятиме'::text,'стояв'::text,'Якщо транспорт стоїть годинами, водії почуваються безнадійно.'::text),
(360915,40102,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tráfico ... parado durante horas, los conductores se sienten sin esperanza.'::text,'está'::text,'estará'::text,'estuvo'::text,'Si el tráfico está parado durante horas, los conductores se sienten sin esperanza.'::text),
(360914,40102,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la circulation ... bloquée pendant des heures, les conducteurs se sentent désespérés.'::text,'reste'::text,'restera'::text,'restait'::text,'Si la circulation reste bloquée pendant des heures, les conducteurs se sentent désespérés.'::text),
(360917,40102,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trafik saatlerce ..., sürücüler umutsuz hisseder.'::text,'durursa'::text,'duracaksa'::text,'durduysa'::text,'Trafik saatlerce durursa, sürücüler umutsuz hisseder.'::text),
(360918,40102,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a forgalom órákig ..., a sofőrök reménytelennek érzik magukat.'::text,'áll'::text,'állni fog'::text,'állt'::text,'Ha a forgalom órákig áll, a sofőrök reménytelennek érzik magukat.'::text),
(378147,42017,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hunderte Autos unter dem Geländer! Er ... zu spät zur Schule kommen. Eine totale Katastrophe!'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Hunderte Autos unter dem Geländer! Er muss zu spät zur Schule kommen. Eine totale Katastrophe!'::text),
(378151,42017,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сотні машин під поруччям! Він ... запізнитися до школи. Повна катастрофа!'::text,'мусить'::text,'може'::text,'не може'::text,'Сотні машин під поруччям! Він мусить запізнитися до школи. Повна катастрофа!'::text),
(378150,42017,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cientos de coches bajo la barandilla! Él ... llegar tarde al colegio. ¡Un desastre total!'::text,'debe de'::text,'puede'::text,'no puede'::text,'¡Cientos de coches bajo la barandilla! Él debe de llegar tarde al colegio. ¡Un desastre total!'::text),
(378149,42017,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des centaines de voitures sous la rambarde ! Il ... être en retard à l''école. Un désastre total !'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Des centaines de voitures sous la rambarde ! Il doit être en retard à l''école. Un désastre total !'::text),
(378152,42017,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korkuluğun altında yüzlerce araba! O, okula ... geç kalacak; tam bir felaket!'::text,'kesin'::text,'belki'::text,'asla'::text,'Korkuluğun altında yüzlerce araba! O, okula kesin geç kalacak; tam bir felaket!'::text),
(378153,42017,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Autók százai a korlát alatt! Ő ... el fog késni az iskolából. Totális katasztrófa!'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Autók százai a korlát alatt! Ő biztosan el fog késni az iskolából. Totális katasztrófa!'::text),
(378210,42024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Stunde im Auto, bevor er das Geländer der Fußgängerbrücke erreichte.'::text,'saß'::text,'saß'::text,'sitzt'::text,'Er saß eine Stunde im Auto, bevor er das Geländer der Fußgängerbrücke erreichte.'::text),
(378214,42024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж дійти до поруччя пішохідного мосту, він ... в машині годину.'::text,'сидів'::text,'сидів'::text,'сидить'::text,'Перш ніж дійти до поруччя пішохідного мосту, він сидів в машині годину.'::text),
(378213,42024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de llegar a la barandilla de la pasarela, él ... en el coche una hora.'::text,'había estado sentado'::text,'estaba sentado'::text,'ha estado sentado'::text,'Antes de llegar a la barandilla de la pasarela, él había estado sentado en el coche una hora.'::text),
(378212,42024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant d''atteindre la rambarde de la passerelle, il ... dans la voiture pendant une heure.'::text,'était resté assis'::text,'était assis'::text,'est resté assis'::text,'Avant d''atteindre la rambarde de la passerelle, il était resté assis dans la voiture pendant une heure.'::text),
(378215,42024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yaya köprüsünün korkuluğuna varmadan önce o bir saat arabada ...'::text,'oturmuştu'::text,'oturuyordu'::text,'oturdu'::text,'Yaya köprüsünün korkuluğuna varmadan önce o bir saat arabada oturmuştu.'::text),
(378216,42024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt elérte a gyalogoshíd korlátját, ő egy órán át az autóban ...'::text,'ült'::text,'ült'::text,'ült'::text,'Mielőtt elérte a gyalogoshíd korlátját, ő egy órán át az autóban ült.'::text),
(366177,40687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast die orange Lok angelächelt, und ehrlich gesagt, ich ...'::text,'auch'::text,'auch'::text,'auch nicht'::text,'Du hast die orange Lok angelächelt, und ehrlich gesagt, ich auch.'::text),
(366181,40687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти усміхнулася тому помаранчевому локомотиву, і, чесно, я ...'::text,'теж'::text,'теж'::text,'теж ні'::text,'Ти усміхнулася тому помаранчевому локомотиву, і, чесно, я теж.'::text),
(366180,40687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú le sonreíste a esa locomotora naranja y, sinceramente, yo ...'::text,'también'::text,'también'::text,'tampoco'::text,'Tú le sonreíste a esa locomotora naranja y, sinceramente, yo también.'::text),
(366179,40687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as souri à cette locomotive orange et, franchement, moi ...'::text,'aussi'::text,'aussi'::text,'non plus'::text,'Tu as souri à cette locomotive orange et, franchement, moi aussi.'::text),
(366182,40687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen o turuncu lokomotife gülümsedin ve açıkçası ben ...'::text,'de'::text,'de'::text,'de değil'::text,'Sen o turuncu lokomotife gülümsedin ve açıkçası ben de.'::text),
(366183,40687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te rámosolyogtál arra a narancssárga mozdonyra, és őszintén, én ...'::text,'is'::text,'is'::text,'sem'::text,'Te rámosolyogtál arra a narancssárga mozdonyra, és őszintén, én is.'::text),
(366258,40696,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Lärms lächelte sie, als die orange Lok vorbeirollte.'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz des Lärms lächelte sie, als die orange Lok vorbeirollte.'::text),
(366262,40696,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... шум, вона усміхалася, коли повз проїжджав помаранчевий локомотив.'::text,'Попри'::text,'Через'::text,'За умови'::text,'Попри шум, вона усміхалася, коли повз проїжджав помаранчевий локомотив.'::text),
(366261,40696,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el ruido, ella sonreía mientras la locomotora naranja pasaba.'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'A pesar de el ruido, ella sonreía mientras la locomotora naranja pasaba.'::text),
(366260,40696,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le bruit, elle souriait pendant que la locomotive orange passait.'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré le bruit, elle souriait pendant que la locomotive orange passait.'::text),
(366263,40696,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gürültüye ..., turuncu lokomotif geçerken o gülümsedi.'::text,'rağmen'::text,'bağlı olarak'::text,'koşuluyla'::text,'Gürültüye rağmen, turuncu lokomotif geçerken o gülümsedi.'::text),
(366264,40696,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zaj ..., ő mosolygott, amikor a narancssárga mozdony elgördült mellette.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A zaj ellenére, ő mosolygott, amikor a narancssárga mozdony elgördült mellette.'::text),
(346710,38524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie grinst jede Straßenbahn im Depot an, also ... sie Straßenbahnen lieben.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Sie grinst jede Straßenbahn im Depot an, also muss sie Straßenbahnen lieben.'::text),
(346714,38524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона усміхається кожному трамваю в депо, тож вона ... любити трамваї.'::text,'мусить'::text,'може'::text,'не може'::text,'Вона усміхається кожному трамваю в депо, тож вона мусить любити трамваї.'::text),
(346713,38524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella sonríe a cada tranvía de las cocheras, así que ... amar los tranvías.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Ella sonríe a cada tranvía de las cocheras, así que debe de amar los tranvías.'::text),
(346712,38524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sourit à chaque tram du dépôt, donc elle ... adorer les trams.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Elle sourit à chaque tram du dépôt, donc elle doit adorer les trams.'::text),
(346715,38524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O depodaki her tramvaya sırıtıyor, demek ki tramvayları ... seviyor.'::text,'kesin'::text,'belki'::text,'asla'::text,'O depodaki her tramvaya sırıtıyor, demek ki tramvayları kesin seviyor.'::text),
(346716,38524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő a depó minden villamosára vigyorog, szóval ... imádja a villamosokat.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Ő a depó minden villamosára vigyorog, szóval biztosan imádja a villamosokat.'::text),
(362703,40301,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ein kleines bisschen begeistert von diesem Holzinterieur sein; sie hört nicht auf zu grinsen.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Sie muss ein kleines bisschen begeistert von diesem Holzinterieur sein; sie hört nicht auf zu grinsen.'::text),
(362707,40301,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... бути трохи в захваті від цього дерев''яного інтер''єру; вона не перестає усміхатися.'::text,'мусить'::text,'може'::text,'не може'::text,'Вона мусить бути трохи в захваті від цього дерев''яного інтер''єру; вона не перестає усміхатися.'::text),
(362706,40301,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... estar un pelín emocionada con este interior de madera; no para de sonreír.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Ella debe de estar un pelín emocionada con este interior de madera; no para de sonreír.'::text),
(362705,40301,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... être légèrement enthousiaste devant cet intérieur en bois ; elle n''arrête pas de sourire.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Elle doit être légèrement enthousiaste devant cet intérieur en bois ; elle n''arrête pas de sourire.'::text),
(362708,40301,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bu ahşap iç mekân için azıcık heyecanlı ...; sırıtmayı bırakmıyor.'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'O bu ahşap iç mekân için azıcık heyecanlı olmalı; sırıtmayı bırakmıyor.'::text),
(362709,40301,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... egy kicsit izgatott ettől a fa belsőtől; nem hagyja abba a vigyorgást.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Ő biztosan egy kicsit izgatott ettől a fa belsőtől; nem hagyja abba a vigyorgást.'::text),
(398190,44244,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man geht davon aus, dass sein Umstieg von der U-Bahn auf die Fähre vorhin weniger als zehn Minuten ...'::text,'gedauert hat'::text,'dauert'::text,'dauernd'::text,'Man geht davon aus, dass sein Umstieg von der U-Bahn auf die Fähre vorhin weniger als zehn Minuten gedauert hat.'::text),
(398194,44244,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що його пересадка з метро на пором сьогодні раніше ... менше десяти хвилин.'::text,'тривала'::text,'триває'::text,'триваючи'::text,'Вважається, що його пересадка з метро на пором сьогодні раніше тривала менше десяти хвилин.'::text),
(398193,44244,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que su transbordo del metro al ferri ... menos de diez minutos hoy más temprano.'::text,'duró'::text,'dura'::text,'durando'::text,'Se cree que su transbordo del metro al ferri duró menos de diez minutos hoy más temprano.'::text),
(398192,44244,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que sa correspondance du métro au ferry ... moins de dix minutes plus tôt aujourd''hui.'::text,'a pris'::text,'prend'::text,'prenant'::text,'On pense que sa correspondance du métro au ferry a pris moins de dix minutes plus tôt aujourd''hui.'::text),
(398195,44244,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Metrodan vapura aktarmasının bugün daha erken saatlerde on dakikadan kısa ... düşünülüyor.'::text,'sürdüğü'::text,'süreceği'::text,'sürmesi'::text,'Metrodan vapura aktarmasının bugün daha erken saatlerde on dakikadan kısa sürdüğü düşünülüyor.'::text),
(398196,44244,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy vélik, hogy a metróról a kompra való átszállása ma korábban kevesebb mint tíz percig ...'::text,'tartott'::text,'tart'::text,'tartva'::text,'Úgy vélik, hogy a metróról a kompra való átszállása ma korábban kevesebb mint tíz percig tartott.'::text),
(400611,44513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... seit der U-Bahn, und das Schiff ist immer noch nicht weg.'::text,'rennt'::text,'rennt'::text,'rennt'::text,'Alter, er rennt seit der U-Bahn, und das Schiff ist immer noch nicht weg.'::text),
(400615,44513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, він ... від самого метро, а те судно досі не відплило.'::text,'біжить'::text,'біжить'::text,'біжить'::text,'Чувак, він біжить від самого метро, а те судно досі не відплило.'::text),
(400614,44513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, él ... desde el metro, y ese barco todavía no se ha ido.'::text,'lleva corriendo'::text,'está corriendo'::text,'corre'::text,'Tío, él lleva corriendo desde el metro, y ese barco todavía no se ha ido.'::text),
(400613,44513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, il ... depuis le métro, et ce bateau n''est toujours pas parti.'::text,'court'::text,'court'::text,'court'::text,'Mec, il court depuis le métro, et ce bateau n''est toujours pas parti.'::text),
(400616,44513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o metrodan beri ... ve o gemi hâlâ gitmedi.'::text,'koşuyor'::text,'koşuyor'::text,'koşar'::text,'Kanka, o metrodan beri koşuyor ve o gemi hâlâ gitmedi.'::text),
(400617,44513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő a metró óta ..., és az a hajó még mindig nem ment el.'::text,'fut'::text,'fut'::text,'fut'::text,'Tesó, ő a metró óta fut, és az a hajó még mindig nem ment el.'::text),
(400665,44519,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du wusstest immer, dass du das Schiff rechtzeitig ..., und so war''s.'::text,'erwischen würdest'::text,'erwischen wirst'::text,'erwischst'::text,'Ehrlich, du wusstest immer, dass du das Schiff rechtzeitig erwischen würdest, und so war''s.'::text),
(400669,44519,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти завжди знав, що ... те судно вчасно, і встиг.'::text,'встигнеш на'::text,'встигнеш на'::text,'встигаєш на'::text,'Чесно, ти завжди знав, що встигнеш на те судно вчасно, і встиг.'::text),
(400668,44519,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú siempre supiste que ... ese barco a tiempo, y lo hiciste.'::text,'cogerías'::text,'cogerás'::text,'estás cogiendo'::text,'Sinceramente, tú siempre supiste que cogerías ese barco a tiempo, y lo hiciste.'::text),
(400667,44519,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as toujours su que tu ... ce bateau à temps, et tu l''as eu.'::text,'attraperais'::text,'attraperas'::text,'attrapes'::text,'Franchement, tu as toujours su que tu attraperais ce bateau à temps, et tu l''as eu.'::text),
(400670,44519,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o gemiye zamanında ... hep biliyordun ve yetiştin.'::text,'yetişeceğini'::text,'yetişeceğini'::text,'yetiştiğini'::text,'Açıkçası sen o gemiye zamanında yetişeceğini hep biliyordun ve yetiştin.'::text),
(400671,44519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te mindig tudtad, hogy időben ... azt a hajót, és el is érted.'::text,'eléred'::text,'el fogod érni'::text,'eléred'::text,'Őszintén, te mindig tudtad, hogy időben eléred azt a hajót, és el is érted.'::text),
(379488,42166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir gesagt, dass er am Tag davor seinen ganzen Recyclingmüll ...'::text,'sortiert hatte'::text,'sortiert hat'::text,'sortiert'::text,'Hör zu, er hat mir gesagt, dass er am Tag davor seinen ganzen Recyclingmüll sortiert hatte.'::text),
(379492,42166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені, що напередодні ... усе своє сміття на переробку.'::text,'посортував'::text,'посортував'::text,'сортує'::text,'Слухай, він сказав мені, що напередодні посортував усе своє сміття на переробку.'::text),
(379491,42166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, él me dijo que ... todo su reciclaje el día anterior.'::text,'había separado'::text,'ha separado'::text,'separa'::text,'Escucha, él me dijo que había separado todo su reciclaje el día anterior.'::text),
(379490,42166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit qu''il ... tout son recyclage la veille.'::text,'avait trié'::text,'a trié'::text,'trie'::text,'Écoute, il m''a dit qu''il avait trié tout son recyclage la veille.'::text),
(379493,42166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, o bana bir gün önce bütün geri dönüşümünü ... söyledi.'::text,'ayırmış olduğunu'::text,'ayırdığını'::text,'ayırdığını'::text,'Dinle, o bana bir gün önce bütün geri dönüşümünü ayırmış olduğunu söyledi.'::text),
(379494,42166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, ő azt mondta nekem, hogy előző nap ... az összes szelektív hulladékát.'::text,'szétválogatta'::text,'szétválogatta'::text,'válogatja'::text,'Figyelj, ő azt mondta nekem, hogy előző nap szétválogatta az összes szelektív hulladékát.'::text),
(379515,42169,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher hat der Park in diesem Jahr 70 Prozent seines Recyclingziels ...'::text,'erreicht'::text,'erreicht'::text,'erreicht'::text,'Bisher hat der Park in diesem Jahr 70 Prozent seines Recyclingziels erreicht.'::text),
(379519,42169,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цього року парк поки що ... 70 відсотків своєї мети з переробки.'::text,'досяг'::text,'досягає'::text,'досягає'::text,'Цього року парк поки що досяг 70 відсотків своєї мети з переробки.'::text),
(379518,42169,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En lo que va de año, el parque ... el 70 por ciento de su objetivo de reciclaje.'::text,'ha alcanzado'::text,'alcanza'::text,'está alcanzando'::text,'En lo que va de año, el parque ha alcanzado el 70 por ciento de su objetivo de reciclaje.'::text),
(379517,42169,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Depuis le début de l''année, le parc ... 70 pour cent de son objectif de recyclage.'::text,'a atteint'::text,'atteint'::text,'est en train d''atteindre'::text,'Depuis le début de l''année, le parc a atteint 70 pour cent de son objectif de recyclage.'::text),
(379520,42169,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu yıl şimdiye kadar park, geri dönüşüm hedefinin yüzde 70''ine ...'::text,'ulaştı'::text,'ulaşıyor'::text,'ulaşıyor'::text,'Bu yıl şimdiye kadar park, geri dönüşüm hedefinin yüzde 70''ine ulaştı.'::text),
(379521,42169,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Idén eddig a park ... az újrahasznosítási célja 70 százalékát.'::text,'elérte'::text,'eléri'::text,'éri el'::text,'Idén eddig a park elérte az újrahasznosítási célja 70 százalékát.'::text),
(403734,44860,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Reise weltweit ist, ... ein Reisender meist Kleidung für Hitze und für Schnee.'::text,'braucht'::text,'wird brauchen'::text,'brauchte'::text,'Wenn eine Reise weltweit ist, braucht ein Reisender meist Kleidung für Hitze und für Schnee.'::text),
(403738,44860,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо подорож охоплює весь світ, мандрівникові зазвичай ... одяг і для спеки, і для снігу.'::text,'потрібен'::text,'знадобиться'::text,'був потрібен'::text,'Якщо подорож охоплює весь світ, мандрівникові зазвичай потрібен одяг і для спеки, і для снігу.'::text),
(403737,44860,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un viaje es por todo el mundo, un viajero normalmente ... ropa para el calor y para la nieve.'::text,'necesita'::text,'necesitará'::text,'necesitaba'::text,'Si un viaje es por todo el mundo, un viajero normalmente necesita ropa para el calor y para la nieve.'::text),
(403736,44860,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un voyage fait le tour du monde, un voyageur ... de vêtements pour la chaleur et pour la neige, en général.'::text,'a besoin'::text,'aura besoin'::text,'avait besoin'::text,'Si un voyage fait le tour du monde, un voyageur a besoin de vêtements pour la chaleur et pour la neige, en général.'::text),
(403739,44860,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yolculuk dünya çapındaysa, gezgin genelde hem sıcak hem kar için kıyafete ...'::text,'ihtiyaç duyar'::text,'ihtiyaç duyacak'::text,'ihtiyaç duydu'::text,'Bir yolculuk dünya çapındaysa, gezgin genelde hem sıcak hem kar için kıyafete ihtiyaç duyar.'::text),
(403740,44860,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy utazás világ körüli, az utazónak általában ... ruha a hőségre és a hóra is.'::text,'kell'::text,'kelleni fog'::text,'kellett'::text,'Ha egy utazás világ körüli, az utazónak általában kell ruha a hőségre és a hóra is.'::text),
(403770,44864,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, wenn er zu Hause geblieben wäre, hätte er diese Pinguine auf seiner Weltreise ..., echt.'::text,'verpasst'::text,'verpassen'::text,'verpasste'::text,'Bro, wenn er zu Hause geblieben wäre, hätte er diese Pinguine auf seiner Weltreise verpasst, echt.'::text),
(403774,44864,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби він залишився вдома, він ... тих пінгвінів у своїй кругосвітній подорожі, реально.'::text,'пропустив би'::text,'пропустить'::text,'пропустив'::text,'Бро, якби він залишився вдома, він пропустив би тих пінгвінів у своїй кругосвітній подорожі, реально.'::text),
(403773,44864,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si se hubiera quedado en casa, él ... esos pingüinos en su viaje por el mundo, en serio.'::text,'se habría perdido'::text,'se perderá'::text,'se perdió'::text,'Bro, si se hubiera quedado en casa, él se habría perdido esos pingüinos en su viaje por el mundo, en serio.'::text),
(403772,44864,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, s''il était resté chez lui, il ... ces manchots pendant son tour du monde, sérieux.'::text,'aurait raté'::text,'ratera'::text,'a raté'::text,'Frère, s''il était resté chez lui, il aurait raté ces manchots pendant son tour du monde, sérieux.'::text),
(403775,44864,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, evde kalsaydı o dünya turunda o penguenleri ..., cidden.'::text,'kaçırmış olurdu'::text,'kaçıracak'::text,'kaçırdı'::text,'Kanka, evde kalsaydı o dünya turunda o penguenleri kaçırmış olurdu, cidden.'::text),
(403776,44864,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha otthon maradt volna, ő ... azokat a pingvineket a világ körüli útján, komolyan.'::text,'kihagyta volna'::text,'ki fogja hagyni'::text,'kihagyta'::text,'Tesó, ha otthon maradt volna, ő kihagyta volna azokat a pingvineket a világ körüli útján, komolyan.'::text),
(398622,44292,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Vertrag funktioniert, ... die beiden Länder viele Jahre lang enge Partner.'::text,'bleiben'::text,'blieben'::text,'blieben'::text,'Wenn der Vertrag funktioniert, bleiben die beiden Länder viele Jahre lang enge Partner.'::text),
(398626,44292,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо договір спрацює, ці дві країни ... близькими партнерами багато років.'::text,'залишаться'::text,'залишилися б'::text,'залишилися'::text,'Якщо договір спрацює, ці дві країни залишаться близькими партнерами багато років.'::text),
(398625,44292,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el tratado funciona, los dos países ... socios cercanos durante muchos años.'::text,'seguirán siendo'::text,'seguirían siendo'::text,'siguieron siendo'::text,'Si el tratado funciona, los dos países seguirán siendo socios cercanos durante muchos años.'::text),
(398624,44292,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le traité fonctionne, les deux pays ... des partenaires proches pendant de nombreuses années.'::text,'resteront'::text,'resteraient'::text,'sont restés'::text,'Si le traité fonctionne, les deux pays resteront des partenaires proches pendant de nombreuses années.'::text),
(398627,44292,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antlaşma işe yararsa iki ülke uzun yıllar yakın ortak ...'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Antlaşma işe yararsa iki ülke uzun yıllar yakın ortak kalacak.'::text),
(398628,44292,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szerződés működik, a két ország sok évig közeli partner ...'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha a szerződés működik, a két ország sok évig közeli partner marad.'::text),
(346062,38452,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, beide Delegationen haben endlich zugestimmt, den Deal ..., kein Witz.'::text,'zu unterschreiben'::text,'Unterschreiben'::text,'unterschreiben'::text,'Yo, beide Delegationen haben endlich zugestimmt, den Deal zu unterschreiben, kein Witz.'::text),
(346066,38452,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, обидві делегації нарешті погодилися ... угоду, без брехні.'::text,'підписати'::text,'підписання'::text,'підписати'::text,'Йо, обидві делегації нарешті погодилися підписати угоду, без брехні.'::text),
(346065,38452,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ambas delegaciones por fin acordaron ... el trato, de verdad.'::text,'firmar'::text,'firmando'::text,'firmar'::text,'Oye, ambas delegaciones por fin acordaron firmar el trato, de verdad.'::text),
(346064,38452,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, les deux délégations ont enfin accepté ... l''accord, sans mentir.'::text,'de signer'::text,'signant'::text,'signer'::text,'Yo, les deux délégations ont enfin accepté de signer l''accord, sans mentir.'::text),
(346067,38452,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, iki heyet de sonunda anlaşmayı ... kabul etti, yalan yok.'::text,'imzalamayı'::text,'imzalayarak'::text,'imzalamak'::text,'Yo, iki heyet de sonunda anlaşmayı imzalamayı kabul etti, yalan yok.'::text),
(346068,38452,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jó, mindkét delegáció végre beleegyezett, hogy ... a megállapodást, nem kamu.'::text,'aláírják'::text,'aláírva'::text,'aláír'::text,'Jó, mindkét delegáció végre beleegyezett, hogy aláírják a megállapodást, nem kamu.'::text),
(346098,38456,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Delegationen werden den Deal bis heute Abend ..., sonst ist alles ruiniert!'::text,'unterschrieben haben'::text,'unterschreiben'::text,'unterschreiben'::text,'Die Delegationen werden den Deal bis heute Abend unterschrieben haben, sonst ist alles ruiniert!'::text),
(346102,38456,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До сьогоднішнього вечора делегації ... угоду, інакше все зруйновано!'::text,'підпишуть'::text,'підписуватимуть'::text,'підписують'::text,'До сьогоднішнього вечора делегації підпишуть угоду, інакше все зруйновано!'::text),
(346101,38456,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para esta noche, las delegaciones ... el acuerdo, o todo estará arruinado!'::text,'habrán firmado'::text,'firmarán'::text,'están firmando'::text,'¡Para esta noche, las delegaciones habrán firmado el acuerdo, o todo estará arruinado!'::text),
(346100,38456,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, les délégations ... l''accord, sinon tout est fichu !'::text,'auront signé'::text,'signeront'::text,'signent'::text,'D''ici ce soir, les délégations auront signé l''accord, sinon tout est fichu !'::text),
(346103,38456,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar heyetler anlaşmayı ..., yoksa her şey mahvolur!'::text,'imzalamış olacak'::text,'imzalayacak'::text,'imzalıyor'::text,'Bu akşama kadar heyetler anlaşmayı imzalamış olacak, yoksa her şey mahvolur!'::text),
(346104,38456,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma estére a delegációk ... a megállapodást, különben minden odavan!'::text,'aláírják'::text,'alá fogják írni'::text,'írják alá'::text,'Ma estére a delegációk aláírják a megállapodást, különben minden odavan!'::text),
(384429,42715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er zitterte vor Angst, als sie den Umschlag mit dem roten Siegel ...!'::text,'hochhielt'::text,'gerade hochhielt'::text,'hochgehalten hat'::text,'Er zitterte vor Angst, als sie den Umschlag mit dem roten Siegel hochhielt!'::text),
(384433,42715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він тремтів від жаху, коли вона ... конверт із червоною печаткою!'::text,'підняла'::text,'піднімала'::text,'підняла'::text,'Він тремтів від жаху, коли вона підняла конверт із червоною печаткою!'::text),
(384432,42715,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él temblaba de terror cuando ella ... el sobre con el sello rojo!'::text,'levantó'::text,'estaba levantando'::text,'ha levantado'::text,'¡Él temblaba de terror cuando ella levantó el sobre con el sello rojo!'::text),
(384431,42715,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il tremblait de terreur quand elle ... l''enveloppe au sceau rouge !'::text,'a brandi'::text,'brandissait'::text,'a brandi'::text,'Il tremblait de terreur quand elle a brandi l''enveloppe au sceau rouge !'::text),
(384434,42715,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, kız kırmızı mühürlü zarfı ... dehşetle titriyordu!'::text,'kaldırdığında'::text,'kaldırırken'::text,'kaldırmışken'::text,'O, kız kırmızı mühürlü zarfı kaldırdığında dehşetle titriyordu!'::text),
(384435,42715,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő rémülten remegett, amikor a lány ... a borítékot a piros pecséttel!'::text,'felemelte'::text,'emelgette'::text,'felemelte'::text,'Ő rémülten remegett, amikor a lány felemelte a borítékot a piros pecséttel!'::text),
(384483,42721,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Siegel auf dem Umschlag ist aus ..., mit einem Stempel geprägt.'::text,'rotem Wachs'::text,'einem roten Wachs'::text,'den roten Wachsen'::text,'Das Siegel auf dem Umschlag ist aus rotem Wachs, mit einem Stempel geprägt.'::text),
(384487,42721,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Печатка на конверті зроблена з ..., відтиснутого штампом.'::text,'червоного воску'::text,'червоного воску'::text,'червоних восків'::text,'Печатка на конверті зроблена з червоного воску, відтиснутого штампом.'::text),
(384486,42721,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sello del sobre está hecho de ... presionada con un tampón.'::text,'cera roja'::text,'una cera roja'::text,'las ceras rojas'::text,'El sello del sobre está hecho de cera roja presionada con un tampón.'::text),
(384485,42721,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sceau de l''enveloppe est fait de ... pressée avec un tampon.'::text,'cire rouge'::text,'une cire rouge'::text,'les cires rouges'::text,'Le sceau de l''enveloppe est fait de cire rouge pressée avec un tampon.'::text),
(384488,42721,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zarftaki mühür, damgayla bastırılmış ... yapılmış.'::text,'kırmızı mumdan'::text,'bir kırmızı mumdan'::text,'kırmızı mumlardan'::text,'Zarftaki mühür, damgayla bastırılmış kırmızı mumdan yapılmış.'::text),
(384489,42721,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A borítékon lévő pecsét anyaga ..., bélyegzővel lenyomva.'::text,'piros viasz'::text,'egy piros viasz'::text,'a piros viaszok'::text,'A borítékon lévő pecsét anyaga piros viasz, bélyegzővel lenyomva.'::text),
(356493,39611,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während der Truck seine Fracht in den Hof ..., winkte der Arbeiter verzweifelt!'::text,'zog'::text,'zog'::text,'gezogen hat'::text,'Während der Truck seine Fracht in den Hof zog, winkte der Arbeiter verzweifelt!'::text),
(356497,39611,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вантажівка ... свій вантаж у двір, робітник відчайдушно махав!'::text,'тягнула'::text,'затягнула'::text,'затягнула'::text,'Поки вантажівка тягнула свій вантаж у двір, робітник відчайдушно махав!'::text),
(356496,39611,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mientras el camión ... su carga al patio, el trabajador hacía señas desesperado!'::text,'arrastraba'::text,'arrastró'::text,'ha arrastrado'::text,'¡Mientras el camión arrastraba su carga al patio, el trabajador hacía señas desesperado!'::text),
(356495,39611,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le camion ... son chargement dans la cour, l''ouvrier faisait des signes désespérés !'::text,'tirait'::text,'a tiré'::text,'a tiré'::text,'Pendant que le camion tirait son chargement dans la cour, l''ouvrier faisait des signes désespérés !'::text),
(356498,39611,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tır yükünü avluya ... işçi çaresizce el sallıyordu!'::text,'çekerken'::text,'çektiğinde'::text,'çekmişken'::text,'Tır yükünü avluya çekerken işçi çaresizce el sallıyordu!'::text),
(356499,39611,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a kamion ... a rakományát az udvarra, a munkás kétségbeesetten integetett!'::text,'húzta'::text,'behúzta'::text,'behúzta'::text,'Miközben a kamion húzta a rakományát az udvarra, a munkás kétségbeesetten integetett!'::text),
(356574,39620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Truck ... den Frachtcontainer gerade über den Kies.'::text,'zieht'::text,'zieht'::text,'hat gezogen'::text,'Der Truck zieht den Frachtcontainer gerade über den Kies.'::text),
(356578,39620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вантажівка просто зараз ... вантажний контейнер по гравію.'::text,'тягне'::text,'тягне'::text,'протягнула'::text,'Вантажівка просто зараз тягне вантажний контейнер по гравію.'::text),
(356577,39620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camión ... el contenedor de carga por la grava ahora mismo.'::text,'está arrastrando'::text,'arrastra'::text,'ha arrastrado'::text,'El camión está arrastrando el contenedor de carga por la grava ahora mismo.'::text),
(356576,39620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le camion ... le conteneur de fret sur le gravier en ce moment.'::text,'tire'::text,'tire'::text,'a tiré'::text,'Le camion tire le conteneur de fret sur le gravier en ce moment.'::text),
(356579,39620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tır şu anda yük konteynerini çakılların üzerinde ...'::text,'çekiyor'::text,'çeker'::text,'çekti'::text,'Tır şu anda yük konteynerini çakılların üzerinde çekiyor.'::text),
(356580,39620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kamion épp most ... a teherkonténert a kavicson.'::text,'húzza'::text,'húzza'::text,'húzta'::text,'A kamion épp most húzza a teherkonténert a kavicson.'::text),
(398721,44303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich macht es ihm Spaß, jeden Kunden mit der Waffel ...'::text,'reinzulegen'::text,'reinzulegen'::text,'reinlegen'::text,'Okay, also angeblich macht es ihm Spaß, jeden Kunden mit der Waffel reinzulegen.'::text),
(398725,44303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, він обожнює ... кожного клієнта з ріжком.'::text,'обманювати'::text,'обманювати'::text,'обманювати'::text,'Коротше, кажуть, він обожнює обманювати кожного клієнта з ріжком.'::text),
(398724,44303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer él disfruta ... a cada cliente con el cucurucho.'::text,'engañando'::text,'engañar'::text,'engañar'::text,'Vale, pues al parecer él disfruta engañando a cada cliente con el cucurucho.'::text),
(398723,44303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment il adore ... chaque client avec le cornet.'::text,'piéger'::text,'piéger'::text,'piéger'::text,'Bon, apparemment il adore piéger chaque client avec le cornet.'::text),
(398726,44303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, anlaşılan o her müşteriyi külahla ... seviyor.'::text,'kandırmayı'::text,'kandırmayı'::text,'kandırmak'::text,'Tamam yani, anlaşılan o her müşteriyi külahla kandırmayı seviyor.'::text),
(398727,44303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag ő imádja ... minden vásárlót a tölcsérrel.'::text,'megtréfálni'::text,'megtréfálni'::text,'megtréfál'::text,'Szóval, állítólag ő imádja megtréfálni minden vásárlót a tölcsérrel.'::text),
(398730,44304,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Starker Move: Du ... den Kunden gerade, und er lacht immer noch.'::text,'veräppelst'::text,'veräppelst'::text,'hast veräppelt'::text,'Starker Move: Du veräppelst den Kunden gerade, und er lacht immer noch.'::text),
(398734,44304,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ефектний хід: ти просто зараз ... того клієнта, а він досі сміється.'::text,'розводиш'::text,'розводиш'::text,'розвів'::text,'Ефектний хід: ти просто зараз розводиш того клієнта, а він досі сміється.'::text),
(398733,44304,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buena jugada: tú ... a ese cliente ahora mismo, y sigue riéndose.'::text,'estás engañando'::text,'engañas'::text,'has engañado'::text,'Buena jugada: tú estás engañando a ese cliente ahora mismo, y sigue riéndose.'::text),
(398732,44304,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Joli coup : tu ... ce client en ce moment, et il rit encore.'::text,'pièges'::text,'pièges'::text,'as piégé'::text,'Joli coup : tu pièges ce client en ce moment, et il rit encore.'::text),
(398735,44304,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şık hamle: sen şu anda o müşteriyi ... ve o hâlâ gülüyor.'::text,'kandırıyorsun'::text,'kandırırsın'::text,'kandırdın'::text,'Şık hamle: sen şu anda o müşteriyi kandırıyorsun ve o hâlâ gülüyor.'::text),
(398736,44304,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ügyes húzás: te épp most ... azt a vásárlót, és még mindig nevet.'::text,'ugratod'::text,'ugratod'::text,'megugrattad'::text,'Ügyes húzás: te épp most ugratod azt a vásárlót, és még mindig nevet.'::text),
(399207,44357,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Licht im ganzen Garten wurde von einem einzigen Schalter ...! Unglaublich!'::text,'eingeschaltet'::text,'eingeschaltet'::text,'eingeschaltet'::text,'Jedes Licht im ganzen Garten wurde von einem einzigen Schalter eingeschaltet! Unglaublich!'::text),
(399211,44357,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожне світло в усьому саду ... одним-єдиним вимикачем! Неймовірно!'::text,'було увімкнено'::text,'увімкнулося'::text,'вмикалося'::text,'Кожне світло в усьому саду було увімкнено одним-єдиним вимикачем! Неймовірно!'::text),
(399210,44357,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada luz de todo el jardín ... con un solo interruptor! ¡Increíble!'::text,'fue encendida'::text,'se ha encendido'::text,'se estaba encendiendo'::text,'¡Cada luz de todo el jardín fue encendida con un solo interruptor! ¡Increíble!'::text),
(399209,44357,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque lumière de tout le jardin ... par un seul interrupteur ! Incroyable !'::text,'a été allumée'::text,'s''est allumée'::text,'s''allumait'::text,'Chaque lumière de tout le jardin a été allumée par un seul interrupteur ! Incroyable !'::text),
(399212,44357,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün bahçedeki her ışık tek bir düğmeyle ...! İnanılmaz!'::text,'açıldı'::text,'açıldı'::text,'açılıyordu'::text,'Bütün bahçedeki her ışık tek bir düğmeyle açıldı! İnanılmaz!'::text),
(399213,44357,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész kertben minden lámpát egyetlen kapcsolóval ...! Hihetetlen!'::text,'kapcsolták fel'::text,'kapcsolt fel'::text,'kapcsolgatták'::text,'Az egész kertben minden lámpát egyetlen kapcsolóval kapcsolták fel! Hihetetlen!'::text),
(349905,38879,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... gerade ein Kabel in die Steckdosenleiste, als der Strom die Lichterkette erreichte.'::text,'steckte'::text,'steckte'::text,'hat gesteckt'::text,'Sie steckte gerade ein Kabel in die Steckdosenleiste, als der Strom die Lichterkette erreichte.'::text),
(349909,38879,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кабель у подовжувач, коли електрика дійшла до гірлянди.'::text,'вставляла'::text,'вставила'::text,'вставила'::text,'Вона вставляла кабель у подовжувач, коли електрика дійшла до гірлянди.'::text),
(349908,38879,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... un cable en la regleta cuando la electricidad llegó a las lucecitas.'::text,'estaba metiendo'::text,'metió'::text,'ha metido'::text,'Ella estaba metiendo un cable en la regleta cuando la electricidad llegó a las lucecitas.'::text),
(349907,38879,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un câble dans la multiprise quand l''électricité a atteint la guirlande lumineuse.'::text,'branchait'::text,'a branché'::text,'a branché'::text,'Elle branchait un câble dans la multiprise quand l''électricité a atteint la guirlande lumineuse.'::text),
(349910,38879,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elektrik ışık zincirine ulaştığında o bir kabloyu uzatma prizine ...'::text,'takıyordu'::text,'taktı'::text,'taktı'::text,'Elektrik ışık zincirine ulaştığında o bir kabloyu uzatma prizine takıyordu.'::text),
(349911,38879,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... egy kábelt az elosztóba, amikor az áram elérte a fényfüzért.'::text,'dugott'::text,'bedugott'::text,'bedugott'::text,'Ő éppen dugott egy kábelt az elosztóba, amikor az áram elérte a fényfüzért.'::text),
(349986,38888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, der Strom ... so eine Woche weg, bis sie ihn wiederhatte, echt.'::text,'war'::text,'war'::text,'ist'::text,'Bro, der Strom war so eine Woche weg, bis sie ihn wiederhatte, echt.'::text),
(349990,38888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, електрики ... десь тиждень, поки вона її не повернула, реально.'::text,'не було'::text,'не було'::text,'нема'::text,'Бро, електрики не було десь тиждень, поки вона її не повернула, реально.'::text),
(349989,38888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la luz ... cortada como una semana cuando la recuperó, en serio.'::text,'había estado'::text,'estaba'::text,'ha estado'::text,'Bro, la luz había estado cortada como una semana cuando la recuperó, en serio.'::text),
(349988,38888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, l''électricité ... coupée genre une semaine quand elle l''a récupérée, sérieux.'::text,'avait été'::text,'était'::text,'a été'::text,'Frère, l''électricité avait été coupée genre une semaine quand elle l''a récupérée, sérieux.'::text),
(349991,38888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o elektriği geri alana kadar elektrik bir hafta falan kesik ..., cidden.'::text,'kalmıştı'::text,'kaldı'::text,'kaldı'::text,'Kanka, o elektriği geri alana kadar elektrik bir hafta falan kesik kalmıştı, cidden.'::text),
(349992,38888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, az áram vagy egy hétig ..., mire visszakapta, komolyan.'::text,'ki volt kapcsolva'::text,'ki volt kapcsolva'::text,'ki van kapcsolva'::text,'Tesó, az áram vagy egy hétig ki volt kapcsolva, mire visszakapta, komolyan.'::text),
(329862,36652,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie sich noch ein bisschen ähnlicher anziehen würden, ... niemand sie auseinanderhalten, logisch.'::text,'könnte'::text,'kann'::text,'hätte'::text,'Wenn sie sich noch ein bisschen ähnlicher anziehen würden, könnte niemand sie auseinanderhalten, logisch.'::text),
(329866,36652,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони вдягалися ще трохи схожіше, ніхто ... їх розрізнити, очевидно.'::text,'не зміг би'::text,'не може'::text,'не зміг би'::text,'Якби вони вдягалися ще трохи схожіше, ніхто не зміг би їх розрізнити, очевидно.'::text),
(329865,36652,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ellas se vistieran un poco más parecido, nadie ... distinguirlas, obviamente.'::text,'podría'::text,'puede'::text,'habría podido'::text,'Si ellas se vistieran un poco más parecido, nadie podría distinguirlas, obviamente.'::text),
(329864,36652,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elles s''habillaient encore un peu plus pareil, personne ne ... les distinguer, évidemment.'::text,'pourrait'::text,'peut'::text,'aurait pu'::text,'Si elles s''habillaient encore un peu plus pareil, personne ne pourrait les distinguer, évidemment.'::text),
(329867,36652,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar biraz daha benzer giyinseler, kimse onları ..., tabii ki.'::text,'ayırt edemezdi'::text,'ayırt edemez'::text,'ayırt edemezdi'::text,'Onlar biraz daha benzer giyinseler, kimse onları ayırt edemezdi, tabii ki.'::text),
(329868,36652,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ők még egy kicsit hasonlóbban öltözködnének, senki sem ... megkülönböztetni őket, nyilván.'::text,'tudná'::text,'tudja'::text,'tudta volna'::text,'Ha ők még egy kicsit hasonlóbban öltözködnének, senki sem tudná megkülönböztetni őket, nyilván.'::text),
(399378,44376,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau sagte, dass sie das nasse Tuch ..., bis das ganze Wasser herausgelaufen war.'::text,'ausgewrungen hatte'::text,'ausgewrungen hat'::text,'auswringt'::text,'Die Frau sagte, dass sie das nasse Tuch ausgewrungen hatte, bis das ganze Wasser herausgelaufen war.'::text),
(399382,44376,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка сказала, що вона ... мокру ганчірку, поки з неї не витекла вся вода.'::text,'викручувала'::text,'викручувала'::text,'викручує'::text,'Жінка сказала, що вона викручувала мокру ганчірку, поки з неї не витекла вся вода.'::text),
(399381,44376,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer dijo que ella ... el trapo mojado hasta que salió toda el agua.'::text,'había retorcido'::text,'ha retorcido'::text,'retuerce'::text,'La mujer dijo que ella había retorcido el trapo mojado hasta que salió toda el agua.'::text),
(399380,44376,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme a dit qu''elle ... le chiffon mouillé jusqu''à ce que toute l''eau soit sortie.'::text,'avait tordu'::text,'a tordu'::text,'tord'::text,'La femme a dit qu''elle avait tordu le chiffon mouillé jusqu''à ce que toute l''eau soit sortie.'::text),
(399383,44376,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın, bütün su çıkana kadar ıslak bezi ... söyledi.'::text,'sıktığını'::text,'sıktığını'::text,'sıktığını'::text,'Kadın, bütün su çıkana kadar ıslak bezi sıktığını söyledi.'::text),
(399384,44376,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő azt mondta, hogy ő addig ... a vizes rongyot, amíg az összes víz ki nem folyt belőle.'::text,'csavarta'::text,'csavarta'::text,'csavarja'::text,'A nő azt mondta, hogy ő addig csavarta a vizes rongyot, amíg az összes víz ki nem folyt belőle.'::text),
(399423,44381,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... den Teig zehn Minuten lang, bevor das Mehl explodierte. Leicht chaotisch.'::text,'drehten'::text,'drehen'::text,'drehten'::text,'Sie drehten den Teig zehn Minuten lang, bevor das Mehl explodierte. Leicht chaotisch.'::text),
(399427,44381,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ... те тісто десять хвилин, поки борошно не вибухнуло. Трохи безладно.'::text,'крутили'::text,'крутять'::text,'крутили'::text,'Вони крутили те тісто десять хвилин, поки борошно не вибухнуло. Трохи безладно.'::text),
(399426,44381,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ellos ... esa masa durante diez minutos antes de que la harina explotara. Un pelín desordenado.'::text,'habían estado retorciendo'::text,'han estado retorciendo'::text,'estaban retorciendo'::text,'Ellos habían estado retorciendo esa masa durante diez minutos antes de que la harina explotara. Un pelín desordenado.'::text),
(399425,44381,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... cette pâte depuis dix minutes quand la farine a explosé. Légèrement salissant.'::text,'tordaient'::text,'tordent'::text,'tordaient'::text,'Ils tordaient cette pâte depuis dix minutes quand la farine a explosé. Légèrement salissant.'::text),
(399428,44381,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onlar un patlamadan önce o hamuru on dakika ...; biraz dağınık.'::text,'bükmüşlerdi'::text,'büküyorlar'::text,'büküyorlardı'::text,'Onlar un patlamadan önce o hamuru on dakika bükmüşlerdi; biraz dağınık.'::text),
(399429,44381,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők tíz percig ... azt a tésztát, mielőtt a liszt felrobbant. Kicsit kaotikus.'::text,'csavarták'::text,'csavarják'::text,'csavarták'::text,'Ők tíz percig csavarták azt a tésztát, mielőtt a liszt felrobbant. Kicsit kaotikus.'::text),
(343722,38192,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste versprechen, dass sie den Laib im Innenhof auf einmal ...; toller Plan, logisch.'::text,'essen werden'::text,'essen werden'::text,'essen'::text,'Die Gäste versprechen, dass sie den Laib im Innenhof auf einmal essen werden; toller Plan, logisch.'::text),
(343726,38192,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості обіцяють, що вони ... хлібину у дворику за один раз. Чудовий план, очевидно.'::text,'з''їдять'::text,'їстимуть'::text,'їдять'::text,'Гості обіцяють, що вони з''їдять хлібину у дворику за один раз. Чудовий план, очевидно.'::text),
(343725,38192,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados prometen que ... la hogaza en el patio de una vez. Gran plan, obviamente.'::text,'se comerán'::text,'estarán comiendo'::text,'están comiendo'::text,'Los invitados prometen que se comerán la hogaza en el patio de una vez. Gran plan, obviamente.'::text),
(343724,38192,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités promettent qu''ils ... la miche dans la cour d''un seul coup. Super plan, évidemment.'::text,'mangeront'::text,'seront en train de manger'::text,'mangent'::text,'Les invités promettent qu''ils mangeront la miche dans la cour d''un seul coup. Super plan, évidemment.'::text),
(343727,38192,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler somunu avluda tek seferde ... söz veriyor. Harika plan, tabii ki.'::text,'yiyeceklerine'::text,'yiyor olacaklarına'::text,'yediklerine'::text,'Misafirler somunu avluda tek seferde yiyeceklerine söz veriyor. Harika plan, tabii ki.'::text),
(343728,38192,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek megígérik, hogy egyszerre ... a cipót az udvaron. Remek terv, nyilván.'::text,'megeszik'::text,'enni fogják'::text,'eszik'::text,'A vendégek megígérik, hogy egyszerre megeszik a cipót az udvaron. Remek terv, nyilván.'::text),
(343785,38199,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn es geregnet hätte, ... die Gäste nicht im Innenhof gegessen.'::text,'hätten'::text,'werden'::text,'hatten'::text,'Wenn es geregnet hätte, hätten die Gäste nicht im Innenhof gegessen.'::text),
(343789,38199,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби пішов дощ, гості ... вечері у дворику.'::text,'не мали б'::text,'не матимуть'::text,'не мали'::text,'Якби пішов дощ, гості не мали б вечері у дворику.'::text),
(343788,38199,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si hubiera llovido, los invitados ... en el patio.'::text,'no habrían cenado'::text,'no cenarán'::text,'no cenaron'::text,'Si hubiera llovido, los invitados no habrían cenado en el patio.'::text),
(343787,38199,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait plu, les invités ... dans la cour.'::text,'n''auraient pas dîné'::text,'ne dîneront pas'::text,'n''ont pas dîné'::text,'S''il avait plu, les invités n''auraient pas dîné dans la cour.'::text),
(343790,38199,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağmur yağsaydı misafirler avluda akşam yemeği ...'::text,'yemezlerdi'::text,'yemeyecek'::text,'yemedi'::text,'Yağmur yağsaydı misafirler avluda akşam yemeği yemezlerdi.'::text),
(343791,38199,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha esett volna az eső, a vendégek ... az udvaron.'::text,'nem vacsoráztak volna'::text,'nem fognak vacsorázni'::text,'nem vacsoráztak'::text,'Ha esett volna az eső, a vendégek nem vacsoráztak volna az udvaron.'::text),
(352992,39222,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... sie gerade die Füllung in den Teig, als der Junge einen Löffel schnappte.'::text,'wickelte'::text,'wickelte'::text,'wickelt'::text,'Okay, also angeblich wickelte sie gerade die Füllung in den Teig, als der Junge einen Löffel schnappte.'::text),
(352996,39222,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, вона ... начинку в тісто, коли хлопчик схопив ложку.'::text,'загортала'::text,'загорнула'::text,'загорнула'::text,'Коротше, кажуть, вона загортала начинку в тісто, коли хлопчик схопив ложку.'::text),
(352995,39222,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, al parecer ella ... el relleno en la masa cuando el niño agarró una cuchara.'::text,'estaba envolviendo'::text,'envolvió'::text,'ha envuelto'::text,'Vale, al parecer ella estaba envolviendo el relleno en la masa cuando el niño agarró una cuchara.'::text),
(352994,39222,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, apparemment elle ... la garniture dans la pâte quand le garçon a attrapé une cuillère.'::text,'enfermait'::text,'a enfermé'::text,'a enfermé'::text,'Bon, apparemment elle enfermait la garniture dans la pâte quand le garçon a attrapé une cuillère.'::text),
(352997,39222,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, anlaşılan oğlan kaşığı kaptığında o dolguyu hamura ...'::text,'sarıyordu'::text,'sardı'::text,'sarmış'::text,'Tamam yani, anlaşılan oğlan kaşığı kaptığında o dolguyu hamura sarıyordu.'::text),
(352998,39222,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval, állítólag ő éppen ... a tölteléket a tésztába, amikor a fiú elkapott egy kanalat.'::text,'hajtogatta'::text,'behajtotta'::text,'behajtotta'::text,'Szóval, állítólag ő éppen hajtogatta a tölteléket a tésztába, amikor a fiú elkapott egy kanalat.'::text),
(353073,39231,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie drückt jeden Rand fest zu, ... die Füllung in der Pfanne ausläuft.'::text,'falls'::text,'damit'::text,'wegen'::text,'Sie drückt jeden Rand fest zu, falls die Füllung in der Pfanne ausläuft.'::text),
(353077,39231,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона щільно закриває кожен край, ... начинка витече на сковорідці.'::text,'на випадок, якщо'::text,'щоб'::text,'через'::text,'Вона щільно закриває кожен край, на випадок, якщо начинка витече на сковорідці.'::text),
(353076,39231,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella cierra bien cada borde ... el relleno se sale en la sartén.'::text,'por si'::text,'para que'::text,'debido a'::text,'Ella cierra bien cada borde por si el relleno se sale en la sartén.'::text),
(353075,39231,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pince chaque bord ... la garniture coulerait dans la poêle.'::text,'au cas où'::text,'pour que'::text,'en raison de'::text,'Elle pince chaque bord au cas où la garniture coulerait dans la poêle.'::text),
(353078,39231,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dolgu tavada dışarı sızar ... her kenarı sıkıca kapatıyor.'::text,'diye'::text,'ki'::text,'yüzünden'::text,'O, dolgu tavada dışarı sızar diye her kenarı sıkıca kapatıyor.'::text),
(353079,39231,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő minden szélét szorosan összenyomja, ... a töltelék kifolyik a serpenyőben.'::text,'arra az esetre, ha'::text,'hogy'::text,'miatt'::text,'Ő minden szélét szorosan összenyomja, arra az esetre, ha a töltelék kifolyik a serpenyőben.'::text),
(371154,41240,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wind stark bleibt, ... der Drachen seines Neffen noch höher.'::text,'fliegt'::text,'flöge'::text,'flog'::text,'Wenn der Wind stark bleibt, fliegt der Drachen seines Neffen noch höher.'::text),
(371158,41240,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вітер залишиться сильним, повітряний змій його племінника ... ще вище.'::text,'полетить'::text,'полетів би'::text,'полетів'::text,'Якщо вітер залишиться сильним, повітряний змій його племінника полетить ще вище.'::text),
(371157,41240,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el viento sigue fuerte, la cometa de su sobrino ... aún más alto.'::text,'volará'::text,'volaría'::text,'voló'::text,'Si el viento sigue fuerte, la cometa de su sobrino volará aún más alto.'::text),
(371156,41240,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent reste fort, le cerf-volant de son neveu ... encore plus haut.'::text,'volera'::text,'volerait'::text,'a volé'::text,'Si le vent reste fort, le cerf-volant de son neveu volera encore plus haut.'::text),
(371159,41240,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rüzgâr güçlü kalırsa yeğeninin uçurtması daha da yükseğe ...'::text,'uçacak'::text,'uçardı'::text,'uçtu'::text,'Rüzgâr güçlü kalırsa yeğeninin uçurtması daha da yükseğe uçacak.'::text),
(371160,41240,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a szél erős marad, az unokaöccse sárkánya még magasabbra ...'::text,'száll'::text,'szállna'::text,'szállt'::text,'Ha a szél erős marad, az unokaöccse sárkánya még magasabbra száll.'::text),
(387966,43108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er könnte einen Freund dazu bringen, ihm die engen Fleeceärmel von den Armen ...'::text,'zu ziehen'::text,'ziehen'::text,'ziehend'::text,'Er könnte einen Freund dazu bringen, ihm die engen Fleeceärmel von den Armen zu ziehen.'::text),
(387970,43108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він міг би попросити друга ... тісні флісові рукави з його рук.'::text,'стягнути'::text,'стягнути'::text,'стягування'::text,'Він міг би попросити друга стягнути тісні флісові рукави з його рук.'::text),
(387969,43108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él podría conseguir que un amigo le ... las mangas ajustadas del forro polar.'::text,'quitara'::text,'quite'::text,'quitando'::text,'Él podría conseguir que un amigo le quitara las mangas ajustadas del forro polar.'::text),
(387968,43108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il pourrait demander à un ami ... les manches serrées de sa polaire.'::text,'de lui retirer'::text,'lui retirer'::text,'lui retirant'::text,'Il pourrait demander à un ami de lui retirer les manches serrées de sa polaire.'::text),
(387971,43108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, dar polar kollarını kollarından ... bir arkadaşını ikna edebilirdi.'::text,'çekmesi için'::text,'çeksin diye'::text,'çekerek'::text,'O, dar polar kollarını kollarından çekmesi için bir arkadaşını ikna edebilirdi.'::text),
(387972,43108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő megkérhetne egy barátot, hogy ... le a szűk polárujjakat a karjáról.'::text,'húzza'::text,'húzza'::text,'húzva'::text,'Ő megkérhetne egy barátot, hogy húzza le a szűk polárujjakat a karjáról.'::text),
(389226,43248,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die ganze Stadt diese Solidarität zeigen würde, ... sich die Menschenkette kilometerweit.'::text,'erstreckte'::text,'erstreckt'::text,'erstreckt'::text,'Wenn die ganze Stadt diese Solidarität zeigen würde, erstreckte sich die Menschenkette kilometerweit.'::text),
(389230,43248,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби все місто проявило таку солідарність, живий ланцюг ... на кілометри.'::text,'розтягнувся б'::text,'розтягнеться'::text,'тягнеться'::text,'Якби все місто проявило таку солідарність, живий ланцюг розтягнувся б на кілометри.'::text),
(389229,43248,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si toda la ciudad mostrara esta solidaridad, la cadena humana ... durante kilómetros.'::text,'se extendería'::text,'se extenderá'::text,'se extiende'::text,'Si toda la ciudad mostrara esta solidaridad, la cadena humana se extendería durante kilómetros.'::text),
(389228,43248,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si toute la ville montrait cette solidarité, la chaîne humaine ... sur des kilomètres.'::text,'s''étendrait'::text,'s''étendra'::text,'s''étend'::text,'Si toute la ville montrait cette solidarité, la chaîne humaine s''étendrait sur des kilomètres.'::text),
(389231,43248,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün şehir bu dayanışmayı gösterse, insan zinciri kilometrelerce ...'::text,'uzanırdı'::text,'uzanacak'::text,'uzanıyor'::text,'Bütün şehir bu dayanışmayı gösterse, insan zinciri kilometrelerce uzanırdı.'::text),
(389232,43248,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az egész város ilyen szolidaritást mutatna, az élőlánc kilométereken át ...'::text,'nyúlna'::text,'fog nyúlni'::text,'nyúlik'::text,'Ha az egész város ilyen szolidaritást mutatna, az élőlánc kilométereken át nyúlna.'::text),
(342651,38073,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ein Typ hat mir erzählt, dass sie die ganze Zeit mit völlig Fremden ...'::text,'zusammengearbeitet hatten'::text,'zusammengearbeitet haben'::text,'zusammenarbeiten'::text,'Mädel, ein Typ hat mir erzählt, dass sie die ganze Zeit mit völlig Fremden zusammengearbeitet hatten.'::text),
(342655,38073,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, один хлопець сказав мені, що вони весь час ... з абсолютно незнайомими людьми.'::text,'співпрацювали'::text,'співпрацювали'::text,'співпрацюють'::text,'Подруго, один хлопець сказав мені, що вони весь час співпрацювали з абсолютно незнайомими людьми.'::text),
(342654,38073,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, un chico me dijo que ellos ... con completos desconocidos todo el tiempo.'::text,'habían cooperado'::text,'han cooperado'::text,'cooperan'::text,'Amiga, un chico me dijo que ellos habían cooperado con completos desconocidos todo el tiempo.'::text),
(342653,38073,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, un mec m''a dit qu''ils ... avec de parfaits inconnus tout le temps.'::text,'avaient coopéré'::text,'ont coopéré'::text,'coopèrent'::text,'Meuf, un mec m''a dit qu''ils avaient coopéré avec de parfaits inconnus tout le temps.'::text),
(342656,38073,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bir çocuk bana onların baştan sona tamamen yabancılarla ... söyledi.'::text,'iş birliği yaptıklarını'::text,'iş birliği yaptıklarını'::text,'iş birliği yaptıklarını'::text,'Kızım, bir çocuk bana onların baştan sona tamamen yabancılarla iş birliği yaptıklarını söyledi.'::text),
(342657,38073,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, egy srác azt mondta, hogy ők végig teljesen idegenekkel ...'::text,'működtek együtt'::text,'működtek együtt'::text,'működnek együtt'::text,'Csajszi, egy srác azt mondta, hogy ők végig teljesen idegenekkel működtek együtt.'::text),
(400080,44454,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schirm ... vom Wind auf links gedreht, also ist er jetzt nutzlos.'::text,'wurde'::text,'hat'::text,'wird'::text,'Der Schirm wurde vom Wind auf links gedreht, also ist er jetzt nutzlos.'::text),
(400084,44454,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Парасольку ... вітром навиворіт, тож тепер вона марна.'::text,'вивернуло'::text,'вивернула'::text,'вивертає'::text,'Парасольку вивернуло вітром навиворіт, тож тепер вона марна.'::text),
(400083,44454,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El paraguas ... del revés por el viento, así que ahora es inútil.'::text,'fue volteado'::text,'volteó'::text,'está volteando'::text,'El paraguas fue volteado del revés por el viento, así que ahora es inútil.'::text),
(400082,44454,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le parapluie ... retourné par le vent, alors maintenant il est inutile.'::text,'a été'::text,'a'::text,'est'::text,'Le parapluie a été retourné par le vent, alors maintenant il est inutile.'::text),
(400085,44454,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şemsiye rüzgârla ters ..., o yüzden artık işe yaramaz.'::text,'çevrildi'::text,'çevirdi'::text,'çeviriyor'::text,'Şemsiye rüzgârla ters çevrildi, o yüzden artık işe yaramaz.'::text),
(400086,44454,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az esernyőt a szél ..., így most használhatatlan.'::text,'kifordította'::text,'kifordította'::text,'fordítja ki'::text,'Az esernyőt a szél kifordította, így most használhatatlan.'::text),
(369300,41034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nebelige Hügel ... ihr schlimmster Albtraum, aber jetzt wandert sie im Regen durch sie hindurch!'::text,'waren früher'::text,'waren'::text,'waren gewohnt'::text,'Nebelige Hügel waren früher ihr schlimmster Albtraum, aber jetzt wandert sie im Regen durch sie hindurch!'::text),
(369304,41034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Туманні пагорби ... її найгіршим кошмаром, а тепер вона гуляє ними під дощем!'::text,'колись були'::text,'були б'::text,'звикли бути'::text,'Туманні пагорби колись були її найгіршим кошмаром, а тепер вона гуляє ними під дощем!'::text),
(369303,41034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las colinas brumosas ... ser su peor pesadilla, pero ahora ella camina por ellas bajo la lluvia!'::text,'solían'::text,'solían'::text,'estaban acostumbradas a'::text,'¡Las colinas brumosas solían ser su peor pesadilla, pero ahora ella camina por ellas bajo la lluvia!'::text),
(369302,41034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Autrefois, les collines brumeuses ... son pire cauchemar, mais maintenant elle les traverse sous la pluie !'::text,'étaient'::text,'étaient'::text,'avaient l''habitude d''être'::text,'Autrefois, les collines brumeuses étaient son pire cauchemar, mais maintenant elle les traverse sous la pluie !'::text),
(369305,41034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sisli tepeler eskiden onun en büyük kâbusu ..., ama şimdi o yağmurda aralarında yürüyor!'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Sisli tepeler eskiden onun en büyük kâbusu olurdu, ama şimdi o yağmurda aralarında yürüyor!'::text),
(369306,41034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ködös dombok régen a legrosszabb rémálmai ..., de most ő az esőben sétál köztük!'::text,'voltak'::text,'lettek volna'::text,'voltak megszokva'::text,'A ködös dombok régen a legrosszabb rémálmai voltak, de most ő az esőben sétál köztük!'::text),
(334551,37173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er die Kreuzung verließ, hatten ihn die Werbetafeln für immer ...!'::text,'umgehauen'::text,'umgehauen'::text,'umhauen'::text,'Als er die Kreuzung verließ, hatten ihn die Werbetafeln für immer umgehauen!'::text),
(334555,37173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він покинув перехрестя, білборди вже назавжди ... йому мозок!'::text,'підірвали'::text,'підірвали'::text,'підривають'::text,'Коли він покинув перехрестя, білборди вже назавжди підірвали йому мозок!'::text),
(334554,37173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando él dejó el cruce, las vallas publicitarias le ... la cabeza para siempre!'::text,'habían volado'::text,'han volado'::text,'vuelan'::text,'¡Para cuando él dejó el cruce, las vallas publicitarias le habían volado la cabeza para siempre!'::text),
(334553,37173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le temps qu''il quitte le carrefour, les panneaux publicitaires lui ... la tête pour toujours !'::text,'avaient retourné'::text,'ont retourné'::text,'retournent'::text,'Le temps qu''il quitte le carrefour, les panneaux publicitaires lui avaient retourné la tête pour toujours !'::text),
(334556,37173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kavşaktan ayrıldığında reklam panoları aklını sonsuza dek ...!'::text,'almıştı'::text,'aldı'::text,'alıyor'::text,'O kavşaktan ayrıldığında reklam panoları aklını sonsuza dek almıştı!'::text),
(334557,37173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire ő elhagyta a kereszteződést, az óriásplakátok örökre ... az agyát!'::text,'eldobták'::text,'eldobták'::text,'dobják el'::text,'Mire ő elhagyta a kereszteződést, az óriásplakátok örökre eldobták az agyát!'::text),
(334605,37179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Werbetafeln in der Stadt, bevor er die Fähre nahm.'::text,'sah'::text,'sah'::text,'sieht'::text,'Er sah die Werbetafeln in der Stadt, bevor er die Fähre nahm.'::text),
(334609,37179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... білборди в місті ще до того, як сів на пором.'::text,'бачив'::text,'бачив'::text,'бачить'::text,'Він бачив білборди в місті ще до того, як сів на пором.'::text),
(334608,37179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... las vallas publicitarias de la ciudad antes de tomar el ferri.'::text,'había visto'::text,'ha visto'::text,'ve'::text,'Él había visto las vallas publicitarias de la ciudad antes de tomar el ferri.'::text),
(334607,37179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... les panneaux publicitaires en ville avant de prendre le ferry.'::text,'avait vu'::text,'a vu'::text,'voit'::text,'Il avait vu les panneaux publicitaires en ville avant de prendre le ferry.'::text),
(334610,37179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O vapura binmeden önce şehirdeki reklam panolarını ...'::text,'görmüştü'::text,'gördü'::text,'görüyor'::text,'O vapura binmeden önce şehirdeki reklam panolarını görmüştü.'::text),
(334611,37179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... az óriásplakátokat a városban, mielőtt kompra szállt.'::text,'látta'::text,'látta'::text,'látja'::text,'Ő látta az óriásplakátokat a városban, mielőtt kompra szállt.'::text),
(348654,38740,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schafft es, die schweren Türen ..., und stellt sich in den Türrahmen.'::text,'aufzuziehen'::text,'aufziehend'::text,'aufziehen'::text,'Sie schafft es, die schweren Türen aufzuziehen, und stellt sich in den Türrahmen.'::text),
(348658,38740,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона примудряється ... важкі двері й стає в дверному прорізі.'::text,'розсунути'::text,'розсування'::text,'розсунути'::text,'Вона примудряється розсунути важкі двері й стає в дверному прорізі.'::text),
(348657,38740,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella consigue ... las pesadas puertas y se queda en el umbral.'::text,'abrir'::text,'abriendo'::text,'abrir'::text,'Ella consigue abrir las pesadas puertas y se queda en el umbral.'::text),
(348656,38740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle parvient à ... les lourdes portes et se tient dans l''embrasure.'::text,'écarter'::text,'écartant'::text,'écarter'::text,'Elle parvient à écarter les lourdes portes et se tient dans l''embrasure.'::text),
(348659,38740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O ağır kapıları ... başarıyor ve kapı aralığında duruyor.'::text,'açmayı'::text,'açarak'::text,'aç'::text,'O ağır kapıları açmayı başarıyor ve kapı aralığında duruyor.'::text),
(348660,38740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neki sikerül ... a nehéz ajtókat, és ő megáll az ajtónyílásban.'::text,'széthúznia'::text,'széthúzva'::text,'széthúz'::text,'Neki sikerül széthúznia a nehéz ajtókat, és ő megáll az ajtónyílásban.'::text),
(348681,38743,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich ewig mit den Schlössern ab, bevor sie den Eingang erreichte. Ein kurzer Besuch, logisch.'::text,'mühte'::text,'müht'::text,'mühte'::text,'Sie mühte sich ewig mit den Schlössern ab, bevor sie den Eingang erreichte. Ein kurzer Besuch, logisch.'::text),
(348685,38743,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... із замками цілу вічність, перш ніж дісталася до входу. Швидкий візит, очевидно.'::text,'воювала'::text,'воює'::text,'воювала'::text,'Вона воювала із замками цілу вічність, перш ніж дісталася до входу. Швидкий візит, очевидно.'::text),
(348684,38743,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... con las cerraduras una eternidad antes de llegar a la entrada. Una visita rápida, obviamente.'::text,'había estado peleándose'::text,'ha estado peleándose'::text,'estaba peleándose'::text,'Ella había estado peleándose con las cerraduras una eternidad antes de llegar a la entrada. Una visita rápida, obviamente.'::text),
(348683,38743,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... avec les serrures pendant une éternité avant d''atteindre l''entrée. Une visite rapide, évidemment.'::text,'avait bataillé'::text,'a bataillé'::text,'bataillait'::text,'Elle avait bataillé avec les serrures pendant une éternité avant d''atteindre l''entrée. Une visite rapide, évidemment.'::text),
(348686,38743,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O girişe varmadan önce kilitlerle uzun süre ...; hızlı bir ziyaret, tabii ki.'::text,'uğraşmıştı'::text,'uğraşıyor'::text,'uğraşıyordu'::text,'O girişe varmadan önce kilitlerle uzun süre uğraşmıştı; hızlı bir ziyaret, tabii ki.'::text),
(348687,38743,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő egy örökkévalóságig ... a zárakkal, mielőtt elérte a bejáratot. Gyors látogatás, nyilván.'::text,'küszködött'::text,'küszködik'::text,'küszködött'::text,'Ő egy örökkévalóságig küszködött a zárakkal, mielőtt elérte a bejáratot. Gyors látogatás, nyilván.'::text),
