(347263,38585,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До півночі вона ... кожен пристрій у квартирі. Абсолютно все згасне!'::text,'відключить'::text,'відключатиме'::text,'відключає'::text,'До півночі вона відключить кожен пристрій у квартирі. Абсолютно все згасне!'::text),
