(362244,40250,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Stempel keine Tinte hätte, ... er keinen Abdruck im Pass.'::text,'hinterließe'::text,'hinterlässt'::text,'hinterlässt'::text,'Wenn der Stempel keine Tinte hätte, hinterließe er keinen Abdruck im Pass.'::text),
(362248,40250,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби штамп не мав чорнила, він ... жодного сліду в паспорті.'::text,'не залишив би'::text,'не залишить'::text,'не залишає'::text,'Якби штамп не мав чорнила, він не залишив би жодного сліду в паспорті.'::text),
(362247,40250,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no tuviera tinta, el sello ... ninguna marca en el pasaporte.'::text,'no dejaría'::text,'no dejará'::text,'no deja'::text,'Si no tuviera tinta, el sello no dejaría ninguna marca en el pasaporte.'::text),
(362246,40250,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le tampon n''avait pas d''encre, il ... aucune marque sur le passeport.'::text,'ne laisserait'::text,'ne laissera'::text,'ne laisse'::text,'Si le tampon n''avait pas d''encre, il ne laisserait aucune marque sur le passeport.'::text),
(362249,40250,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Damganın mürekkebi olmasaydı, damga pasaportta hiç iz ...'::text,'bırakmazdı'::text,'bırakmayacak'::text,'bırakmıyor'::text,'Damganın mürekkebi olmasaydı, damga pasaportta hiç iz bırakmazdı.'::text),
(362250,40250,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem lenne tinta benne, a pecsét ... semmilyen nyomot az útlevélen.'::text,'nem hagyna'::text,'nem fog hagyni'::text,'nem hagy'::text,'Ha nem lenne tinta benne, a pecsét nem hagyna semmilyen nyomot az útlevélen.'::text),
(331023,36781,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, die Menge ... ihre 10er-Karten schon bereit, bevor die Genehmigung überhaupt kam, echt.'::text,'hatte'::text,'hat'::text,'hat'::text,'Bro, die Menge hatte ihre 10er-Karten schon bereit, bevor die Genehmigung überhaupt kam, echt.'::text),
(331027,36781,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, натовп ... свої картки з 10 напоготові ще до того, як взагалі прийшло схвалення, реально.'::text,'мав'::text,'має'::text,'має'::text,'Бро, натовп мав свої картки з 10 напоготові ще до того, як взагалі прийшло схвалення, реально.'::text),
(331026,36781,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la gente ... sus carteles de 10 listos antes de que llegara siquiera la aprobación, en serio.'::text,'tenía'::text,'tiene'::text,'tiene'::text,'Bro, la gente tenía sus carteles de 10 listos antes de que llegara siquiera la aprobación, en serio.'::text),
(331025,36781,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frère, la foule ... ses cartons 10 prêts avant même que l''approbation arrive, sérieux.'::text,'avait'::text,'a'::text,'a'::text,'Frère, la foule avait ses cartons 10 prêts avant même que l''approbation arrive, sérieux.'::text),
(331028,36781,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onay daha gelmeden kalabalık 10''luk kartlarını hazır ..., cidden.'::text,'etmişti'::text,'etti'::text,'ediyor'::text,'Kanka, onay daha gelmeden kalabalık 10''luk kartlarını hazır etmişti, cidden.'::text),
(331029,36781,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a tömeg már a jóváhagyás előtt ... a 10-es kártyáit, komolyan.'::text,'előkészítette'::text,'előkészítette'::text,'előkészíti'::text,'Tesó, a tömeg már a jóváhagyás előtt előkészítette a 10-es kártyáit, komolyan.'::text),
(331068,36786,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Monatelang ... er vor diesem unglaublichen Moment auf die Genehmigung!'::text,'wartete'::text,'wartet'::text,'wartet'::text,'Monatelang wartete er vor diesem unglaublichen Moment auf die Genehmigung!'::text),
(331072,36786,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... схвалення місяцями перед цією неймовірною миттю!'::text,'чекав'::text,'чекає'::text,'чекає'::text,'Він чекав схвалення місяцями перед цією неймовірною миттю!'::text),
(331071,36786,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... la aprobación durante meses antes de este momento increíble!'::text,'había estado esperando'::text,'ha estado esperando'::text,'está esperando'::text,'¡Él había estado esperando la aprobación durante meses antes de este momento increíble!'::text),
(331070,36786,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''approbation depuis des mois avant ce moment incroyable !'::text,'attendait'::text,'attend'::text,'attend'::text,'Il attendait l''approbation depuis des mois avant ce moment incroyable !'::text),
(331073,36786,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bu inanılmaz andan önce aylarca onayı ...!'::text,'beklemişti'::text,'bekliyor'::text,'bekliyor'::text,'O bu inanılmaz andan önce aylarca onayı beklemişti!'::text),
(331074,36786,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő hónapokig ... a jóváhagyásra e hihetetlen pillanat előtt!'::text,'várt'::text,'vár'::text,'vár'::text,'Ő hónapokig várt a jóváhagyásra e hihetetlen pillanat előtt!'::text),
(400962,44552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie denkt, dass sie morgen noch ein Vitamin ..., weil dieses schon weg ist.'::text,'nehmen wird'::text,'nehmen wird'::text,'nimmt'::text,'Sie denkt, dass sie morgen noch ein Vitamin nehmen wird, weil dieses schon weg ist.'::text),
(400966,44552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона думає, що завтра ... ще один вітамін, бо цей уже зник.'::text,'вип''є'::text,'питиме'::text,'п''є'::text,'Вона думає, що завтра вип''є ще один вітамін, бо цей уже зник.'::text),
(400965,44552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella cree que mañana ... otra vitamina, porque esta ya no está.'::text,'tomará'::text,'estará tomando'::text,'está tomando'::text,'Ella cree que mañana tomará otra vitamina, porque esta ya no está.'::text),
(400964,44552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle pense qu''elle ... une autre vitamine demain, parce que celle-ci a déjà disparu.'::text,'prendra'::text,'sera en train de prendre'::text,'prend'::text,'Elle pense qu''elle prendra une autre vitamine demain, parce que celle-ci a déjà disparu.'::text),
(400967,44552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O yarın bir vitamin daha ... düşünüyor, çünkü bu çoktan bitti.'::text,'alacağını'::text,'alıyor olacağını'::text,'aldığını'::text,'O yarın bir vitamin daha alacağını düşünüyor, çünkü bu çoktan bitti.'::text),
(400968,44552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt hiszi, hogy holnap ... még egy vitamint, mert ez már elfogyott.'::text,'bevesz'::text,'be fog venni'::text,'bevesz'::text,'Ő azt hiszi, hogy holnap bevesz még egy vitamint, mert ez már elfogyott.'::text),
(401025,44559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Vitamin nicht reingeworfen hätte, ... das Wasser nicht orange geworden. Was für ein Verlust, logisch.'::text,'wäre'::text,'wird'::text,'wurde'::text,'Wenn sie das Vitamin nicht reingeworfen hätte, wäre das Wasser nicht orange geworden. Was für ein Verlust, logisch.'::text),
(401029,44559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не кинула туди вітамін, вода ... помаранчевою. Яка втрата, очевидно.'::text,'не стала б'::text,'не стане'::text,'не стала'::text,'Якби вона не кинула туди вітамін, вода не стала б помаранчевою. Яка втрата, очевидно.'::text),
(401028,44559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ella no hubiera echado la vitamina, el agua ... naranja. Qué pérdida, obviamente.'::text,'no se habría vuelto'::text,'no se volverá'::text,'no se volvió'::text,'Si ella no hubiera echado la vitamina, el agua no se habría vuelto naranja. Qué pérdida, obviamente.'::text),
(401027,44559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle n''avait pas mis la vitamine, l''eau ... orange. Quelle perte, évidemment.'::text,'ne serait pas devenue'::text,'ne deviendra pas'::text,'n''est pas devenue'::text,'Si elle n''avait pas mis la vitamine, l''eau ne serait pas devenue orange. Quelle perte, évidemment.'::text),
(401030,44559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O vitamini atmasaydı su turuncuya ...; ne kayıp ama, tabii ki.'::text,'dönmezdi'::text,'dönmeyecek'::text,'dönmedi'::text,'O vitamini atmasaydı su turuncuya dönmezdi; ne kayıp ama, tabii ki.'::text),
(401031,44559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő nem dobta volna bele a vitamint, a víz ... narancssárga. Micsoda veszteség, nyilván.'::text,'nem lett volna'::text,'nem lesz'::text,'nem lett'::text,'Ha ő nem dobta volna bele a vitamint, a víz nem lett volna narancssárga. Micsoda veszteség, nyilván.'::text),
(364431,40493,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der rissige Boden am Fuß des Vulkans ... von glühender Lava bedeckt.'::text,'ist'::text,'bedeckt'::text,'bedeckte'::text,'Der rissige Boden am Fuß des Vulkans ist von glühender Lava bedeckt.'::text),
(364435,40493,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Потріскана земля біля підніжжя вулкана ... розпеченою лавою.'::text,'вкрита'::text,'вкриває'::text,'вкривала'::text,'Потріскана земля біля підніжжя вулкана вкрита розпеченою лавою.'::text),
(364434,40493,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El suelo agrietado al pie del volcán ... de lava incandescente.'::text,'está cubierto'::text,'cubre'::text,'estaba cubriendo'::text,'El suelo agrietado al pie del volcán está cubierto de lava incandescente.'::text),
(364433,40493,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sol craquelé au pied du volcan ... de lave incandescente.'::text,'est couvert'::text,'couvre'::text,'couvrait'::text,'Le sol craquelé au pied du volcan est couvert de lave incandescente.'::text),
(364436,40493,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yanardağın eteğindeki çatlak zemin parlayan lavla ...'::text,'kaplanmış'::text,'kaplıyor'::text,'kaplıyordu'::text,'Yanardağın eteğindeki çatlak zemin parlayan lavla kaplanmış.'::text),
(364437,40493,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vulkán lábánál a repedezett talaj ... izzó lávával.'::text,'be van borítva'::text,'borít'::text,'borított'::text,'A vulkán lábánál a repedezett talaj be van borítva izzó lávával.'::text),
(386841,42983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Übelkeit ... jetzt schon seit einer Stunde jeden Fahrgast! Totaler Albtraum!'::text,'erwischt'::text,'erwischt'::text,'erwischt'::text,'Diese Übelkeit erwischt jetzt schon seit einer Stunde jeden Fahrgast! Totaler Albtraum!'::text),
(386845,42983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ця нудота ... кожного пасажира вже годину! Повний кошмар!'::text,'накриває'::text,'накриває'::text,'накриває'::text,'Ця нудота накриває кожного пасажира вже годину! Повний кошмар!'::text),
(386844,42983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Este mareo ... a cada pasajero desde hace una hora! ¡Una pesadilla total!'::text,'ha estado afectando'::text,'está afectando'::text,'afecta'::text,'¡Este mareo ha estado afectando a cada pasajero desde hace una hora! ¡Una pesadilla total!'::text),
(386843,42983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce malaise ... chaque passager depuis une heure maintenant ! Cauchemar total !'::text,'frappe'::text,'frappe'::text,'frappe'::text,'Ce malaise frappe chaque passager depuis une heure maintenant ! Cauchemar total !'::text),
(386846,42983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu mide bulantısı bir saattir her yolcuyu ...! Tam bir kâbus!'::text,'tutuyor'::text,'tutuyor'::text,'tutar'::text,'Bu mide bulantısı bir saattir her yolcuyu tutuyor! Tam bir kâbus!'::text),
(386847,42983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez a rosszullét már egy órája ... minden utast! Totális rémálom!'::text,'leteríti'::text,'leteríti'::text,'leteríti'::text,'Ez a rosszullét már egy órája leteríti minden utast! Totális rémálom!'::text),
(386877,42987,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast deinen Freund dazu gebracht, dir Wasser ..., als die Übelkeit kam. Schlauer Move, ehrlich.'::text,'zu bringen'::text,'bringen'::text,'bringend'::text,'Du hast deinen Freund dazu gebracht, dir Wasser zu bringen, als die Übelkeit kam. Schlauer Move, ehrlich.'::text),
(386881,42987,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти попросив друга ... тобі води, коли накрила нудота. Розумний хід, чесно.'::text,'принести'::text,'принести'::text,'приносячи'::text,'Ти попросив друга принести тобі води, коли накрила нудота. Розумний хід, чесно.'::text),
(386880,42987,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú conseguiste que tu amigo te ... agua cuando llegó el mareo. Buena jugada, sinceramente.'::text,'trajera'::text,'trajera'::text,'trayendo'::text,'Tú conseguiste que tu amigo te trajera agua cuando llegó el mareo. Buena jugada, sinceramente.'::text),
(386879,42987,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as demandé à ton pote ... de l''eau quand le malaise a frappé. Bien joué, franchement.'::text,'de t''apporter'::text,'t''apporter'::text,'t''apportant'::text,'Tu as demandé à ton pote de t''apporter de l''eau quand le malaise a frappé. Bien joué, franchement.'::text),
(386882,42987,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mide bulantısı bastırınca sen arkadaşına su ...; akıllıca hamle, açıkçası.'::text,'getirttin'::text,'getirttin'::text,'getirterek'::text,'Mide bulantısı bastırınca sen arkadaşına su getirttin; akıllıca hamle, açıkçası.'::text),
(386883,42987,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te megkérted a barátodat, hogy ... neked vizet, amikor rád tört a rosszullét. Okos húzás, őszintén.'::text,'hozzon'::text,'hozzon'::text,'hozva'::text,'Te megkérted a barátodat, hogy hozzon neked vizet, amikor rád tört a rosszullét. Okos húzás, őszintén.'::text),
(333426,37048,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine durchsichtige Box, ... jeden Stimmzettel perfekt versteckt. Wirklich geniales Design.'::text,'die'::text,'wer'::text,'wo'::text,'Eine durchsichtige Box, die jeden Stimmzettel perfekt versteckt. Wirklich geniales Design.'::text),
(333430,37048,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прозора скринька, ... ідеально ховає кожен бюлетень. Справді геніальний дизайн.'::text,'яка'::text,'хто'::text,'де'::text,'Прозора скринька, яка ідеально ховає кожен бюлетень. Справді геніальний дизайн.'::text),
(333429,37048,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una caja transparente ... esconde cada papeleta a la perfección. Un diseño realmente genial.'::text,'que'::text,'quien'::text,'donde'::text,'Una caja transparente que esconde cada papeleta a la perfección. Un diseño realmente genial.'::text),
(333428,37048,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une boîte transparente ... cache parfaitement chaque bulletin. Un design vraiment génial.'::text,'qui'::text,'qui'::text,'où'::text,'Une boîte transparente qui cache parfaitement chaque bulletin. Un design vraiment génial.'::text),
(333431,37048,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... her oy pusulasını kusursuzca gizleyen şeffaf bir kutu. Gerçekten dâhiyane bir tasarım.'::text,''::text,NULL::text,NULL::text,'Her oy pusulasını kusursuzca gizleyen şeffaf bir kutu. Gerçekten dâhiyane bir tasarım.'::text),
(333432,37048,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy átlátszó doboz, ... tökéletesen elrejt minden szavazólapot. Igazán zseniális dizájn.'::text,'amely'::text,'aki'::text,'ahol'::text,'Egy átlátszó doboz, amely tökéletesen elrejt minden szavazólapot. Igazán zseniális dizájn.'::text),
(333471,37053,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stundenlang ... sie Stimmzettel in die Box, als die Schlange plötzlich im Chaos explodierte!'::text,'steckten'::text,'stecken'::text,'steckten'::text,'Stundenlang steckten sie Stimmzettel in die Box, als die Schlange plötzlich im Chaos explodierte!'::text),
(333475,37053,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони годинами ... бюлетені, коли черга раптом вибухнула хаосом!'::text,'вкидали'::text,'вкидають'::text,'вкинули'::text,'Вони годинами вкидали бюлетені, коли черга раптом вибухнула хаосом!'::text),
(333474,37053,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ellos ... papeletas durante horas cuando la fila de repente estalló en caos!'::text,'habían estado metiendo'::text,'han estado metiendo'::text,'metieron'::text,'¡Ellos habían estado metiendo papeletas durante horas cuando la fila de repente estalló en caos!'::text),
(333473,37053,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ... des bulletins depuis des heures quand la file a soudain explosé dans le chaos !'::text,'glissaient'::text,'glissent'::text,'ont glissé'::text,'Ils glissaient des bulletins depuis des heures quand la file a soudain explosé dans le chaos !'::text),
(333476,37053,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kuyruk aniden kaosa dönüştüğünde onlar saatlerdir oy pusulası ...!'::text,'atıyorlardı'::text,'atıyorlar'::text,'attılar'::text,'Kuyruk aniden kaosa dönüştüğünde onlar saatlerdir oy pusulası atıyorlardı!'::text),
(333477,37053,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ők órák óta ... a szavazólapokat, amikor a sor hirtelen káoszba robbant!'::text,'dobálták be'::text,'dobálják be'::text,'bedobták'::text,'Ők órák óta dobálták be a szavazólapokat, amikor a sor hirtelen káoszba robbant!'::text),
(346296,38478,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, angeblich ... sie nächste Woche um diese Zeit die Demokratie mit einer riesigen Party.'::text,'feiern'::text,'feiern'::text,'feiern'::text,'Mädel, angeblich feiern sie nächste Woche um diese Zeit die Demokratie mit einer riesigen Party.'::text),
(346300,38478,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, наступного тижня в цей час вони ... демократію величезною вечіркою.'::text,'святкуватимуть'::text,'відсвяткують'::text,'святкують'::text,'Подруго, кажуть, наступного тижня в цей час вони святкуватимуть демократію величезною вечіркою.'::text),
(346299,38478,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer la semana que viene a esta hora ellos ... la democracia con una fiesta enorme.'::text,'estarán celebrando'::text,'celebrarán'::text,'celebran'::text,'Amiga, al parecer la semana que viene a esta hora ellos estarán celebrando la democracia con una fiesta enorme.'::text),
(346298,38478,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment la semaine prochaine à cette heure-ci, ils ... la démocratie avec une énorme fête.'::text,'seront en train de célébrer'::text,'célébreront'::text,'célèbrent'::text,'Meuf, apparemment la semaine prochaine à cette heure-ci, ils seront en train de célébrer la démocratie avec une énorme fête.'::text),
(346301,38478,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, anlaşılan önümüzdeki hafta bu saatlerde onlar demokrasiyi dev bir partiyle ...'::text,'kutluyor olacaklar'::text,'kutlayacaklar'::text,'kutluyorlar'::text,'Kızım, anlaşılan önümüzdeki hafta bu saatlerde onlar demokrasiyi dev bir partiyle kutluyor olacaklar.'::text),
(346302,38478,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag jövő héten ilyenkor ők egy óriási bulival ... a demokráciát.'::text,'fogják ünnepelni'::text,'megünneplik'::text,'ünneplik'::text,'Csajszi, állítólag jövő héten ilyenkor ők egy óriási bulival fogják ünnepelni a demokráciát.'::text),
(346350,38484,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn niemand zum Wählen gekommen wäre, ... die Demokratie heute in diesem Saal nicht funktioniert.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn niemand zum Wählen gekommen wäre, hätte die Demokratie heute in diesem Saal nicht funktioniert.'::text),
(346354,38484,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ніхто не прийшов голосувати, демократія ... в цій залі сьогодні.'::text,'не спрацювала б'::text,'не спрацює'::text,'не спрацювала'::text,'Якби ніхто не прийшов голосувати, демократія не спрацювала б в цій залі сьогодні.'::text),
(346353,38484,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si nadie hubiera venido a votar, la democracia ... en esta sala hoy.'::text,'no habría funcionado'::text,'no funcionará'::text,'no funcionó'::text,'Si nadie hubiera venido a votar, la democracia no habría funcionado en esta sala hoy.'::text),
(346352,38484,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si personne n''était venu voter, la démocratie ... dans cette salle aujourd''hui.'::text,'n''aurait pas fonctionné'::text,'ne fonctionnera pas'::text,'n''a pas fonctionné'::text,'Si personne n''était venu voter, la démocratie n''aurait pas fonctionné dans cette salle aujourd''hui.'::text),
(346355,38484,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse oy vermeye gelmeseydi, demokrasi bugün bu salonda ...'::text,'işlemezdi'::text,'işlemeyecek'::text,'işlemedi'::text,'Kimse oy vermeye gelmeseydi, demokrasi bugün bu salonda işlemezdi.'::text),
(346356,38484,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha senki sem jött volna el szavazni, a demokrácia ma ... ebben a teremben.'::text,'nem működött volna'::text,'nem fog működni'::text,'nem működött'::text,'Ha senki sem jött volna el szavazni, a demokrácia ma nem működött volna ebben a teremben.'::text),
(362973,40331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... gerade in sein Tagebuch, als die Klippen auftauchten. Absolut unglaublich!'::text,'schrieb'::text,'schrieb'::text,'hat geschrieben'::text,'Er schrieb gerade in sein Tagebuch, als die Klippen auftauchten. Absolut unglaublich!'::text),
(362977,40331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... у свій щоденник, коли з''явилися скелі. Абсолютно неймовірно!'::text,'писав'::text,'написав'::text,'написав'::text,'Він писав у свій щоденник, коли з''явилися скелі. Абсолютно неймовірно!'::text),
(362976,40331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él ... en su diario cuando aparecieron los acantilados. ¡Absolutamente increíble!'::text,'estaba escribiendo'::text,'escribió'::text,'ha escrito'::text,'Él estaba escribiendo en su diario cuando aparecieron los acantilados. ¡Absolutamente increíble!'::text),
(362975,40331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... dans son carnet quand les falaises sont apparues. Absolument incroyable !'::text,'écrivait'::text,'a écrit'::text,'a écrit'::text,'Il écrivait dans son carnet quand les falaises sont apparues. Absolument incroyable !'::text),
(362978,40331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçurumlar göründüğünde o günlüğüne ...; kesinlikle inanılmaz!'::text,'yazıyordu'::text,'yazdı'::text,'yazdı'::text,'Uçurumlar göründüğünde o günlüğüne yazıyordu; kesinlikle inanılmaz!'::text),
(362979,40331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő éppen ... a naplójába, amikor feltűntek a sziklák. Abszolút hihetetlen!'::text,'írt'::text,'írt'::text,'írt'::text,'Ő éppen írt a naplójába, amikor feltűntek a sziklák. Abszolút hihetetlen!'::text),
(363045,40339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eindeutig ein langweiliger Ausblick: Gerade ... er pausenlos in sein Tagebuch.'::text,'schreibt'::text,'schreibt'::text,'hat geschrieben'::text,'Eindeutig ein langweiliger Ausblick: Gerade schreibt er pausenlos in sein Tagebuch.'::text),
(363049,40339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно нудний краєвид: просто зараз він ... у щоденник без упину.'::text,'пише'::text,'пише'::text,'написав'::text,'Явно нудний краєвид: просто зараз він пише у щоденник без упину.'::text),
(363048,40339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una vista aburrida: ahora mismo él ... en su diario sin parar.'::text,'está escribiendo'::text,'escribe'::text,'ha escrito'::text,'Claramente una vista aburrida: ahora mismo él está escribiendo en su diario sin parar.'::text),
(363047,40339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement une vue ennuyeuse : en ce moment, il ... dans son carnet sans arrêt.'::text,'écrit'::text,'écrit'::text,'a écrit'::text,'Clairement une vue ennuyeuse : en ce moment, il écrit dans son carnet sans arrêt.'::text),
(363050,40339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sıkıcı bir manzara: şu anda o durmadan günlüğüne ...'::text,'yazıyor'::text,'yazar'::text,'yazdı'::text,'Belli ki sıkıcı bir manzara: şu anda o durmadan günlüğüne yazıyor.'::text),
(363051,40339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen unalmas kilátás: ő épp most megállás nélkül ... a naplójába.'::text,'ír'::text,'ír'::text,'írt'::text,'Egyértelműen unalmas kilátás: ő épp most megállás nélkül ír a naplójába.'::text),
(401376,44598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, ich hab gehört, der Schneider ... ihre Taille in fünf Sekunden.'::text,'maß'::text,'wurde gemessen'::text,'messend'::text,'Warte, ich hab gehört, der Schneider maß ihre Taille in fünf Sekunden.'::text),
(401380,44598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, я чула, що кравець ... її талію за п''ять секунд.'::text,'виміряв'::text,'був виміряний'::text,'вимірюючи'::text,'Стоп, я чула, що кравець виміряв її талію за п''ять секунд.'::text),
(401379,44598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, oí que el sastre le ... la cintura en cinco segundos.'::text,'midió'::text,'fue medido'::text,'midiendo'::text,'Espera, oí que el sastre le midió la cintura en cinco segundos.'::text),
(401378,44598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu dire que le tailleur ... son tour de taille en cinq secondes.'::text,'a mesuré'::text,'a été mesuré'::text,'mesurant'::text,'Attends, j''ai entendu dire que le tailleur a mesuré son tour de taille en cinq secondes.'::text),
(401381,44598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki terzi onun belini beş saniyede ...'::text,'ölçmüş'::text,'ölçülmüş'::text,'ölçerek'::text,'Dur, duydum ki terzi onun belini beş saniyede ölçmüş.'::text),
(401382,44598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt hallottam, hogy a szabó öt másodperc alatt ... a derekát.'::text,'lemérte'::text,'le lett mérve'::text,'mérve'::text,'Várj, azt hallottam, hogy a szabó öt másodperc alatt lemérte a derekát.'::text),
(355998,39556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kellner ... in einer formellen Uniform mit schwarzer Fliege.'::text,'ist gekleidet'::text,'kleidet sich'::text,'sich kleidend'::text,'Der Kellner ist gekleidet in einer formellen Uniform mit schwarzer Fliege.'::text),
(356002,39556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Офіціант ... у формальну уніформу з чорним метеликом.'::text,'одягнений'::text,'одягається'::text,'одягаючись'::text,'Офіціант одягнений у формальну уніформу з чорним метеликом.'::text),
(356001,39556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El camarero ... con un uniforme formal y una pajarita negra.'::text,'va vestido'::text,'se viste'::text,'vistiéndose'::text,'El camarero va vestido con un uniforme formal y una pajarita negra.'::text),
(356000,39556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le serveur ... d''un uniforme formel avec un nœud papillon noir.'::text,'est vêtu'::text,'se vêt'::text,'se vêtant'::text,'Le serveur est vêtu d''un uniforme formel avec un nœud papillon noir.'::text),
(356003,39556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Garson siyah papyonlu resmî bir üniforma ...'::text,'giymiş'::text,'giyiyor'::text,'giyerek'::text,'Garson siyah papyonlu resmî bir üniforma giymiş.'::text),
(356004,39556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pincér hivatalos egyenruhába ... fekete csokornyakkendővel.'::text,'van öltözve'::text,'öltözik'::text,'öltözve'::text,'A pincér hivatalos egyenruhába van öltözve fekete csokornyakkendővel.'::text),
(401628,44626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Walkerin ihre Stöcke vergisst, ... der ganze Spaziergang zur totalen Katastrophe!'::text,'wird'::text,'wird'::text,'wurde'::text,'Wenn eine Walkerin ihre Stöcke vergisst, wird der ganze Spaziergang zur totalen Katastrophe!'::text),
(401632,44626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ходачка забуває палиці, уся прогулянка ... повною катастрофою!'::text,'стає'::text,'стане'::text,'стала'::text,'Якщо ходачка забуває палиці, уся прогулянка стає повною катастрофою!'::text),
(401631,44626,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si una caminante olvida sus bastones, todo el paseo ... un desastre total!'::text,'se convierte en'::text,'se convertirá en'::text,'se convirtió en'::text,'¡Si una caminante olvida sus bastones, todo el paseo se convierte en un desastre total!'::text),
(401630,44626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une marcheuse oublie ses bâtons, toute la promenade ... un désastre total !'::text,'devient'::text,'deviendra'::text,'est devenue'::text,'Si une marcheuse oublie ses bâtons, toute la promenade devient un désastre total !'::text),
(401633,44626,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yürüyüşçü batonlarını unutursa bütün yürüyüş tam bir felakete ...!'::text,'döner'::text,'dönecek'::text,'döndü'::text,'Bir yürüyüşçü batonlarını unutursa bütün yürüyüş tam bir felakete döner!'::text),
(401634,44626,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy gyalogló otthon felejti a botjait, az egész séta totális katasztrófává ...!'::text,'válik'::text,'fog válni'::text,'vált'::text,'Ha egy gyalogló otthon felejti a botjait, az egész séta totális katasztrófává válik!'::text),
(401646,44628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Walkerin ... bei jedem Spaziergang zwei Stöcke, einen in jeder Hand.'::text,'benutzt'::text,'benutzt'::text,'hat benutzt'::text,'Die Walkerin benutzt bei jedem Spaziergang zwei Stöcke, einen in jeder Hand.'::text),
(401650,44628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ходачка ... на кожній прогулянці дві палиці, по одній у кожній руці.'::text,'використовує'::text,'використовує'::text,'використала'::text,'Ходачка використовує на кожній прогулянці дві палиці, по одній у кожній руці.'::text),
(401649,44628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La caminante ... dos bastones, uno en cada mano, en cada paseo.'::text,'usa'::text,'está usando'::text,'ha usado'::text,'La caminante usa dos bastones, uno en cada mano, en cada paseo.'::text),
(401648,44628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La marcheuse ... deux bâtons, un dans chaque main, à chaque promenade.'::text,'utilise'::text,'utilise'::text,'a utilisé'::text,'La marcheuse utilise deux bâtons, un dans chaque main, à chaque promenade.'::text),
(401651,44628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçü her yürüyüşte her elde bir tane olmak üzere iki baton ...'::text,'kullanır'::text,'kullanıyor'::text,'kullandı'::text,'Yürüyüşçü her yürüyüşte her elde bir tane olmak üzere iki baton kullanır.'::text),
(401652,44628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyalogló minden sétán két botot ..., mindkét kezében egyet.'::text,'használ'::text,'használ'::text,'használt'::text,'A gyalogló minden sétán két botot használ, mindkét kezében egyet.'::text),
(349113,38791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wanderer jemals in die Innenstadt käme, ... er vor lauter Angst in Panik!'::text,'geriete'::text,'gerät'::text,'geriet'::text,'Wenn der Wanderer jemals in die Innenstadt käme, geriete er vor lauter Angst in Panik!'::text),
(349117,38791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби турист колись приїхав у центр, він ... в абсолютному жаху!'::text,'запанікував би'::text,'запанікує'::text,'запанікував'::text,'Якби турист колись приїхав у центр, він запанікував би в абсолютному жаху!'::text),
(349116,38791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si el excursionista alguna vez viniera al centro, él ... presa del terror absoluto!'::text,'entraría en pánico'::text,'entrará en pánico'::text,'entró en pánico'::text,'¡Si el excursionista alguna vez viniera al centro, él entraría en pánico presa del terror absoluto!'::text),
(349115,38791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le randonneur venait un jour en centre-ville, il ... dans une terreur absolue !'::text,'paniquerait'::text,'paniquera'::text,'a paniqué'::text,'Si le randonneur venait un jour en centre-ville, il paniquerait dans une terreur absolue !'::text),
(349118,38791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yürüyüşçü bir gün şehir merkezine gelse, o büyük bir dehşetle ...!'::text,'paniğe kapılırdı'::text,'paniğe kapılacak'::text,'paniğe kapıldı'::text,'Yürüyüşçü bir gün şehir merkezine gelse, o büyük bir dehşetle paniğe kapılırdı!'::text),
(349119,38791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a túrázó valaha bejönne a belvárosba, ő teljes rémületben ...!'::text,'pánikba esne'::text,'pánikba fog esni'::text,'pánikba esett'::text,'Ha a túrázó valaha bejönne a belvárosba, ő teljes rémületben pánikba esne!'::text),
(349149,38795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um sechs ... Menschenmassen die große Kreuzung in der Innenstadt.'::text,'überqueren'::text,'überqueren'::text,'überqueren'::text,'Morgen um sechs überqueren Menschenmassen die große Kreuzung in der Innenstadt.'::text),
(349153,38795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о шостій натовпи ... велике перехрестя в центрі.'::text,'переходитимуть'::text,'перейдуть'::text,'переходять'::text,'Завтра о шостій натовпи переходитимуть велике перехрестя в центрі.'::text),
(349152,38795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a las seis, las multitudes ... el gran cruce del centro.'::text,'estarán cruzando'::text,'habrán cruzado'::text,'cruzan'::text,'Mañana a las seis, las multitudes estarán cruzando el gran cruce del centro.'::text),
(349151,38795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à six heures, les foules ... le grand carrefour du centre-ville.'::text,'seront en train de traverser'::text,'auront traversé'::text,'traversent'::text,'Demain à six heures, les foules seront en train de traverser le grand carrefour du centre-ville.'::text),
(349154,38795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın saat altıda kalabalıklar şehir merkezindeki büyük geçidi ...'::text,'geçiyor olacak'::text,'geçmiş olacak'::text,'geçiyor'::text,'Yarın saat altıda kalabalıklar şehir merkezindeki büyük geçidi geçiyor olacak.'::text),
(349155,38795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap hatkor tömegek ... a belvárosi nagy kereszteződésen.'::text,'fognak átkelni'::text,'már átkeltek'::text,'kelnek át'::text,'Holnap hatkor tömegek fognak átkelni a belvárosi nagy kereszteződésen.'::text),
(365322,40592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, der Rahmen, ... du gerade ausgerichtet hast, sieht richtig edel aus.'::text,'den'::text,'wer'::text,'dessen'::text,'Ehrlich, der Rahmen, den du gerade ausgerichtet hast, sieht richtig edel aus.'::text),
(365326,40592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, рамка, ... ти вирівняв, виглядає дуже стильно.'::text,'яку'::text,'хто'::text,'чию'::text,'Чесно, рамка, яку ти вирівняв, виглядає дуже стильно.'::text),
(365325,40592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, el marco ... tú nivelaste queda muy elegante.'::text,'que'::text,'quien'::text,'cuyo'::text,'Sinceramente, el marco que tú nivelaste queda muy elegante.'::text),
(365324,40592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, le cadre ... tu as mis de niveau a vraiment la classe.'::text,'que'::text,'qui'::text,'dont'::text,'Franchement, le cadre que tu as mis de niveau a vraiment la classe.'::text),
(365327,40592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası ... senin düzelttiğin çerçeve çok şık duruyor.'::text,''::text,NULL::text,NULL::text,'Açıkçası senin düzelttiğin çerçeve çok şık duruyor.'::text),
(365328,40592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, a keret, ... te vízszintbe tettél, nagyon elegáns.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'Őszintén, a keret, amelyet te vízszintbe tettél, nagyon elegáns.'::text),
(365358,40596,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er die Wasserwaage auf den Rahmen, um zu sehen, ob er gerade ist.'::text,'legt'::text,'legt'::text,'hat gelegt'::text,'Gerade legt er die Wasserwaage auf den Rahmen, um zu sehen, ob er gerade ist.'::text),
(365362,40596,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто зараз він ... рівень на рамку, щоб перевірити, чи вона рівна.'::text,'кладе'::text,'кладе'::text,'поклав'::text,'Просто зараз він кладе рівень на рамку, щоб перевірити, чи вона рівна.'::text),
(365361,40596,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo él ... el nivel sobre el marco para ver si está recto.'::text,'está colocando'::text,'coloca'::text,'ha colocado'::text,'Ahora mismo él está colocando el nivel sobre el marco para ver si está recto.'::text),
(365360,40596,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... le niveau à bulle sur le cadre pour voir s''il est droit.'::text,'pose'::text,'pose'::text,'a posé'::text,'En ce moment, il pose le niveau à bulle sur le cadre pour voir s''il est droit.'::text),
(365363,40596,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda o, düz olup olmadığını görmek için su terazisini çerçevenin üstüne ...'::text,'koyuyor'::text,'koyar'::text,'koydu'::text,'Şu anda o, düz olup olmadığını görmek için su terazisini çerçevenin üstüne koyuyor.'::text),
(365364,40596,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ő ... a vízmértéket a keretre, hogy lássa, egyenes-e.'::text,'teszi'::text,'teszi'::text,'tette'::text,'Épp most ő teszi a vízmértéket a keretre, hogy lássa, egyenes-e.'::text),
(334488,37166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Scheine ... aus dem offenen Portemonnaie auf die Theke.'::text,'rutschen'::text,'werden geschoben'::text,'rutschend'::text,'Die Scheine rutschen aus dem offenen Portemonnaie auf die Theke.'::text),
(334492,37166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Купюри ... з відкритого гаманця на прилавок.'::text,'вислизають'::text,'висуваються'::text,'вислизаючи'::text,'Купюри вислизають з відкритого гаманця на прилавок.'::text),
(334491,37166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los billetes ... de la cartera abierta al mostrador.'::text,'se deslizan'::text,'son deslizados'::text,'deslizándose'::text,'Los billetes se deslizan de la cartera abierta al mostrador.'::text),
(334490,37166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les billets ... du portefeuille ouvert sur le comptoir.'::text,'glissent'::text,'sont glissés'::text,'glissant'::text,'Les billets glissent du portefeuille ouvert sur le comptoir.'::text),
(334493,37166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Banknotlar açık cüzdandan tezgâha ...'::text,'kayıyor'::text,'kaydırılıyor'::text,'kayarak'::text,'Banknotlar açık cüzdandan tezgâha kayıyor.'::text),
(334494,37166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A bankjegyek ... a nyitott pénztárcából a pultra.'::text,'kicsúsznak'::text,'ki vannak csúsztatva'::text,'kicsúszva'::text,'A bankjegyek kicsúsznak a nyitott pénztárcából a pultra.'::text),
(402204,44690,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sein Portemonnaie ist leer, also ... er nicht sehr reich sein. Was für eine Überraschung.'::text,'kann'::text,'muss'::text,'sollte'::text,'Sein Portemonnaie ist leer, also kann er nicht sehr reich sein. Was für eine Überraschung.'::text),
(402208,44690,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його гаманець порожній, тож він ... бути дуже багатим. Який сюрприз.'::text,'не може'::text,'мусить'::text,'мав би'::text,'Його гаманець порожній, тож він не може бути дуже багатим. Який сюрприз.'::text),
(402207,44690,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su cartera está vacía, así que él ... ser muy rico. Qué sorpresa.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Su cartera está vacía, así que él no puede ser muy rico. Qué sorpresa.'::text),
(402206,44690,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son portefeuille est vide, donc il ... être très riche. Quelle surprise.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Son portefeuille est vide, donc il ne peut pas être très riche. Quelle surprise.'::text),
(402209,44690,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cüzdanı boş, yani o çok zengin ...; ne sürpriz.'::text,'olamaz'::text,'olmalı'::text,'olmalı'::text,'Cüzdanı boş, yani o çok zengin olamaz; ne sürpriz.'::text),
(402210,44690,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pénztárcája üres, szóval ő ... nagyon gazdag. Micsoda meglepetés.'::text,'biztosan nem'::text,'biztosan'::text,'elvileg'::text,'A pénztárcája üres, szóval ő biztosan nem nagyon gazdag. Micsoda meglepetés.'::text),
(402267,44697,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich lüg nicht, du ... ewig dein Portemonnaie, bevor du wie ein reicher Mann gegrinst hast.'::text,'durchsuchtest'::text,'durchsuchst'::text,'durchsuchtest'::text,'Ich lüg nicht, du durchsuchtest ewig dein Portemonnaie, bevor du wie ein reicher Mann gegrinst hast.'::text),
(402271,44697,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти ... свій гаманець цілу вічність, перш ніж усміхнувся, як багатій.'::text,'обшукував'::text,'обшукуєш'::text,'обшукував'::text,'Не брехатиму, ти обшукував свій гаманець цілу вічність, перш ніж усміхнувся, як багатій.'::text),
(402270,44697,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, tú ... en tu cartera una eternidad antes de sonreír como un hombre rico.'::text,'habías estado buscando'::text,'has estado buscando'::text,'estabas buscando'::text,'No voy a mentir, tú habías estado buscando en tu cartera una eternidad antes de sonreír como un hombre rico.'::text),
(402269,44697,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... ton portefeuille pendant une éternité avant de sourire comme un homme riche.'::text,'avais fouillé'::text,'as fouillé'::text,'fouillais'::text,'Je vais pas mentir, tu avais fouillé ton portefeuille pendant une éternité avant de sourire comme un homme riche.'::text),
(402272,44697,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, sen zengin bir adam gibi sırıtmadan önce cüzdanını uzun süre ...'::text,'karıştırmıştın'::text,'karıştırıyorsun'::text,'karıştırıyordun'::text,'Yalan yok, sen zengin bir adam gibi sırıtmadan önce cüzdanını uzun süre karıştırmıştın.'::text),
(402273,44697,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te egy örökkévalóságig ... a pénztárcádban, mielőtt úgy vigyorogtál, mint egy gazdag ember.'::text,'kutattál'::text,'kutatsz'::text,'kutattál'::text,'Nem hazudok, te egy örökkévalóságig kutattál a pénztárcádban, mielőtt úgy vigyorogtál, mint egy gazdag ember.'::text),
(395364,43930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Panzer ... langsam durch den Rauch hinter den rennenden Soldaten.'::text,'rollt'::text,'wird gerollt'::text,'rollend'::text,'Der Panzer rollt langsam durch den Rauch hinter den rennenden Soldaten.'::text),
(395368,43930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Танк повільно ... крізь дим позаду солдатів, що біжать.'::text,'котиться'::text,'котиться'::text,'котячись'::text,'Танк повільно котиться крізь дим позаду солдатів, що біжать.'::text),
(395367,43930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El tanque ... lentamente entre el humo detrás de los soldados que corren.'::text,'rueda'::text,'es rodado'::text,'rodando'::text,'El tanque rueda lentamente entre el humo detrás de los soldados que corren.'::text),
(395366,43930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le char ... lentement dans la fumée derrière les soldats qui courent.'::text,'roule'::text,'est roulé'::text,'roulant'::text,'Le char roule lentement dans la fumée derrière les soldats qui courent.'::text),
(395369,43930,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tank koşan askerlerin arkasında dumanın içinden yavaşça ...'::text,'ilerliyor'::text,'ilerletiliyor'::text,'ilerleyerek'::text,'Tank koşan askerlerin arkasında dumanın içinden yavaşça ilerliyor.'::text),
(395370,43930,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tank lassan ... a füstön át a futó katonák mögött.'::text,'gördül'::text,'gördítik'::text,'gördülve'::text,'A tank lassan gördül a füstön át a futó katonák mögött.'::text),
(356142,39572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich glaube, die Schneeburg ... im Frühling, weil sie aus Schnee ist.'::text,'schmilzt'::text,'schmilzt'::text,'schmilzt'::text,'Ich glaube, die Schneeburg schmilzt im Frühling, weil sie aus Schnee ist.'::text),
(356146,39572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я думаю, що снігова фортеця навесні ..., бо вона зі снігу.'::text,'розтане'::text,'танутиме'::text,'тане'::text,'Я думаю, що снігова фортеця навесні розтане, бо вона зі снігу.'::text),
(356145,39572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo creo que el fuerte de nieve ... en primavera, porque está hecho de nieve.'::text,'se derretirá'::text,'se estará derritiendo'::text,'se está derritiendo'::text,'Yo creo que el fuerte de nieve se derretirá en primavera, porque está hecho de nieve.'::text),
(356144,39572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je pense que le fort de neige ... au printemps, parce qu''il est fait de neige.'::text,'fondra'::text,'sera en train de fondre'::text,'fond'::text,'Je pense que le fort de neige fondra au printemps, parce qu''il est fait de neige.'::text),
(356147,39572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bence kardan kale baharda ..., çünkü kardan yapılmış.'::text,'eriyecek'::text,'eriyor olacak'::text,'eriyor'::text,'Bence kardan kale baharda eriyecek, çünkü kardan yapılmış.'::text),
(356148,39572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szerintem a hóvár tavasszal ..., mert hóból van.'::text,'elolvad'::text,'olvadni fog'::text,'olvad'::text,'Szerintem a hóvár tavasszal elolvad, mert hóból van.'::text),
(356196,39578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Offensichtlich ein friedlicher Nachmittag: Das rote Team bestritt, den Schneeballkrieg von seiner Burg aus ...'::text,'begonnen zu haben'::text,'zu beginnen'::text,'begonnen'::text,'Offensichtlich ein friedlicher Nachmittag: Das rote Team bestritt, den Schneeballkrieg von seiner Burg aus begonnen zu haben.'::text),
(356200,39578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, мирний день: червона команда заперечила, що ... снігову війну зі своєї фортеці.'::text,'почала'::text,'почне'::text,'почала'::text,'Очевидно, мирний день: червона команда заперечила, що почала снігову війну зі своєї фортеці.'::text),
(356199,39578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente una tarde tranquila: el equipo rojo negó ... la guerra de bolas de nieve desde su fuerte.'::text,'haber empezado'::text,'empezar'::text,'empezó'::text,'Obviamente una tarde tranquila: el equipo rojo negó haber empezado la guerra de bolas de nieve desde su fuerte.'::text),
(356198,39578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment un après-midi paisible : l''équipe rouge a nié ... la bataille de boules de neige depuis son fort.'::text,'avoir lancé'::text,'lancer'::text,'a lancé'::text,'Évidemment un après-midi paisible : l''équipe rouge a nié avoir lancé la bataille de boules de neige depuis son fort.'::text),
(356201,39578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki huzurlu bir öğleden sonra: kırmızı takım kartopu savaşını kalesinden ... inkâr etti.'::text,'başlattığını'::text,'başlatmayı'::text,'başlattı'::text,'Belli ki huzurlu bir öğleden sonra: kırmızı takım kartopu savaşını kalesinden başlattığını inkâr etti.'::text),
(356202,39578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvalóan békés délután: a piros csapat tagadta, hogy ... a hógolyócsatát a várából.'::text,'elkezdte'::text,'elkezdeni'::text,'elkezdte'::text,'Nyilvánvalóan békés délután: a piros csapat tagadta, hogy elkezdte a hógolyócsatát a várából.'::text),
(393654,43740,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'So viel Zeug fällt aus ihrem Schrank, also ... sie nicht sehr ordentlich sein.'::text,'kann'::text,'muss'::text,'sollte'::text,'So viel Zeug fällt aus ihrem Schrank, also kann sie nicht sehr ordentlich sein.'::text),
(393658,43740,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стільки речей випадає з її шафи, тож вона ... бути дуже охайною.'::text,'не може'::text,'мусить'::text,'мала б'::text,'Стільки речей випадає з її шафи, тож вона не може бути дуже охайною.'::text),
(393657,43740,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se caen tantas cosas de su armario, así que ella ... ser muy ordenada.'::text,'no puede'::text,'debe de'::text,'debería'::text,'Se caen tantas cosas de su armario, así que ella no puede ser muy ordenada.'::text),
(393656,43740,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tellement de trucs tombent de son armoire, donc elle ... être très ordonnée.'::text,'ne peut pas'::text,'doit'::text,'devrait'::text,'Tellement de trucs tombent de son armoire, donc elle ne peut pas être très ordonnée.'::text),
(393659,43740,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dolabından o kadar çok eşya düşüyor ki o çok düzenli ...'::text,'olamaz'::text,'olmalı'::text,'olmalı'::text,'Dolabından o kadar çok eşya düşüyor ki o çok düzenli olamaz.'::text),
(393660,43740,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annyi cucc esik ki a szekrényéből, szóval ő ... nagyon rendes.'::text,'biztosan nem'::text,'biztosan'::text,'elvileg'::text,'Annyi cucc esik ki a szekrényéből, szóval ő biztosan nem nagyon rendes.'::text),
(381540,42394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag wird sie zwei Stunden lang im Bademantel durch das Ankleidezimmer ...'::text,'gelaufen sein'::text,'laufen'::text,'laufen'::text,'Bis Mittag wird sie zwei Stunden lang im Bademantel durch das Ankleidezimmer gelaufen sein.'::text),
(381544,42394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня вона вже дві години ... по гардеробній у халаті.'::text,'ходитиме'::text,'ходитиме'::text,'пройде'::text,'До полудня вона вже дві години ходитиме по гардеробній у халаті.'::text),
(381543,42394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía, ella ... por el vestidor en bata durante dos horas.'::text,'habrá estado caminando'::text,'estará caminando'::text,'caminará'::text,'Para el mediodía, ella habrá estado caminando por el vestidor en bata durante dos horas.'::text),
(381542,42394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, elle ... dans le dressing en peignoir depuis deux heures.'::text,'aura déambulé'::text,'sera en train de déambuler'::text,'déambulera'::text,'À midi, elle aura déambulé dans le dressing en peignoir depuis deux heures.'::text),
(381545,42394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar o, sabahlığıyla giyinme odasında iki saattir ...'::text,'dolaşıyor olacak'::text,'dolaşıyor olacak'::text,'dolaşacak'::text,'Öğlene kadar o, sabahlığıyla giyinme odasında iki saattir dolaşıyor olacak.'::text),
(381546,42394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ő már két órája ... a gardróbszobában a köntösében.'::text,'járkál'::text,'járkálni fog'::text,'járkál majd'::text,'Délre ő már két órája járkál a gardróbszobában a köntösében.'::text),
(383457,42607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ... seit zehn Minuten das Ufer ab, was sucht sie überhaupt?'::text,'sucht'::text,'sucht'::text,'sucht'::text,'Alter, sie sucht seit zehn Minuten das Ufer ab, was sucht sie überhaupt?'::text),
(383461,42607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона вже десять хвилин ... берег, що вона взагалі шукає?'::text,'розглядає'::text,'розглядає'::text,'розглядає'::text,'Чувак, вона вже десять хвилин розглядає берег, що вона взагалі шукає?'::text),
(383460,42607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ella ... la orilla desde hace diez minutos; ¿qué está buscando siquiera?'::text,'ha estado rastreando'::text,'está rastreando'::text,'rastrea'::text,'Tío, ella ha estado rastreando la orilla desde hace diez minutos; ¿qué está buscando siquiera?'::text),
(383459,42607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle ... le rivage depuis dix minutes, elle cherche quoi au juste ?'::text,'scrute'::text,'scrute'::text,'scrute'::text,'Mec, elle scrute le rivage depuis dix minutes, elle cherche quoi au juste ?'::text),
(383462,42607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o on dakikadır kıyıyı ..., ne arıyor ki?'::text,'tarıyor'::text,'tarıyor'::text,'tarar'::text,'Kanka, o on dakikadır kıyıyı tarıyor, ne arıyor ki?'::text),
(383463,42607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő tíz perce ... a partot, mit keres egyáltalán?'::text,'pásztázza'::text,'pásztázza'::text,'pásztázza'::text,'Tesó, ő tíz perce pásztázza a partot, mit keres egyáltalán?'::text),
(383538,42616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bei dem Tempo wird sie das ganze Stadion bis Mitternacht ...; ein schneller Job, logisch.'::text,'abgesucht haben'::text,'absuchen'::text,'absucht'::text,'Bei dem Tempo wird sie das ganze Stadion bis Mitternacht abgesucht haben; ein schneller Job, logisch.'::text),
(383542,42616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Такими темпами вона ... весь стадіон до півночі. Швидка робота, очевидно.'::text,'обдивиться'::text,'оглядатиме'::text,'оглядає'::text,'Такими темпами вона обдивиться весь стадіон до півночі. Швидка робота, очевидно.'::text),
(383541,42616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A este ritmo, ella ... todo el estadio para medianoche. Un trabajo rápido, obviamente.'::text,'habrá rastreado'::text,'rastreará'::text,'rastrea'::text,'A este ritmo, ella habrá rastreado todo el estadio para medianoche. Un trabajo rápido, obviamente.'::text),
(383540,42616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À ce rythme, elle ... tout le stade d''ici minuit. Un travail rapide, évidemment.'::text,'aura scruté'::text,'scrutera'::text,'scrute'::text,'À ce rythme, elle aura scruté tout le stade d''ici minuit. Un travail rapide, évidemment.'::text),
(383543,42616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu gidişle o gece yarısına kadar bütün stadyumu ...; hızlı bir iş, tabii ki.'::text,'taramış olacak'::text,'tarayacak'::text,'tarıyor'::text,'Bu gidişle o gece yarısına kadar bütün stadyumu taramış olacak; hızlı bir iş, tabii ki.'::text),
(383544,42616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ilyen tempóban ő éjfélre ... az egész stadiont. Gyors munka, nyilván.'::text,'végigpásztázza'::text,'végig fogja pásztázni'::text,'pásztázza'::text,'Ilyen tempóban ő éjfélre végigpásztázza az egész stadiont. Gyors munka, nyilván.'::text),
(357708,39746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich hab gehört, sie ... bis zur allerletzten Rakete auf das Feuerwerk.'::text,'starrten'::text,'starrten'::text,'haben gestarrt'::text,'Hör zu, ich hab gehört, sie starrten bis zur allerletzten Rakete auf das Feuerwerk.'::text),
(357712,39746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що вони ... на феєрверк до останньої ракети.'::text,'дивилися'::text,'дивилися'::text,'дивилися'::text,'Слухай, я чула, що вони дивилися на феєрверк до останньої ракети.'::text),
(357711,39746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, oí que ellos ... los fuegos artificiales hasta el último cohete.'::text,'contemplaron'::text,'estaban contemplando'::text,'han contemplado'::text,'Escucha, oí que ellos contemplaron los fuegos artificiales hasta el último cohete.'::text),
(357710,39746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''ils ... le feu d''artifice jusqu''à la toute dernière fusée.'::text,'ont contemplé'::text,'contemplaient'::text,'ont contemplé'::text,'Écoute, j''ai entendu dire qu''ils ont contemplé le feu d''artifice jusqu''à la toute dernière fusée.'::text),
(357713,39746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki onlar en son rokete kadar havai fişeklere ...'::text,'bakmışlar'::text,'bakıyorlarmış'::text,'bakmışlar'::text,'Dinle, duydum ki onlar en son rokete kadar havai fişeklere bakmışlar.'::text),
(357714,39746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy ők az utolsó rakétáig ... a tűzijátékot.'::text,'bámulták'::text,'bámulták'::text,'bámulták'::text,'Figyelj, azt hallottam, hogy ők az utolsó rakétáig bámulták a tűzijátékot.'::text),
(357771,39753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Lärms blicken die drei Individuen weiterhin in den Himmel, ohne wegzusehen.'::text,'Trotz'::text,'Aufgrund'::text,'Vorausgesetzt'::text,'Trotz des Lärms blicken die drei Individuen weiterhin in den Himmel, ohne wegzusehen.'::text),
(357775,39753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... шум, троє індивідів продовжують дивитися в небо, не відводячи погляду.'::text,'Попри'::text,'Через'::text,'За умови'::text,'Попри шум, троє індивідів продовжують дивитися в небо, не відводячи погляду.'::text),
(357774,39753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el ruido, los tres individuos siguen mirando el cielo sin apartar la vista.'::text,'A pesar de'::text,'Debido a'::text,'Siempre que'::text,'A pesar de el ruido, los tres individuos siguen mirando el cielo sin apartar la vista.'::text),
(357773,39753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le bruit, les trois individus continuent de fixer le ciel sans détourner le regard.'::text,'Malgré'::text,'En raison de'::text,'Pourvu que'::text,'Malgré le bruit, les trois individus continuent de fixer le ciel sans détourner le regard.'::text),
(357776,39753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gürültüye ..., üç birey gözlerini ayırmadan gökyüzüne bakmaya devam ediyor.'::text,'rağmen'::text,'bağlı olarak'::text,'koşuluyla'::text,'Gürültüye rağmen, üç birey gözlerini ayırmadan gökyüzüne bakmaya devam ediyor.'::text),
(357777,39753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A zaj ..., a három egyén továbbra is az eget nézi, anélkül hogy elfordítaná a tekintetét.'::text,'ellenére'::text,'miatt'::text,'feltéve'::text,'A zaj ellenére, a három egyén továbbra is az eget nézi, anélkül hogy elfordítaná a tekintetét.'::text),
(401835,44649,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... die Gießkanne hält, lächelt ihre Pflanzen an.'::text,'die'::text,'welche'::text,'deren'::text,'Die Frau, die die Gießkanne hält, lächelt ihre Pflanzen an.'::text),
(401839,44649,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... тримає лійку, усміхається своїм рослинам.'::text,'яка'::text,'яка'::text,'чия'::text,'Жінка, яка тримає лійку, усміхається своїм рослинам.'::text),
(401838,44649,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... sostiene la regadera sonríe a sus plantas.'::text,'que'::text,'la cual'::text,'cuya'::text,'La mujer que sostiene la regadera sonríe a sus plantas.'::text),
(401837,44649,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... tient l''arrosoir sourit à ses plantes.'::text,'qui'::text,'laquelle'::text,'dont'::text,'La femme qui tient l''arrosoir sourit à ses plantes.'::text),
(401840,44649,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sulama kabını ... tutan kadın bitkilerine gülümsüyor.'::text,''::text,NULL::text,NULL::text,'Sulama kabını tutan kadın bitkilerine gülümsüyor.'::text),
(401841,44649,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő, ... a locsolókannát tartja, mosolyog a növényeire.'::text,'aki'::text,'amely'::text,'akinek'::text,'A nő, aki a locsolókannát tartja, mosolyog a növényeire.'::text),
(401871,44653,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie gießt ihre Pflanzen ... mit der Gießkanne auf ihrem Balkon.'::text,'bei Sonnenuntergang'::text,'beim Sonnenuntergang'::text,'in einem Sonnenuntergang'::text,'Sie gießt ihre Pflanzen bei Sonnenuntergang mit der Gießkanne auf ihrem Balkon.'::text),
(401875,44653,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона поливає рослини з лійки ... на своєму балконі.'::text,'на заході сонця'::text,'на заході сонця'::text,'у заході сонця'::text,'Вона поливає рослини з лійки на заході сонця на своєму балконі.'::text),
(401874,44653,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella riega sus plantas con la regadera ... en su balcón.'::text,'al atardecer'::text,'en el atardecer'::text,'en un atardecer'::text,'Ella riega sus plantas con la regadera al atardecer en su balcón.'::text),
(401873,44653,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle arrose ses plantes avec l''arrosoir ... sur son balcon.'::text,'au coucher du soleil'::text,'au coucher du soleil'::text,'dans un coucher de soleil'::text,'Elle arrose ses plantes avec l''arrosoir au coucher du soleil sur son balcon.'::text),
(401876,44653,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, balkonunda bitkilerini sulama kabıyla ... suluyor.'::text,'gün batımında'::text,'gün batımında'::text,'bir gün batımında'::text,'O, balkonunda bitkilerini sulama kabıyla gün batımında suluyor.'::text),
(401877,44653,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... meglocsolja a növényeit a locsolókannával az erkélyén.'::text,'naplementekor'::text,'a naplementekor'::text,'egy naplementében'::text,'Ő naplementekor meglocsolja a növényeit a locsolókannával az erkélyén.'::text),
(352326,39148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Abschied ... von den Leuten am Kai, weil sie diejenigen waren, die winkten.'::text,'wurde gegeben'::text,'gab'::text,'gibt'::text,'Der Abschied wurde gegeben von den Leuten am Kai, weil sie diejenigen waren, die winkten.'::text),
(352330,39148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прощання ... людьми на набережній, бо саме вони махали.'::text,'було влаштоване'::text,'влаштувало'::text,'влаштовує'::text,'Прощання було влаштоване людьми на набережній, бо саме вони махали.'::text),
(352329,39148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La despedida ... por la gente del muelle, porque eran ellos los que saludaban.'::text,'fue dada'::text,'dio'::text,'está dando'::text,'La despedida fue dada por la gente del muelle, porque eran ellos los que saludaban.'::text),
(352328,39148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''adieu ... par les gens sur le quai, parce que c''étaient eux qui faisaient signe.'::text,'a été fait'::text,'a fait'::text,'fait'::text,'L''adieu a été fait par les gens sur le quai, parce que c''étaient eux qui faisaient signe.'::text),
(352331,39148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Veda rıhtımdaki insanlar tarafından ..., çünkü el sallayanlar onlardı.'::text,'edildi'::text,'etti'::text,'ediyor'::text,'Veda rıhtımdaki insanlar tarafından edildi, çünkü el sallayanlar onlardı.'::text),
(352332,39148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A búcsút a rakparton álló emberek ..., mert ők voltak azok, akik integettek.'::text,'intették'::text,'intett'::text,'inti'::text,'A búcsút a rakparton álló emberek intették, mert ők voltak azok, akik integettek.'::text),
(352371,39153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, sie hat mir erzählt, dass sie dieser Fähre jeden Sonntag zum Abschied ...'::text,'winken'::text,'winken'::text,'gewinkt haben'::text,'Moment, sie hat mir erzählt, dass sie dieser Fähre jeden Sonntag zum Abschied winken.'::text),
(352375,39153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, вона сказала мені, що вони щонеділі ... цьому порому на прощання.'::text,'махають'::text,'махають'::text,'помахали'::text,'Стоп, вона сказала мені, що вони щонеділі махають цьому порому на прощання.'::text),
(352374,39153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, ella me dijo que ellos ... para despedir a este ferri cada domingo.'::text,'saludan'::text,'están saludando'::text,'han saludado'::text,'Espera, ella me dijo que ellos saludan para despedir a este ferri cada domingo.'::text),
(352373,39153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, elle m''a dit qu''ils ... d''adieu à ce ferry chaque dimanche.'::text,'font signe'::text,'font signe'::text,'ont fait signe'::text,'Attends, elle m''a dit qu''ils font signe d''adieu à ce ferry chaque dimanche.'::text),
(352376,39153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, o bana onların her pazar bu vapura veda için el ... söyledi.'::text,'salladıklarını'::text,'salladıklarını'::text,'salladıklarını'::text,'Dur, o bana onların her pazar bu vapura veda için el salladıklarını söyledi.'::text),
(352377,39153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, ő azt mondta nekem, hogy minden vasárnap ... búcsút ennek a kompnak.'::text,'intenek'::text,'intenek'::text,'intettek'::text,'Várj, ő azt mondta nekem, hogy minden vasárnap intenek búcsút ennek a kompnak.'::text),
(402411,44713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Unkraut lange Wurzeln hat, ... es schwer herauszuziehen.'::text,'ist'::text,'wird'::text,'war'::text,'Wenn ein Unkraut lange Wurzeln hat, ist es schwer herauszuziehen.'::text),
(402415,44713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бур''ян має довге коріння, його ... важко виривати.'::text,''::text,'буде'::text,'було'::text,'Якщо бур''ян має довге коріння, його важко виривати.'::text),
(402414,44713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tiene raíces largas, una mala hierba ... difícil de arrancar.'::text,'es'::text,'será'::text,'era'::text,'Si tiene raíces largas, una mala hierba es difícil de arrancar.'::text),
(402413,44713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une mauvaise herbe a de longues racines, elle ... difficile à arracher.'::text,'est'::text,'sera'::text,'était'::text,'Si une mauvaise herbe a de longues racines, elle est difficile à arracher.'::text),
(402416,44713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yabani ot uzun köklüyse, onu sökmek zor ...'::text,'olur'::text,'olacak'::text,'oldu'::text,'Yabani ot uzun köklüyse, onu sökmek zor olur.'::text),
(402417,44713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy gyomnak hosszú a gyökere, nehéz ... kihúzni.'::text,''::text,'lesz'::text,'volt'::text,'Ha egy gyomnak hosszú a gyökere, nehéz kihúzni.'::text),
(402501,44723,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er zog ... Unkraut im ganzen Beet aus der Erde.'::text,'das größte'::text,'ein größtes'::text,'größtes'::text,'Er zog das größte Unkraut im ganzen Beet aus der Erde.'::text),
(402505,44723,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він вирвав із землі ... бур''ян на всій грядці.'::text,'найбільший'::text,'найбільший'::text,'найбільший'::text,'Він вирвав із землі найбільший бур''ян на всій грядці.'::text),
(402504,44723,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él arrancó de la tierra ... mala hierba de todo el bancal.'::text,'la mayor'::text,'una mayor'::text,'mayor'::text,'Él arrancó de la tierra la mayor mala hierba de todo el bancal.'::text),
(402503,44723,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a arraché du sol ... mauvaise herbe de tout le carré.'::text,'la plus grosse'::text,'une plus grosse'::text,'plus grosse'::text,'Il a arraché du sol la plus grosse mauvaise herbe de tout le carré.'::text),
(402506,44723,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O bütün tarhtaki ... yabani otu topraktan söktü.'::text,'en büyük'::text,'bir en büyük'::text,'en büyük'::text,'O bütün tarhtaki en büyük yabani otu topraktan söktü.'::text),
(402507,44723,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő kihúzta a földből ... gyomot az egész ágyásban.'::text,'a legnagyobb'::text,'egy legnagyobb'::text,'legnagyobb'::text,'Ő kihúzta a földből a legnagyobb gyomot az egész ágyásban.'::text),
(402600,44734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gastgeber ... ihn so herzlich. Er war offensichtlich überhaupt nicht willkommen.'::text,'begrüßten'::text,'wurden begrüßt'::text,'begrüßend'::text,'Die Gastgeber begrüßten ihn so herzlich. Er war offensichtlich überhaupt nicht willkommen.'::text),
(402604,44734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господарі ... його так тепло. Він, очевидно, був зовсім не бажаним гостем.'::text,'привітали'::text,'були привітані'::text,'вітаючи'::text,'Господарі привітали його так тепло. Він, очевидно, був зовсім не бажаним гостем.'::text),
(402603,44734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los anfitriones lo ... con tanto cariño. Obviamente, él no era nada bienvenido.'::text,'recibieron'::text,'fueron recibidos'::text,'recibiendo'::text,'Los anfitriones lo recibieron con tanto cariño. Obviamente, él no era nada bienvenido.'::text),
(402602,44734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les hôtes ... si chaleureusement. Il n''était évidemment pas du tout le bienvenu.'::text,'l''ont accueilli'::text,'ont été accueillis'::text,'l''accueillant'::text,'Les hôtes l''ont accueilli si chaleureusement. Il n''était évidemment pas du tout le bienvenu.'::text),
(402605,44734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahipleri onu çok sıcak ...; belli ki o hiç hoş karşılanmamıştı.'::text,'karşıladı'::text,'karşılandı'::text,'karşılayarak'::text,'Ev sahipleri onu çok sıcak karşıladı; belli ki o hiç hoş karşılanmamıştı.'::text),
(402606,44734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazdák olyan melegen ... őt. Nyilvánvalóan egyáltalán nem volt szívesen látott vendég.'::text,'üdvözölték'::text,'üdvözölve lettek'::text,'üdvözölve'::text,'A házigazdák olyan melegen üdvözölték őt. Nyilvánvalóan egyáltalán nem volt szívesen látott vendég.'::text),
(402609,44735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er fühlte sich willkommen, ... er am geschnitzten Holztor ankam.'::text,'sobald'::text,'falls'::text,'außer wenn'::text,'Er fühlte sich willkommen, sobald er am geschnitzten Holztor ankam.'::text),
(402613,44735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він відчув себе бажаним гостем, ... прибув до різьблених дерев''яних воріт.'::text,'щойно'::text,'на випадок, якщо'::text,'хіба що'::text,'Він відчув себе бажаним гостем, щойно прибув до різьблених дерев''яних воріт.'::text),
(402612,44735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él se sintió bienvenido ... llegó a la puerta de madera tallada.'::text,'en cuanto'::text,'por si'::text,'a menos que'::text,'Él se sintió bienvenido en cuanto llegó a la puerta de madera tallada.'::text),
(402611,44735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il s''est senti le bienvenu ... il est arrivé à la porte en bois sculpté.'::text,'dès l''instant où'::text,'au cas où'::text,'à moins que'::text,'Il s''est senti le bienvenu dès l''instant où il est arrivé à la porte en bois sculpté.'::text),
(402614,44735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O oyma ahşap kapıya ... kendini hoş karşılanmış hissetti.'::text,'varır varmaz'::text,'varırsa diye'::text,'varmadıkça'::text,'O oyma ahşap kapıya varır varmaz kendini hoş karşılanmış hissetti.'::text),
(402615,44735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő szívesen látottnak érezte magát, ... megérkezett a faragott fa kapuhoz.'::text,'amint'::text,'arra az esetre, ha'::text,'hacsak nem'::text,'Ő szívesen látottnak érezte magát, amint megérkezett a faragott fa kapuhoz.'::text),
(361353,40151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, ich hab gehört, der Typ, ... all die Naben gefilmt hat, arbeitet in einem Fahrradladen.'::text,'der'::text,'was'::text,'dessen'::text,'Moment, ich hab gehört, der Typ, der all die Naben gefilmt hat, arbeitet in einem Fahrradladen.'::text),
(361357,40151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп, я чула, що хлопець, ... знімав усі ті втулки, працює у веломагазині.'::text,'який'::text,'котрий'::text,'чий'::text,'Стоп, я чула, що хлопець, який знімав усі ті втулки, працює у веломагазині.'::text),
(361356,40151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, oí que el chico ... grabó todos esos bujes trabaja en una tienda de bicis.'::text,'que'::text,'el cual'::text,'cuyo'::text,'Espera, oí que el chico que grabó todos esos bujes trabaja en una tienda de bicis.'::text),
(361355,40151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, j''ai entendu dire que le mec ... a filmé tous ces moyeux bosse dans un magasin de vélos.'::text,'qui'::text,'lequel'::text,'dont'::text,'Attends, j''ai entendu dire que le mec qui a filmé tous ces moyeux bosse dans un magasin de vélos.'::text),
(361358,40151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, duydum ki bütün o göbekleri ... çeken adam bir bisiklet dükkânında çalışıyormuş.'::text,''::text,NULL::text,NULL::text,'Dur, duydum ki bütün o göbekleri çeken adam bir bisiklet dükkânında çalışıyormuş.'::text),
(361359,40151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, azt hallottam, hogy a srác, ... az összes kerékagyat lefilmezte, egy bicikliboltban dolgozik.'::text,'aki'::text,'amely'::text,'akinek'::text,'Várj, azt hallottam, hogy a srác, aki az összes kerékagyat lefilmezte, egy bicikliboltban dolgozik.'::text),
(361407,40157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein ganz normaler Tag: Er ... stundenlang Naben, bevor er die größte von allen fand.'::text,'studierte'::text,'studierte'::text,'studiert'::text,'Ein ganz normaler Tag: Er studierte stundenlang Naben, bevor er die größte von allen fand.'::text),
(361411,40157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цілком звичайний день: він ... втулки годинами, поки не знайшов найбільшу з усіх.'::text,'вивчав'::text,'вивчав'::text,'вивчає'::text,'Цілком звичайний день: він вивчав втулки годинами, поки не знайшов найбільшу з усіх.'::text),
(361410,40157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un día de lo más normal: él ... bujes durante horas antes de encontrar el más grande de todos.'::text,'había estado estudiando'::text,'estaba estudiando'::text,'ha estado estudiando'::text,'Un día de lo más normal: él había estado estudiando bujes durante horas antes de encontrar el más grande de todos.'::text),
(361409,40157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une journée très ordinaire : il ... des moyeux pendant des heures avant de trouver le plus gros de tous.'::text,'avait étudié'::text,'étudiait'::text,'a étudié'::text,'Une journée très ordinaire : il avait étudié des moyeux pendant des heures avant de trouver le plus gros de tous.'::text),
(361412,40157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok sıradan bir gün: o en büyüğünü bulmadan önce saatlerce göbekleri ...'::text,'incelemişti'::text,'inceliyordu'::text,'inceledi'::text,'Çok sıradan bir gün: o en büyüğünü bulmadan önce saatlerce göbekleri incelemişti.'::text),
(361413,40157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy teljesen hétköznapi nap: ő órákig ... a kerékagyakat, mielőtt megtalálta a legnagyobbat.'::text,'tanulmányozta'::text,'tanulmányozta'::text,'tanulmányozza'::text,'Egy teljesen hétköznapi nap: ő órákig tanulmányozta a kerékagyakat, mielőtt megtalálta a legnagyobbat.'::text),
(347727,38637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann mit Behinderung, ... seinen Rollstuhl selbst antreibt, rollt schnell den laubbedeckten Weg entlang.'::text,'der'::text,'welches'::text,'dessen'::text,'Der Mann mit Behinderung, der seinen Rollstuhl selbst antreibt, rollt schnell den laubbedeckten Weg entlang.'::text),
(347731,38637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік з інвалідністю, ... сам штовхає свій візок, швидко котиться стежкою в листі.'::text,'який'::text,'котре'::text,'чий'::text,'Чоловік з інвалідністю, який сам штовхає свій візок, швидко котиться стежкою в листі.'::text),
(347730,38637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre con discapacidad, ... empuja su propia silla de ruedas, rueda rápido por el camino lleno de hojas.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El hombre con discapacidad, que empuja su propia silla de ruedas, rueda rápido por el camino lleno de hojas.'::text),
(347729,38637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme handicapé, ... pousse lui-même son fauteuil roulant, file sur le chemin couvert de feuilles.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''homme handicapé, qui pousse lui-même son fauteuil roulant, file sur le chemin couvert de feuilles.'::text),
(347732,38637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendi tekerlekli sandalyesini ... iten engelli adam, yapraklı yolda hızla ilerliyor.'::text,''::text,NULL::text,NULL::text,'Kendi tekerlekli sandalyesini iten engelli adam, yapraklı yolda hızla ilerliyor.'::text),
(347733,38637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A mozgássérült férfi, ... maga hajtja a kerekesszékét, gyorsan gurul a leveles ösvényen.'::text,'aki'::text,'amely'::text,'akinek'::text,'A mozgássérült férfi, aki maga hajtja a kerekesszékét, gyorsan gurul a leveles ösvényen.'::text),
(337989,37555,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Team ... die Kandidatin auf die Schultern. Eine sehr ruhige Nacht, logisch.'::text,'hob'::text,'wurde gehoben'::text,'hebend'::text,'Ihr Team hob die Kandidatin auf die Schultern. Eine sehr ruhige Nacht, logisch.'::text),
(337993,37555,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її команда ... кандидатку на плечі. Дуже тиха ніч, очевидно.'::text,'підняла'::text,'була піднята'::text,'піднімаючи'::text,'Її команда підняла кандидатку на плечі. Дуже тиха ніч, очевидно.'::text),
(337992,37555,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su equipo ... a la candidata a hombros. Una noche muy tranquila, obviamente.'::text,'levantó'::text,'fue levantado'::text,'levantando'::text,'Su equipo levantó a la candidata a hombros. Una noche muy tranquila, obviamente.'::text),
(337991,37555,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son équipe ... la candidate sur ses épaules. Une nuit très calme, évidemment.'::text,'a porté'::text,'a été portée'::text,'portant'::text,'Son équipe a porté la candidate sur ses épaules. Une nuit très calme, évidemment.'::text),
(337994,37555,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekibi adayı omuzlarına ...; çok sakin bir gece, tabii ki.'::text,'kaldırdı'::text,'kaldırıldı'::text,'kaldırarak'::text,'Ekibi adayı omuzlarına kaldırdı; çok sakin bir gece, tabii ki.'::text),
(337995,37555,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csapata a vállára ... a jelöltet. Nagyon csendes éjszaka, nyilván.'::text,'emelte'::text,'emelve lett'::text,'emelve'::text,'A csapata a vállára emelte a jelöltet. Nagyon csendes éjszaka, nyilván.'::text),
(396903,44101,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, dass er das Holz am Tag davor zu Brettern ...'::text,'gesägt hatte'::text,'gesägt hat'::text,'sägt'::text,'Er sagte, dass er das Holz am Tag davor zu Brettern gesägt hatte.'::text),
(396907,44101,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що напередодні ... деревину на дошки.'::text,'розпиляв'::text,'розпиляв'::text,'пиляє'::text,'Він сказав, що напередодні розпиляв деревину на дошки.'::text),
(396906,44101,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Él dijo que ... la madera en tablones el día anterior.'::text,'había cortado'::text,'ha cortado'::text,'corta'::text,'Él dijo que había cortado la madera en tablones el día anterior.'::text),
(396905,44101,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... le bois en planches la veille.'::text,'avait coupé'::text,'a coupé'::text,'coupe'::text,'Il a dit qu''il avait coupé le bois en planches la veille.'::text),
(396908,44101,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, keresteyi bir gün önce tahtalara ... söyledi.'::text,'kestiğini'::text,'kestiğini'::text,'kestiğini'::text,'O, keresteyi bir gün önce tahtalara kestiğini söyledi.'::text),
(396909,44101,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő azt mondta, hogy előző nap ... a fát deszkákra.'::text,'felvágta'::text,'felvágta'::text,'vágja'::text,'Ő azt mondta, hogy előző nap felvágta a fát deszkákra.'::text),
(361983,40221,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Maschinen sind riesig, also ... diese Fabrik zur Schwerindustrie gehören.'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Die Maschinen sind riesig, also muss diese Fabrik zur Schwerindustrie gehören.'::text),
(361987,40221,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ті машини величезні, тож ця фабрика ... бути частиною важкої промисловості.'::text,'мусить'::text,'може'::text,'не може'::text,'Ті машини величезні, тож ця фабрика мусить бути частиною важкої промисловості.'::text),
(361986,40221,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esas máquinas son enormes, así que esta fábrica ... formar parte de la industria pesada.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Esas máquinas son enormes, así que esta fábrica debe de formar parte de la industria pesada.'::text),
(361985,40221,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces machines sont énormes, donc cette usine ... faire partie de l''industrie lourde.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Ces machines sont énormes, donc cette usine doit faire partie de l''industrie lourde.'::text),
(361988,40221,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O makineler devasa, yani bu fabrika ağır sanayinin parçası ...'::text,'olmalı'::text,'olabilir'::text,'olamaz'::text,'O makineler devasa, yani bu fabrika ağır sanayinin parçası olmalı.'::text),
(361989,40221,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a gépek hatalmasak, szóval ez a gyár ... a nehézipar része.'::text,'biztosan'::text,'talán'::text,'biztosan nem'::text,'Azok a gépek hatalmasak, szóval ez a gyár biztosan a nehézipar része.'::text),
(392556,43618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... jede Kiste auf die Palette, bevor du sie ins Lager gezogen hast.'::text,'stapeltest'::text,'stapeltest'::text,'stapelst'::text,'Ehrlich, du stapeltest jede Kiste auf die Palette, bevor du sie ins Lager gezogen hast.'::text),
(392560,43618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... кожну коробку на той піддон, перш ніж відтягнула його на склад.'::text,'склала'::text,'склала'::text,'складаєш'::text,'Чесно, ти склала кожну коробку на той піддон, перш ніж відтягнула його на склад.'::text),
(392559,43618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, tú ... cada caja en ese palé antes de llevarlo al almacén.'::text,'habías apilado'::text,'has apilado'::text,'apilas'::text,'Sinceramente, tú habías apilado cada caja en ese palé antes de llevarlo al almacén.'::text),
(392558,43618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... chaque carton sur cette palette avant de la tirer jusqu''à l''entrepôt.'::text,'avais empilé'::text,'as empilé'::text,'empiles'::text,'Franchement, tu avais empilé chaque carton sur cette palette avant de la tirer jusqu''à l''entrepôt.'::text),
(392561,43618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası sen o paleti depoya çekmeden önce her kutuyu üstüne ...'::text,'dizmiştin'::text,'dizdin'::text,'diziyorsun'::text,'Açıkçası sen o paleti depoya çekmeden önce her kutuyu üstüne dizmiştin.'::text),
(392562,43618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, te ... minden dobozt arra a raklapra, mielőtt a raktárba húztad.'::text,'felpakoltál'::text,'felpakoltál'::text,'pakolsz'::text,'Őszintén, te felpakoltál minden dobozt arra a raklapra, mielőtt a raktárba húztad.'::text),
(392610,43624,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Palette in Folie, bevor sie sie ins Lager zog.'::text,'wickelte'::text,'wickelte'::text,'wickelte gerade'::text,'Sie wickelte die Palette in Folie, bevor sie sie ins Lager zog.'::text),
(392614,43624,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... піддон у плівку, перш ніж відтягнула його на склад.'::text,'обмотала'::text,'обмотала'::text,'обмотувала'::text,'Вона обмотала піддон у плівку, перш ніж відтягнула його на склад.'::text),
(392613,43624,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el palé en film plástico antes de llevarlo al almacén.'::text,'había envuelto'::text,'ha envuelto'::text,'estaba envolviendo'::text,'Ella había envuelto el palé en film plástico antes de llevarlo al almacén.'::text),
(392612,43624,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la palette de film plastique avant de la tirer jusqu''à l''entrepôt.'::text,'avait emballé'::text,'a emballé'::text,'emballait'::text,'Elle avait emballé la palette de film plastique avant de la tirer jusqu''à l''entrepôt.'::text),
(392615,43624,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O paleti depoya çekmeden önce streç filme ...'::text,'sarmıştı'::text,'sardı'::text,'sarıyordu'::text,'O paleti depoya çekmeden önce streç filme sarmıştı.'::text),
(392616,43624,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a raklapot fóliába, mielőtt a raktárba húzta.'::text,'becsomagolta'::text,'becsomagolta'::text,'csomagolta'::text,'Ő becsomagolta a raklapot fóliába, mielőtt a raktárba húzta.'::text),
(375906,41768,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du eine Position so selbstbewusst ..., fällt das den Leuten immer auf. Respekt.'::text,'hältst'::text,'halten wirst'::text,'hieltest'::text,'Wenn du eine Position so selbstbewusst hältst, fällt das den Leuten immer auf. Respekt.'::text),
(375910,41768,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли ти ... позу так упевнено, люди завжди це помічають. Респект.'::text,'тримаєш'::text,'триматимеш'::text,'тримала'::text,'Коли ти тримаєш позу так упевнено, люди завжди це помічають. Респект.'::text),
(375909,41768,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú ... una postura con tanta seguridad, la gente siempre lo nota. Respeto.'::text,'mantienes'::text,'mantendrás'::text,'mantuviste'::text,'Si tú mantienes una postura con tanta seguridad, la gente siempre lo nota. Respeto.'::text),
(375908,41768,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ... une position avec autant d''assurance, les gens le remarquent toujours. Respect.'::text,'tiens'::text,'tiendras'::text,'tenais'::text,'Si tu tiens une position avec autant d''assurance, les gens le remarquent toujours. Respect.'::text),
(375911,41768,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen bir pozisyonu o kadar kendinden emin ..., insanlar hep fark eder. Saygı.'::text,'tutarsan'::text,'tutacaksan'::text,'tuttuysan'::text,'Sen bir pozisyonu o kadar kendinden emin tutarsan, insanlar hep fark eder. Saygı.'::text),
(375912,41768,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te ilyen magabiztosan ... egy pozíciót, az emberek mindig észreveszik. Respekt.'::text,'tartasz'::text,'fogsz tartani'::text,'tartottál'::text,'Ha te ilyen magabiztosan tartasz egy pozíciót, az emberek mindig észreveszik. Respekt.'::text),
(384825,42759,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du einen handgeschriebenen Brief schickst, ... die Leute ihn für immer, ehrlich.'::text,'behalten'::text,'behalten'::text,'behielten'::text,'Wenn du einen handgeschriebenen Brief schickst, behalten die Leute ihn für immer, ehrlich.'::text),
(384829,42759,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти надсилаєш рукописний лист, люди ... його назавжди, чесно.'::text,'зберігають'::text,'збережуть'::text,'зберегли'::text,'Якщо ти надсилаєш рукописний лист, люди зберігають його назавжди, чесно.'::text),
(384828,42759,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tú mandas una carta escrita a mano, la gente la ... para siempre, sinceramente.'::text,'guarda'::text,'guardará'::text,'guardó'::text,'Si tú mandas una carta escrita a mano, la gente la guarda para siempre, sinceramente.'::text),
(384827,42759,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu envoies une lettre écrite à la main, les gens la ... pour toujours, franchement.'::text,'gardent'::text,'garderont'::text,'ont gardée'::text,'Si tu envoies une lettre écrite à la main, les gens la gardent pour toujours, franchement.'::text),
(384830,42759,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sen el yazısıyla bir mektup gönderirsen insanlar onu sonsuza dek ..., açıkçası.'::text,'saklar'::text,'saklayacak'::text,'sakladı'::text,'Sen el yazısıyla bir mektup gönderirsen insanlar onu sonsuza dek saklar, açıkçası.'::text),
(384831,42759,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha te kézzel írt levelet küldesz, az emberek örökre ..., őszintén.'::text,'megtartják'::text,'meg fogják tartani'::text,'megtartották'::text,'Ha te kézzel írt levelet küldesz, az emberek örökre megtartják, őszintén.'::text),
(353109,39235,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Medizinerin sagte, dass der Film eine Stunde vorher aus dem Labor geschickt worden ...'::text,'war'::text,'ist'::text,'wird'::text,'Die Medizinerin sagte, dass der Film eine Stunde vorher aus dem Labor geschickt worden war.'::text),
(353113,39235,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медикиня сказала, що плівку ... з лабораторії за годину до того.'::text,'надіслали'::text,'надіслали'::text,'надсилають'::text,'Медикиня сказала, що плівку надіслали з лабораторії за годину до того.'::text),
(353112,39235,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médica dijo que la placa ... enviada desde el laboratorio una hora antes.'::text,'había sido'::text,'ha sido'::text,'es'::text,'La médica dijo que la placa había sido enviada desde el laboratorio una hora antes.'::text),
(353111,39235,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La médecin a dit que le film ... envoyé du labo une heure avant.'::text,'avait été'::text,'a été'::text,'est'::text,'La médecin a dit que le film avait été envoyé du labo une heure avant.'::text),
(353114,39235,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sağlıkçı, filmin bir saat önce laboratuvardan ... söyledi.'::text,'gönderilmiş olduğunu'::text,'gönderildiğini'::text,'gönderildiğini'::text,'Sağlıkçı, filmin bir saat önce laboratuvardan gönderilmiş olduğunu söyledi.'::text),
(353115,39235,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az orvos azt mondta, hogy a filmet egy órával korábban ... a laborból.'::text,'küldték'::text,'küldték'::text,'küldik'::text,'Az orvos azt mondta, hogy a filmet egy órával korábban küldték a laborból.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
where l.id = v.id and l.exercise_id = v.eid and l.language_code = v.lang and l.intro_text is not distinct from v.o_intro_text and l.correct_answer is not distinct from v.o_correct_answer and l.distractor_1 is not distinct from v.o_distractor_1 and l.distractor_2 is not distinct from v.o_distractor_2 and l.full_sentence is not distinct from v.o_full_sentence
returning l.id;
